const a={"les-n5-u01-01":{pedagogical_framework:{what:{summary:"Pola predikat nominal afirmatif 〜は〜です dan penanda topik は (wa).",canDo:"Bisa menyebutkan nama, asal negara, dan profesi diri secara sopan saat perjumpaan pertama.",targetPatterns:["〜は〜です","は (topik)"],coreVocabSample:["わたし","なまえ","がくせい","かいしゃいん","エンジニア","インドネシア"]},sensei_context:{sceneIntro:"Bayangkan kamu baru saja mendarat di Jepang untuk bekerja atau belajar. Langkah pertamamu adalah mendatangi balai kota (Kuyakusho) untuk mendaftarkan alamat tinggal dan berkenalan dengan staf loket.",dailyMission:"Mampu menyebutkan nama, asal negara, dan profesi dirimu dengan percaya diri, ramah, dan santun tanpa rasa canggung.",whyOrder:"Kenapa pola ini dipelajari pertama kali? Karena otak kita jauh lebih mudah merakit pola kalimat dasar [Subjek + adalah + Predikat] sebelum masuk ke perubahan kata kerja yang bercabang-cabang. Pola ini adalah pondasi dari 80% komunikasi awal di Jepang."},cultural_notes:{title:"Etika Perkenalan Pertama (Jikoshoukai) di Jepang",etiquette:'Saat mengucapkan "Hajimemashite" dan "Douzo yoroshiku", tundukkan badan sekitar 15 derajat (Eshaku) dengan kedua tangan di samping paha (pria) atau di depan perut (wanita). Jangan pernah menambahkan akhiran gelar "-san" pada nama dirimu sendiri!',taboos:'Dalam percakapan sehari-hari, orang Jepang sering menghilangkan subjek atau menyebut nama/jabatan + さん. Sebutan "anata" dapat terdengar berjarak atau terlalu langsung dalam konteks interpersonal tertentu (meski lazim di kuesioner tertulis atau lagu). Untuk kenalan baru, lebih aman dan santun memanggil nama keluarga lawan bicara diikuti gelar "-san" (misal: Tanaka-san).'},pronunciation_tips:{title:"Tips Pelafalan Alami untuk Lidah Indonesia",moraNote:"Bahasa Jepang memakai ketukan waktu yang rata (mora), bukan suku kata yang ditekan keras-lemah.",soundTip:`Bunyi "su" pada akhiran "desu" dilafalkan sangat tipis dan terbisukan laksana embusan napas (des'), jangan dibaca tebal atau ditekan seperti kata "desa" dalam bahasa Indonesia.`},common_pitfalls:[{title:'Jebakan Kata "Adalah" (Struktur SVO Indonesia vs SOV Jepang)',caseScenario:'Menerjemahkan kata "adalah" di tengah kalimat seperti susunan bahasa Indonesia.',pitfallWarning:'"わたしは です ブディ。" (Watashi wa desu Budi)',rightSolution:'"わたしは ブディ です。" (Watashi wa Budi desu)',explanation:'Di bahasa Indonesia kita meletakkan "adalah" di tengah kalimat. Namun dalam kalimat pernyataan dasar bahasa Jepang, "desu" berfungsi menutup predikat sopan (dapat diikuti partikel penanya/penegas seperti "ka", "yo", atau "ne").'},{title:'Pantangan Menempelkan Gelar "-san" ke Diri Sendiri',caseScenario:"Memperkenalkan nama diri dengan embel-embel sopan.",pitfallWarning:'"わたしは ブディさん です。" (Watashi wa Budi-san desu)',rightSolution:'"わたしは ブディ です。" (Watashi wa Budi desu)',explanation:'Gelar "-san" adalah tanda penghormatan eksklusif untuk orang lain. Menggunakannya untuk diri sendiri terdengar sombong dan janggal bagi telinga orang Jepang.'}],who_and_when:{situational_context:"Perkenalan pertama kali (Jikoshoukai), registrasi administrasi balai kota, orientasi kerja, atau menyapa tetangga baru.",social_relations:"Digunakan kepada orang yang baru dikenal, rekan kerja sejawat, atau staf pelayanan publik dalam ragam kesopanan standar (Teineigo).",when_not_to_use:'Hindari menggunakan kata ganti "anata" secara sembarangan kepada orang yang baru dikenal.'},scenario:{title:"Registrasi Kependudukan di Balai Kota Shinjuku",setting:"Loket Pendaftaran Penduduk, Kuyakusho Tokyo",narrative:"Budi baru saja mendarat di Jepang untuk bekerja. Dia mendatangi loket balai kota dan memperkenalkan identitas dirinya kepada Tanaka-san, petugas loket."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Petugas Balai Kota",avatar:"🧑‍💼",jp:"こんにちは。はじめまして。田中【たなか】です。",furigana:"こんにちは。はじめまして。田中です。",romaji:"Konnichiwa. Hajimemashite. Tanaka desu.",idText:"Halo selamat siang. Salam kenal. Saya Tanaka.",note:"Menunduk hormat 15 derajat (Eshaku)"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はじめまして。私【わたし】は ブディです。どうぞ よろしく お願【ねが】いします。",furigana:"はじめまして。私は ブディです。どうぞ よろしく お願いします。",romaji:"Hajimemashite. Watashi wa Budi desu. Douzo yoroshiku onegaishimasu.",idText:"Salam kenal. Saya Budi. Senang berkenalan dengan Anda, mohon bimbingannya."},{id:"d3",speaker:"Tanaka",speakerRole:"Petugas Balai Kota",avatar:"🧑‍💼",jp:"ブディさんは、どちらから 来【き】ましたか。",furigana:"ブディさんは、どちらから 来ましたか。",romaji:"Budi-san wa, dochira kara kimashita ka.",idText:"Budi-san datang dari mana (asal negara/daerah)?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"インドネシアから 来【き】ました。ジャカルタの 出身【しゅっしん】です。",furigana:"インドネシアから 来ました。ジャカルタの 出身です。",romaji:"Indoneshia kara kimashita. Jakaruta no shusshin desu.",idText:"Saya datang dari Indonesia. Asal saya dari Jakarta."},{id:"d5",speaker:"Tanaka",speakerRole:"Petugas Balai Kota",avatar:"🧑‍💼",jp:"そうですか。ブディさんは、学生【がくせい】ですか。",furigana:"そうですか。ブディさんは、学生ですか。",romaji:"Sou desu ka. Budi-san wa, gakusei desu ka.",idText:"Begitu ya. Apakah Budi-san seorang mahasiswa/pelajar?",note:"Mengangguk ramah (Aizuchi)"},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"いいえ、学生【がくせい】じゃ ありません。会社員【かいしゃいん】です。エンジニアです。",furigana:"いいえ、学生じゃ ありません。会社員です。エンジニアです。",romaji:"Iie, gakusei ja arimasen. Kaishain desu. Enjinia desu.",idText:"Bukan, saya bukan mahasiswa. Saya karyawan perusahaan. Saya seorang engineer."},{id:"d7",speaker:"Tanaka",speakerRole:"Petugas Balai Kota",avatar:"🧑‍💼",jp:"エンジニアですね。素晴【すば】らしいです。ようこそ 日本【にほん】へ！",furigana:"エンジニアですね。素晴らしいです。ようこそ 日本へ！",romaji:"Enjinia desu ne. Subarashii desu. Youkoso Nihon e!",idText:"Insinyur ya. Luar biasa. Selamat datang di Jepang!"}],vocab_breakdown:[{id:"v1",word:"わたし",reading:"わたし",romaji:"watashi",meaning:"Saya (kata ganti orang pertama netral & sopan)",nuance:"Paling aman dan standar digunakan oleh pria maupun wanita dalam situasi formal, kerja, dan sosial umum.",particleTip:"Biasa dipasangkan dengan partikel は (watashi wa) untuk memulai perkenalan.",exampleSentence:{jp:"わたしは エンジニアです。",furigana:"私は エンジニアです。",romaji:"Watashi wa enjinia desu.",idText:"Saya adalah seorang insinyur."}},{id:"v2",word:"なまえ",reading:"なまえ",romaji:"namae",meaning:"Nama",nuance:'Jika bertanya nama orang lain, tambahkan awalan penghormatan "o-" menjadi "O-namae wa?" (お名前). Jangan gunakan "o-" untuk nama diri sendiri.',particleTip:"おなまえは なんですか。(Siapa nama Anda?)",exampleSentence:{jp:"おなまえは なんですか。",furigana:"お名前は 何ですか。",romaji:"Onamae wa nan desu ka.",idText:"Siapa nama Anda?"}},{id:"v3",word:"がくせい",reading:"がくせい",romaji:"gakusei",meaning:"Pelajar / Mahasiswa",nuance:"Menyebutkan status pendidikan secara umum, mulai dari sekolah kejuruan hingga universitas.",particleTip:"がくせいです。(Saya seorang pelajar.)",exampleSentence:{jp:"たなかさんは がくせいですか。",furigana:"田中さんは 学生ですか。",romaji:"Tanaka-san wa gakusei desu ka.",idText:"Apakah Tanaka-san seorang pelajar?"}},{id:"v4",word:"かいしゃいん",reading:"かいしゃいん",romaji:"kaishain",meaning:"Karyawan Perusahaan / Pegawai Kantor",nuance:'Dipakai saat menyebut profesi diri ("Saya karyawan"). Jika menyebut nama kantor tertentu, gunakan kata "shain" (misal: Toyota no shain).',particleTip:"かいしゃいんです。(Saya karyawan kantor.)",exampleSentence:{jp:"わたしは かいしゃいんです。",furigana:"私は 会社員です。",romaji:"Watashi wa kaishain desu.",idText:"Saya adalah seorang karyawan perusahaan."}},{id:"v5",word:"エンジニア",reading:"エンジニア",romaji:"enjinia",meaning:"Insinyur / Software Engineer / Teknisi",nuance:"Kata serapan bahasa asing yang ditulis dengan aksara Katakana.",particleTip:"ITの エンジニアです。(Saya insinyur IT.)",exampleSentence:{jp:"ブディさんは エンジニアです。",furigana:"ブディさんは エンジニアです。",romaji:"Budi-san wa enjinia desu.",idText:"Budi-san adalah seorang insinyur."}},{id:"v6",word:"せんせい",reading:"せんせい",romaji:"sensei",meaning:"Guru / Dosen / Dokter / Pengajar Terhormat",nuance:'Gelar penghormatan untuk profesi pendidik atau dokter. Pantang menyebut diri sendiri "watashi wa sensei desu" di depan umum; gunakan "kyoushi" untuk profesi diri.',particleTip:"たなかせんせい (Tanaka-sensei / Pak Guru Tanaka).",exampleSentence:{jp:"たなかさんは せんせいです。",furigana:"田中さんは 先生です。",romaji:"Tanaka-san wa sensei desu.",idText:"Tanaka-san adalah seorang guru."}},{id:"v7",word:"インドネシア",reading:"インドネシア",romaji:"indoneshia",meaning:"Negara Indonesia",nuance:'Untuk menyatakan warga negara Indonesia, cukup tambahkan akhiran "jin" (インドネシアじん).',particleTip:"インドネシアから きました。(Saya datang dari Indonesia.)",exampleSentence:{jp:"わたしは インドネシアじんです。",furigana:"私は インドネシア人です。",romaji:"Watashi wa indoneshiajin desu.",idText:"Saya adalah orang Indonesia."}},{id:"v8",word:"にほん",reading:"にほん",romaji:"nihon",meaning:"Negara Jepang",nuance:"Negara Jepang. Sering juga dilafalkan にっぽん (nippon) dalam konteks formal, acara resmi, atau uang koin. Orang Jepang = にほんじん (nihonjin). Bahasa Jepang = にほんご (nihongo).",particleTip:"にほんへ ようこそ！(Selamat datang di Jepang!)",exampleSentence:{jp:"たなかさんは にほんじんです。",furigana:"田中さんは 日本人です。",romaji:"Tanaka-san wa nihonjin desu.",idText:"Tanaka-san adalah orang Jepang."}}],explanations:[{id:"exp1",grammarId:"gn5-00001",title:"Pola Predikat Identitas Sopan: 〜は〜です",formula:"[Subjek/Topik] は [Predikat Kata Benda] です",meaning:"Menyatakan identitas diri, nama, kebangsaan, atau profesi secara santun dan terhormat.",nuanceNotes:"Struktur dasar paling penting dalam bahasa Jepang. Menghubungkan topik pembicaraan dengan identitasnya di depan lawan bicara.",patternLogic:'Orang Jepang berpikir dengan cara: "Mengenai [Topik], ia adalah [Predikat]". Karena itu, topik diangkat terlebih dahulu menggunakan partikel は, lalu identitasnya dikunci dengan akhiran kesopanan です di ujung kalimat.',particleNotes:'Partikel penanda topik は ditulis menggunakan huruf hiragana "ha", namun KHUSUS saat berfungsi sebagai partikel penanda topik kalimat, bunyinya wajib dibaca "wa".',formVariations:[{label:"Bentuk Positif (Afirmatif)",jp:"わたしは ブディです。",idText:"Saya adalah Budi."},{label:"Bentuk Negatif (Penyangkal)",jp:"わたしは がくせいじゃ ありません。",idText:"Saya bukan pelajar."},{label:"Bentuk Tanya (Introgatif)",jp:"たなかさんは せんせいですか。",idText:"Apakah Tanaka-san seorang guru?"}],examples:[{jp:"わたしは エンジニアです。",furigana:"私は エンジニアです。",romaji:"Watashi wa enjinia desu.",idText:"Saya adalah seorang insinyur."},{jp:"たなかさんは にほんじんです。",furigana:"田中さんは 日本人です。",romaji:"Tanaka-san wa nihonjin desu.",idText:"Tanaka-san adalah orang Jepang."}],pairedExamples:[{speakerA:"Tanaka",jpA:"ブディさんは、がくせいですか。",idA:"Apakah Budi-san seorang mahasiswa?",speakerB:"Budi",jpB:"いいえ、がくせいじゃ ありません。エンジニアです。",idB:"Bukan, saya bukan mahasiswa. Saya seorang insinyur."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kontekstual): Manakah kata yang tepat untuk menyebut "karyawan perusahaan" bagi profesi diri?',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["かいしゃいん (kaishain)","せんせい (sensei)","がくせい (gakusei)","ぎんこういん (ginkouin)"],correctAnswer:"かいしゃいん (kaishain)",explanation:"Kaishain adalah sebutan tepat untuk karyawan perusahaan secara umum.",diagnosticFeedback:{"せんせい (sensei)":"Sensei berarti guru atau dokter, bukan karyawan perusahaan.","がくせい (gakusei)":"Gakusei berarti pelajar atau mahasiswa.","ぎnこういん (ginkouin)":"Ginkouin berarti pegawai bank secara spesifik.","ぎんこういん (ginkouin)":'Pilihan "ぎんこういん (ginkouin)" keliru karena tidak selaras dengan kaidah pola gn5-00001.'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pilihan Partikel): Pilih partikel penanda topik yang tepat untuk melengkapi kalimat perkenalan:",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["は","が","を","に"],correctAnswer:"は",explanation:'Partikel は (dibaca "wa") berfungsi mengangkat "watashi" sebagai topik kalimat.',diagnosticFeedback:{が:"Partikel が (ga) menandai subjek gramatikal spesifik atau penekanan fokus, kurang lazim untuk perkenalan identitas umum.",を:"Partikel を (wo) adalah penanda objek penderita kata kerja, bukan kalimat nominal desu.",に:"Partikel に (ni) menandai waktu, tempat tujuan, atau keberadaan."}},{id:"drill-3",type:"reorder",instruction:'Langkah 3 (Susun Kepingan Kalimat): Susun kepingan kata berikut menjadi kalimat: "Saya adalah karyawan perusahaan"',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["わたしは かいしゃいん です","かいしゃいん わたしは です","かいしゃいん です わたしは","わたしは です かいしゃいん"],correctAnswer:"わたしは かいしゃいん です",explanation:"Urutan bahasa Jepang selalu: Topik (watashi wa) + Predikat Benda (kaishain) + Kopula Sopan (desu).",diagnosticFeedback:{"かいしゃいん わたしは です":'Jebakan Susunan: Urutan kata pada frasa "かいしゃいん わたしは です" terbalik atau tidak selaras dengan struktur kalimat bahasa Jepang yang alami.',"かいしゃいん です わたしは":'Jebakan Susunan: Urutan kata pada frasa "かいしゃいん です わたしは" terbalik atau tidak selaras dengan struktur kalimat bahasa Jepang yang alami.',"わたしは です かいしゃいん":'Jebakan Susunan: Urutan kata pada frasa "わたしは です かいしゃいん" terbalik atau tidak selaras dengan struktur kalimat bahasa Jepang yang alami.'},tokens:["わたしは","かいしゃいん","です"],correctOrder:["0","1","2"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Kesalahan Umum): Kalimat manakah yang TIDAK PANTAS diucapkan saat berkenalan di Jepang?",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["わたしは ブディさん です。","わたしは ブディ です。","たなかさんは にほんじんです。"],correctAnswer:"わたしは ブディさん です。",explanation:'Gelar "-san" tidak boleh dipasang pada nama diri sendiri. Menyebut diri sendiri "Budi-san" terdengar janggal dan tidak sopan.',diagnosticFeedback:{"わたしは ブディ です。":"Kalimat ini 100% benar dan sopan untuk memperkenalkan diri.","たなかさんは にほんじんです。":'Kalimat ini benar karena memasang "-san" pada nama orang lain (Tanaka).'}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Percakapan Nyata): Petugas bertanya: "ブディさんは がくせいですか。". Jika kamu seorang insinyur, apa jawaban terbaikmu?',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["いいえ、がくせいじゃ ありません。エンジニアです。","はい、がくせいじゃ ありません。","わたしは です エンジニア。","いいえ、がくせいです。"],correctAnswer:"いいえ、がくせいじゃ ありません。エンジニアです。",explanation:'Menyangkal dengan "Iie, gakusei ja arimasen" lalu mengoreksi dengan profesi yang benar "Enjinia desu".',diagnosticFeedback:{"はい、がくせいじゃ ありません。":'Kontradiktif: "Hai" (Ya) tidak bisa dipasangkan dengan sangkalan negatif "ja arimasen".',"わたしは です エンジニア。":'Terbalik akibat terjemahan harfiah bahasa Indonesia; "desu" wajib berada di ujung kalimat.',"いいえ、がくせいです。":'Kontradiktif: "Iie" (Bukan) tidak cocok dengan penegasan positif "gakusei desu".'}}],can_do_challenge:{statement:"Mampu memperkenalkan nama, profesi, dan asal negara secara santun dan wajar saat pertama kali bertemu.",situation:'Kamu baru saja mendarat di Tokyo dan mendatangi loket balai kota (Kuyakusho). Staf loket menyapa: "Konnichiwa! Hajimemashite."',promptTask:"Ucapkan salam kenal, sebutkan namamu, sampaikan bahwa kamu berasal dari Indonesia, dan tutup dengan permohonan bimbingan yang santun!",modelAnswer:"はじめまして。わたしは [Nama] です。インドネシアから きました。どうぞ よろしく おねがいします。",modelAnswerId:"Hajimemashite. Watashi wa [Nama] desu. Indoneshia kara kimashita. Douzo yoroshiku onegaishimasu.",culturalEtiquette:"Ucapkan sambil membungkukkan badan sekitar 15 derajat (Eshaku) dengan senyum ramah dan kontak mata yang wajar.",skillUnlocked:["Bisa menyebutkan nama diri tanpa menyematkan -san","Bisa menyatakan kebangsaan dan asal negara","Bisa merangkai kalimat nominal sopan berakhiran desu"],pocketSummary:{keyFormula:"[Topik] は [Predikat] です",coreWords:["わたし (Saya)","なまえ (Nama)","かいしゃいん (Karyawan)"],coreWarning:'Jangan taruh "desu" di tengah kalimat & jangan panggil diri sendiri dengan "-san"!',quickDialogue:"A: おなまえは？ → B: わたしは ブディです。"}},pocket_summary:{keyFormula:"[Topik] は [Predikat] です",coreWords:["わたし (Saya)","なまえ (Nama)","かいしゃいん (Karyawan)"],coreWarning:'Jangan taruh "desu" di tengah kalimat & jangan panggil diri sendiri dengan "-san"!',quickDialogue:"A: おなまえは？ → B: わたしは ブディです。"}},"les-n5-u01-02":{pedagogical_framework:{what:{summary:"Bentuk negatif predikat 〜じゃありません dan partikel tanya か.",canDo:"Bisa menyangkal profesi/kewarganegaraan dan menanyakan identitas orang lain dengan sopan.",targetPatterns:["〜じゃありません","〜ですか"],coreVocabSample:["がくせい","せんせい","いしゃ","かいしゃいん","はい","いいえ"]},sensei_context:{sceneIntro:"Di kantor atau lingkungan baru, orang sering salah menebak profesi atau asalmu. Pelajaran ini melatihmu untuk meluruskan kesalahpahaman secara santun tanpa menyinggung perasaan lawan bicara.",dailyMission:"Mampu meluruskan status atau profesi diri dengan menyangkal secara halus dan bertanya balik mengenai identitas lawan bicara.",whyOrder:"Setelah pola kalimat positif (desu) kamu kuasai, otakmu siap beralih ke variasi seimbangannya: bentuk negatif (ja arimasen) dan bentuk pertanyaan (desu ka). Keduanya adalah kunci untuk membangun percakapan dua arah yang hidup."},cultural_notes:{title:"Etika Menolak & Menyangkal di Jepang",etiquette:'Jangan memotong ucapan lawan bicara dengan kata "Iie!" (Bukan/Tidak!) yang keras atau mendadak. Mulailah dengan nada yang lembut: "Iie, gakusei ja arimasen..." diikuti penjelasan yang sebenarnya.',taboos:'Dalam situasi resmi atau kerja, bentuk tulisan formal adalah "dewa arimasen". Dalam percakapan santun sehari-hari, "ja arimasen" adalah ragam yang paling umum dan alami.'},pronunciation_tips:{title:"Intonasi Pertanyaan Bahasa Jepang",moraNote:'Partikel "ka" di akhir kalimat berfungsi menggantikan tanda tanya (?).',soundTip:'Naikkan sedikit nada bicaramu pada suku kata terakhir "ka?" secara lembut, jangan berteriak atau terlalu tajam.'},common_pitfalls:[{title:"Ja Arimasen vs Bukan Bahasa Indonesia",caseScenario:'Mencoba membuat kalimat negatif dengan menyisipkan kata "bukan" di depan kata benda.',pitfallWarning:'"わたしは じゃない がくせい。" (Susunan kata salah)',rightSolution:'"わたしは がくせいじゃ ありません。" (Susunan kata benar)',explanation:'Di bahasa Jepang, penanda negatif "ja arimasen" SELALU ditaruh di belakang kata bendanya, bukan di depannya.'},{title:"Menjawab Pertanyaan Negatif dengan Iie Terbalik",caseScenario:'Menjawab pertanyaan negatif sopan seperti "Nihonjin ja arimasen ka?".',pitfallWarning:'Menjawab "Iie" dengan maksud mengiyakan sangkalan lawan bicara ala logika bahasa Indonesia.',rightSolution:'Menjawab "Hai, Nihonjin ja arimasen" (Benar, saya bukan orang Jepang).',explanation:'Dalam bahasa Jepang, "Hai" berarti membenarkan premis kalimat lawan bicara, sedangkan "Iie" berarti menyangkal premis kalimat lawan bicara.'}],who_and_when:{situational_context:"Klarifikasi data diri, wawancara kerja, menjawab pertanyaan formulir atau teman baru.",social_relations:"Sopan resmi (Teineigo) kepada siapa pun dalam situasi kerja atau publik.",when_not_to_use:'Hindari mengatakan "Iie!" secara ketus tanpa alasan pelunak ketika menolak.'},scenario:{title:"Verifikasi Identitas di Kantor Pos Tokyo",setting:"Loket Pengambilan Paket Yuubinkyoku",narrative:"Petugas kantor pos menanyakan apakah Budi seorang mahasiswa universitas setempat sebelum menyerahkan paket kiriman."}},dialogue:[{id:"d1",speaker:"Petugas Pos",speakerRole:"Staf Pos",avatar:"📮",jp:"ブディさんは、東京大学【とうきょうだいがく】の 学生【がくせい】ですか。",furigana:"ブディさんは、東京大学の 学生ですか。",romaji:"Budi-san wa, Toukyou daigaku no gakusei desu ka.",idText:"Apakah Budi-san mahasiswa Universitas Tokyo?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"いいえ、学生【がくせい】じゃ ありません。会社員【かいしゃいん】です。",furigana:"いいえ、学生じゃ ありません。会社員です。",romaji:"Iie, gakusei ja arimasen. Kaishain desu.",idText:"Bukan, saya bukan mahasiswa. Saya karyawan perusahaan."},{id:"d3",speaker:"Petugas Pos",speakerRole:"Staf Pos",avatar:"📮",jp:"あ、会社員【かいしゃいん】ですね。失礼【】しました。こちらに サインを お願【つれ】いします。",furigana:"あ、会社員ですね。失礼しました。こちらに サインを お願いします。",romaji:"A, kaishain desu ne. Shitsurei shimashita. Kochira ni sain wo onegaishimasu.",idText:"Oh, karyawan perusahaan ya. Maaf salah mengira. Mohon tanda tangan di sebelah sini."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、分【わ】かりました。ありがとうございます。",furigana:"はい、分かりました。ありがとうございます。",romaji:"Hai, wakarimashita. Arigatou gozaimasu.",idText:"Baik, saya mengerti. Terima kasih banyak."}],vocab_breakdown:[{id:"v1",word:"はい",reading:"はい",romaji:"hai",meaning:"Ya / Benar (jawaban afirmatif sopan)",nuance:"Jawaban sopan resmi. Menunjukkan kesiapan mendengarkan atau persetujuan.",exampleSentence:{jp:"はい、そうです。",furigana:"はい、そうです。",romaji:"Hai, sou desu.",idText:"Ya, benar demikian."}},{id:"v2",word:"いいえ",reading:"いいえ",romaji:"iie",meaning:"Tidak / Bukan (jawaban sangkalan sopan)",nuance:"Ucapkan dengan lembut saat mengoreksi informasi lawan bicara.",exampleSentence:{jp:"いいえ、ちがいます。",furigana:"いいえ、違います。",romaji:"Iie, chigaimasu.",idText:"Bukan, bukan begitu."}},{id:"v3",word:"いしゃ",reading:"いしゃ",romaji:"isha",meaning:"Dokter",nuance:"Profesi dokter = いしゃ (医者). Panggilan sopan dalam keseharian sering menggunakan お医者さん (おいしゃさん). Saat menyapa dokter yang memeriksa Anda secara langsung, gunakan せんせい (先生).",exampleSentence:{jp:"たなかさんは いしゃじゃ ありません。",furigana:"田中さんは 医者じゃ ありません。",romaji:"Tanaka-san wa isha ja arimasen.",idText:"Tanaka-san bukan seorang dokter."}},{id:"v4",word:"だいがく",reading:"だいがく",romaji:"daigaku",meaning:"Universitas / Perguruan Tinggi",nuance:"Tingkat pendidikan tinggi.",exampleSentence:{jp:"とうきょうだいがくの がくせいです。",furigana:"東京大学の 学生です。",romaji:"Toukyou daigaku no gakusei desu.",idText:"Mahasiswa Universitas Tokyo."}}],explanations:[{id:"exp1",grammarId:"gn5-00002",title:"Bentuk Negatif Sopan: 〜じゃありません",formula:"[Kata Benda] + じゃ ありません",meaning:"Menyatakan bahwa subjek bukan berstatus kata benda yang dimaksud.",nuanceNotes:"Bentuk sangkalan sopan netral untuk percakapan sehari-hari.",patternLogic:"Menggantikan akhiran です dengan じゃ ありません di akhir kalimat.",examples:[{jp:"わたしは せんせいじゃ ありません。",furigana:"私は 先生じゃ ありません。",romaji:"Watashi wa sensei ja arimasen.",idText:"Saya bukan seorang guru."}]},{id:"exp2",grammarId:"gn5-00004",title:"Partikel Tanya: 〜ですか",formula:"[Kalimat Lengkap] + か",meaning:"Mengubah kalimat pernyataan menjadi pertanyaan sopan.",nuanceNotes:"Di bahasa Jepang, partikel か menggantikan fungsi tanda tanya.",examples:[{jp:"ブディさんは がくせいですか。",furigana:"ブディさんは 学生ですか。",romaji:"Budi-san wa gakusei desu ka.",idText:"Apakah Budi-san seorang mahasiswa?"}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kontekstual): Bagaimana cara sopan menjawab "Bukan, salah mengira" dalam bahasa Jepang?',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["いいえ (Iie)","はい (Hai)","ありがとう (Arigatou)","どうぞ (Douzo)"],correctAnswer:"いいえ (Iie)",explanation:"Iie adalah kata sangkalan sopan untuk menyatakan bukan/tidak.",diagnosticFeedback:{"はい (Hai)":'Jebakan Partikel: Pilihan "はい (Hai)" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.',"ありがとう (Arigatou)":'Jebakan Partikel: Pilihan "ありがとう (Arigatou)" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.',"どうぞ (Douzo)":'Pilihan "どうぞ (Douzo)" keliru karena tidak selaras dengan kaidah pola gn5-00002.'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pilihan Partikel): Lengkapi partikel tanya di akhir kalimat:",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["か","は","ね","よ"],correctAnswer:"か",explanation:"Partikel か (ka) di akhir kalimat berfungsi sebagai penanda kalimat tanya.",diagnosticFeedback:{は:'Jebakan Partikel: Pilihan "は" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.',ね:'Pilihan "ね" keliru karena tidak selaras dengan kaidah pola gn5-00002.',よ:'Pilihan "よ" keliru karena tidak selaras dengan kaidah pola gn5-00002.'}},{id:"drill-3",type:"reorder",instruction:'Langkah 3 (Susun Kalimat): Susun kata-kata berikut menjadi: "Bukan guru"',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["せんせいじゃ ありません","ありません せんせいじゃ"],correctAnswer:"せんせいじゃ ありません",explanation:"Sensei ja arimasen = Bukan seorang guru.",diagnosticFeedback:{"ありません せんせいじゃ":'Jebakan Susunan: Urutan kata pada frasa "ありません せんせいじゃ" terbalik atau tidak selaras dengan struktur kalimat bahasa Jepang yang alami.'},tokens:["せんせいじゃ","ありません"],correctOrder:["0","1"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Kesalahan): Manakah susunan kalimat negatif yang SALAH?",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["わたしは じゃない がくせい。","わたしは がくせいじゃ ありません。","たなかさんは いしゃじゃ ありません。"],correctAnswer:"わたしは じゃない がくせい。",explanation:'Janai/ja arimasen tidak diletakkan di depan kata benda seperti kata "bukan" dalam bahasa Indonesia, melainkan di belakangnya.',diagnosticFeedback:{"わたしは がくせいじゃ ありません。":'Jebakan Partikel: Pilihan "わたしは がくせいじゃ ありません。" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.',"たなかさんは いしゃじゃ ありません。":'Jebakan Partikel: Pilihan "たなかさんは いしゃじゃ ありません。" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.'}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Nyata): Seseorang bertanya: "たなかさんは いしゃですか。". Jika Tanaka adalah guru dan bukan dokter, apa jawabanmu?',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["いいえ、いしゃじゃ ありません。せんせいです。","はい、いしゃじゃ ありません。","いいえ、いしゃです。","せんせい は です。"],correctAnswer:"いいえ、いしゃじゃ ありません。せんせいです。",explanation:"Menyangkal profesi dokter lalu menegaskan profesi guru secara tepat.",diagnosticFeedback:{"はい、いしゃじゃ ありません。":'Jebakan Partikel: Pilihan "はい、いしゃじゃ ありません。" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.',"いいえ、いしゃです。":'Jebakan Partikel: Pilihan "いいえ、いしゃです。" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.',"せんせい は です。":'Jebakan Partikel: Pilihan "せんせい は です。" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.'}}],can_do_challenge:{statement:"Mampu menyangkal kesalahpahaman profesi/status diri dan menyatakan identitas yang benar.",situation:"Petugas administrasi salah mengira Anda adalah seorang dokter.",promptTask:"Katakan bahwa Anda bukan dokter, melainkan perawat (kangoshi)!",modelAnswer:"いいえ、いしゃじゃ ありません。かんごしです。",modelAnswerId:"Iie, isha ja arimasen. Kangoshi desu.",culturalEtiquette:"Gunakan intonasi lembut saat meluruskan agar lawan bicara tidak merasa malu.",skillUnlocked:["Bisa menyangkal dengan 〜じゃありません","Bisa bertanya sopan dengan 〜ですか"],pocketSummary:{keyFormula:"[Nomina] じゃ ありません (Bukan ~) / 〜ですか (Apakah ~?)",coreWords:["はい (Ya)","いいえ (Bukan)","いしゃ (Dokter)"],coreWarning:'Jangan taruh kata "bukan" di depan kata benda!',quickDialogue:"A: がくせいですか？ → B: いいえ、かいしゃいんです。"}},pocket_summary:{keyFormula:"[Nomina] じゃ ありません (Bukan ~) / 〜ですか (Apakah ~?)",coreWords:["はい (Ya)","いいえ (Bukan)","いしゃ (Dokter)"],coreWarning:'Jangan taruh kata "bukan" di depan kata benda!',quickDialogue:"A: がくせいですか？ → B: いいえ、かいしゃいんです。"}},"les-n5-u01-03":{pedagogical_framework:{what:{summary:"Pola kepemilikan dan afiliasi dengan partikel の (no), serta predikat nominal lampau 〜でした dan sangkalan lampau 〜じゃありませんでした.",canDo:'Bisa menyatakan pemilik barang ("buku saya"), asal institusi ("mahasiswa universitas mana"), dan mengonfirmasi kondisi di waktu lampau.',targetPatterns:["〜の〜","〜でした","〜じゃありませんでした"],coreVocabSample:["ほん","ノート","だいがく","だれ","きのう","くるま"]},sensei_context:{sceneIntro:"Di tempat kerja atau kampus, sering kali barang tertinggal di atas meja rapat atau kita ditanya mengenai organisasi asal kita di masa lalu.",dailyMission:"Mampu menjelaskan kepemilikan barang pribadi dan menyebutkan asal institusi pendidikan atau tempat kerja sebelumnya secara santun.",whyOrder:'Partikel の adalah "lem perekat" paling serbaguna dalam bahasa Jepang. Menguasai の bersama bentuk lampau でした membuka kemampuan bercerita tentang latar belakang diri.'},cultural_notes:{title:"Partikel の Sebagai Penanda Keanggotaan Sosial (Uchi vs Soto)",etiquette:'Di Jepang, saat memperkenalkan diri dalam lingkungan bisnis, orang sering menyebut nama perusahaannya terlebih dahulu diikuti の baru namanya sendiri: "Toyota no Tanaka desu".',taboos:'Jangan terbalik susunannya! Di bahasa Indonesia kita mengatakan "Buku Budi" (Benda + Pemilik), sedangkan di bahasa Jepang selalu "Budi no hon" (Pemilik + の + Benda).'},pronunciation_tips:{title:"Ketukan Mora Partikel の dan Bentuk Lampau",moraNote:"Partikel の diucapkan pendek dan rata dengan 1 ketukan mora (no), menyatu halus dengan kata benda di depannya.",soundTip:'Pada bentuk lampau でした (deshita), vokal "i" dilafalkan teredam ("desh-ta"), jangan dipanjangkan menjadi "de-syi-ta".'},common_pitfalls:[{title:"Urutan Kepemilikan Terbalik (Hukum D-M Indonesia vs M-D Jepang)",caseScenario:"Menerjemahkan kepemilikan sesuai susunan kata bahasa Indonesia.",pitfallWarning:'"ほん ブディ の" (Buku Budi no - Terbalik)',rightSolution:'"ブディさんの 本" (Budi-san no hon - Benar)',explanation:"Bahasa Indonesia berpola Diterangkan-Menerangkan (Buku Budi), sedangkan bahasa Jepang berpola Menerangkan-Diterangkan (Budi-san no hon)."},{title:"Keterangan Lampau Berpasangan dengan Desu",caseScenario:"Menyatakan keadaan kemarin namun lupa mengubah desu menjadi deshita.",pitfallWarning:'"きのうは あめ です。" (Kemarin hujan adalah - bukan lampau)',rightSolution:'"きのうは あめ でした。" (Kinou wa ame deshita - lampau)',explanation:"Keterangan waktu lampau (kemarin, minggu lalu) wajib berpasangan dengan predikat lampau でした, bukan です."}],who_and_when:{situational_context:"Menanyakan kepemilikan barang di kantor/kelas, mencari barang hilang di meja resepsionis, atau menceritakan riwayat singkat.",social_relations:"Sopan standar (Teineigo) yang berlaku umum antar rekan kerja, staf publik, dan guru.",when_not_to_use:"Jangan memakai partikel の bertumpuk lebih dari 3 kali berturut-turut dalam satu tarikan napas agar kalimat tidak membingungkan."},scenario:{title:"Buku Catatan Tertinggal di Ruang Rapat Shinjuku",setting:"Ruang Rapat Perusahaan IT Tokyo",narrative:"Ken menemukan sebuah buku catatan tebal berwarna biru di atas meja dan menanyakan kepada Budi apakah itu miliknya."}},dialogue:[{id:"d1",speaker:"Ken",speakerRole:"Rekan Kerja Jepang",avatar:"👨‍💼",jp:"すみません、この ノートは ブディさんのですか。",furigana:"すみません、この ノートは ブディさんのですか。",romaji:"Sumimasen, kono nooto wa Budi-san no desu ka.",idText:"Permisi, apakah buku catatan ini milik Budi-san?",note:"Menunjuk sopan ke meja"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"いいえ、私【わたし】のでは ありません。田中【たなか】さんのですよ。",furigana:"いいえ、私のでは ありません。田中さんのですよ。",romaji:"Iie, watashi no dewa arimasen. Tanaka-san no desu yo.",idText:"Bukan, bukan milik saya. Itu milik Tanaka-san lho."},{id:"d3",speaker:"Ken",speakerRole:"Rekan Kerja Jepang",avatar:"👨‍💼",jp:"あ、田中【たなか】さんのですね。昨日【きのう】 ここで 会議【かいぎ】が ありましたね。",furigana:"あ、田中さんのですね。昨日 ここで 会議が ありましたね。",romaji:"A, Tanaka-san no desu ne. Kinou koko de kaigi ga arimashita ne.",idText:"Oh, milik Tanaka-san ya. Kemarin ada rapat di sini ya."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、昨日【きのう】は とても 忙【いそが】しい 一日【いちにち】でした。",furigana:"はい、昨日は とても 忙しい 一日でした。",romaji:"Hai, kinou wa totemo isogashii ichinichi deshita.",idText:"Ya, kemarin adalah hari yang sangat sibuk."}],vocab_breakdown:[{id:"v1",word:"ほん",reading:"ほん",romaji:"hon",meaning:"Buku",nuance:"Kata umum untuk semua jenis buku fisik.",exampleSentence:{jp:"これは にほんごの ホンです。",furigana:"これは 日本語の 本です。",romaji:"Kore wa nihongo no hon desu.",idText:"Ini adalah buku bahasa Jepang."}},{id:"v2",word:"ノート",reading:"ノート",romaji:"nooto",meaning:"Buku catatan / Notebook",nuance:'Berasal dari serapan bahasa Inggris "notebook".',exampleSentence:{jp:"それは わたしの ノートです。",furigana:"それは 私の ノートです。",romaji:"Sore wa watashi no nooto desu.",idText:"Itu adalah buku catatan saya."}},{id:"v3",word:"だれ",reading:"だれ",romaji:"dare",meaning:"Siapa (kata tanya orang)",nuance:"Ragam sopannya adalah どなた (donata).",exampleSentence:{jp:"これは だれの かさですか。",furigana:"これは 誰の 傘ですか。",romaji:"Kore wa dare no kasa desu ka.",idText:"Ini payung milik siapa?"}},{id:"v4",word:"きのう",reading:"きのう",romaji:"kinou",meaning:"Kemarin (waktu lampau)",nuance:"Wajib dipasangkan dengan predikat bentuk lampau でした.",exampleSentence:{jp:"きのうは やすみでした。",furigana:"昨日は 休みでした。",romaji:"Kinou wa yasumi deshita.",idText:"Kemarin adalah hari libur."}}],explanations:[{id:"exp1",grammarId:"gn5-00003",title:"Partikel Kepemilikan & Afiliasi: 〜の",formula:"[Pemilik/Institusi] + の + [Kata Benda]",meaning:"Menyatakan bahwa benda kedua dimiliki atau terhubung dengan entitas pertama.",nuanceNotes:"Susunannya selalu Pemilik di depan, Benda di belakang.",examples:[{jp:"これは わたしの ペンです。",furigana:"これは 私の ペンです。",romaji:"Kore wa watashi no pen desu.",idText:"Ini adalah pulpen milik saya."}]},{id:"exp2",grammarId:"gn5-00005",title:"Predikat Nominal Lampau: 〜でした / 〜じゃありませんでした",formula:"[Kata Benda] + でした / じゃ ありませんでした",meaning:"Menyatakan status atau kondisi yang terjadi di masa lalu.",nuanceNotes:"Bentuk lampau positif adalah でした, sedangkan lampau negatif adalah じゃありませんでした.",examples:[{jp:"きのうは にちようびでした。",furigana:"昨日は 日曜日でした。",romaji:"Kinou wa nichiyoubi deshita.",idText:"Kemarin adalah hari Minggu."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah arti dari kata tanya "だれ (dare)"?',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["Siapa","Kapan","Di mana","Berapa"],correctAnswer:"Siapa",explanation:"だれ (dare) berarti siapa.",diagnosticFeedback:{Kapan:"Kapan dalam bahasa Jepang adalah いつ (itsu).","Di mana":"Di mana dalam bahasa Jepang adalah どこ (doko).",Berapa:"Berapa adalah いくら / いくつ."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Pilihan Partikel): Lengkapi partikel kepemilikan berikut: "Ini buku milik Budi-san"',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["の","は","を","に"],correctAnswer:"の",explanation:"Partikel の menghubungkan pemilik (Budi-san) dengan bendanya (hon).",diagnosticFeedback:{は:"Partikel は adalah penanda topik, bukan penanda kepemilikan kata benda.",を:"Partikel を menandai objek kata kerja tindakan.",に:"Partikel に menandai tujuan atau titik waktu."}},{id:"drill-3",type:"reorder",instruction:'Langkah 3 (Susun Kalimat): Susun kalimat berikut: "Buku catatan milik saya"',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["わたし の ノート","の わたし ノート","の ノート わたし","わたし ノート の"],correctAnswer:"わたし の ノート",explanation:"Pemilik (watashi) + partikel (no) + benda (nooto).",diagnosticFeedback:{"の わたし ノート":'Jebakan Susunan: Urutan kata pada frasa "の わたし ノート" terbalik atau tidak selaras dengan struktur kalimat bahasa Jepang yang alami.',"の ノート わたし":'Jebakan Susunan: Urutan kata pada frasa "の ノート わたし" terbalik atau tidak selaras dengan struktur kalimat bahasa Jepang yang alami.',"わたし ノート の":'Jebakan Susunan: Urutan kata pada frasa "わたし ノート の" terbalik atau tidak selaras dengan struktur kalimat bahasa Jepang yang alami.'},tokens:["わたし","の","ノート"],correctOrder:["0","1","2"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Kesalahan): Manakah susunan kalimat lampau yang SALAH?",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["きのうは あめ です。","きのうは あめ でした。","おとといは やすみでした。"],correctAnswer:"きのうは あめ です。",explanation:'Keterangan waktu lampau "きのう" wajib berpasangan dengan predikat lampau "でした", bukan "です".',diagnosticFeedback:{"きのうは あめ でした。":"Kalimat ini benar karena memakai predikat lampau でした.","おとといは やすみでした。":"Kalimat ini benar karena おととい (kemarin lusa) berpasangan dengan でした."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Seseorang bertanya: "これは あなたの ノートですか。". Jika itu milik Tanaka, apa respons Anda?',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["いいえ、わたしのでは ありません。たなかさんのです。","はい、たなかさんのです。","いいえ、ノートです。","たなかさんは ノートです。"],correctAnswer:"いいえ、わたしのでは ありません。たなかさんのです。",explanation:"Menyangkal kepemilikan pribadi lalu menegaskan pemilik sebenarnya secara santun.",diagnosticFeedback:{"はい、たなかさんのです。":'Jebakan Partikel: Pilihan "はい、たなかさんのです。" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.',"いいえ、ノートです。":'Jebakan Partikel: Pilihan "いいえ、ノートです。" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.',"たなかさんは ノートです。":'Jebakan Partikel: Pilihan "たなかさんは ノートです。" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.'}}],can_do_challenge:{statement:"Mampu menjelaskan kepemilikan benda dan menyatakan peristiwa di masa lampau.",situation:"Rekan kerja menemukan payung tertinggal dan menanyakan apakah itu milik Anda.",promptTask:"Katakan bahwa itu bukan milik Anda, melainkan milik Tanaka-san!",modelAnswer:"いいえ、わたしのでは ありません。たなかさんのです。",modelAnswerId:"Iie, watashi no dewa arimasen. Tanaka-san no desu.",culturalEtiquette:"Ucapkan dengan ramah dan tunjuk ke arah pemilik yang bersangkutan bila ada di ruangan.",skillUnlocked:["Menguasai partikel kepemilikan 〜の","Menguasai bentuk lampau nominal 〜でした"],pocketSummary:{keyFormula:"[Pemilik] の [Benda] / [Waktu Lampau] は [Nomina] でした",coreWords:["ほん (Buku)","だれ (Siapa)","きのう (Kemarin)"],coreWarning:"Pemilik selalu di depan partikel の, jangan terbalik!",quickDialogue:"A: だれの ノートですか？ → B: わたしのです。"}},pocket_summary:{keyFormula:"[Pemilik] の [Benda] / [Waktu Lampau] は [Nomina] でした",coreWords:["ほん (Buku)","だれ (Siapa)","きのう (Kemarin)"],coreWarning:"Pemilik selalu di depan partikel の, jangan terbalik!",quickDialogue:"A: だれの ノートですか？ → B: わたしのです。"}}},n={"les-n5-u02-01":{pedagogical_framework:{what:{summary:"Pola kata tunjuk benda mandiri これ (dekat pembicara), それ (dekat lawan bicara), あれ (jauh dari keduanya), dan kata tanya どれ (yang mana).",canDo:"Bisa menunjuk dan menanyakan nama benda di sekitar dalam ruang kerja, toko, atau kelas secara tepat posisi.",targetPatterns:["これは〜です","それは〜ですか","あれは〜です","どれですか"],coreVocabSample:["これ","それ","あれ","どれ","ペン","かぎ","とけい","なん"]},sensei_context:{sceneIntro:"Saat berbelanja di minimarket Jepang atau meminta tolong mengambilkan barang di kantor, kamu perlu menunjuk barang dengan tepat berdasarkan jarak posisi.",dailyMission:"Mampu menunjuk barang yang ada di dekatmu (Kore), dekat temanmu (Sore), dan yang berada jauh dari kalian berdua (Are).",whyOrder:"Sistem kata tunjuk Ko-So-A-Do adalah pilar spasial bahasa Jepang yang teratur. Menguasai 4 koordinat dasar ini membuatmu bisa bertanya nama benda apa pun."},cultural_notes:{title:"Etika Menunjuk Benda di Jepang",etiquette:"Saat menunjuk barang di tempat umum atau toko, arahkan telapak tangan terbuka dengan jari rapat ke arah barang (Tenohira), bukan dengan telunjuk mengacung tunggal yang dianggap kasar.",taboos:'Jangan pernah menunjuk orang menggunakan kata "Kore" atau "Are"! Untuk orang, gunakan kata sopan "Kochira" atau "Achira".'},pronunciation_tips:{title:"Intonasi Ko-So-A-Do",moraNote:"Setiap kata memiliki 2 ketukan mora rata: ko-re, so-re, a-re, do-re.",soundTip:'Ucapkan "Kore wa nan desu ka?" dengan penekanan wajar pada kata tanya "nan".'},common_pitfalls:[{title:"Tertukar Kore dan Sore Berdasarkan Perspektif Rekan Bicara",caseScenario:"Menunjuk barang yang dipegang lawan bicara dengan berkata Kore.",pitfallWarning:'Menunjuk barang di tangan teman sambil berkata "Kore wa...".',rightSolution:'Barang di tangan lawan bicara wajib disebut "Sore wa...".',explanation:"Kore hanya untuk benda di zona pembicara. Jika benda berada di tangan atau meja rekan bicara, gunakan Sore!"},{title:"Menempelkan Kata Benda Langsung Setelah Kore",caseScenario:'Mencoba membuat kalimat "Buku ini" dengan Kore Hon.',pitfallWarning:'"これ 本は わたしのです。" (Kore hon wa...)',rightSolution:'"この 本は わたしのです。" (Kono hon wa...) atau "これは わたしの 本です。"',explanation:"Kore adalah kata ganti mandiri (pronomina) yang diikuti partikel は, tidak boleh langsung menempel pada kata benda."}],who_and_when:{situational_context:"Berbelanja di minimarket/toko buku, meminjam alat tulis di kantor, mengidentifikasi dokumen di meja kerja.",social_relations:"Ragam sopan standar (Teineigo) yang aman digunakan kepada siapa pun.",when_not_to_use:"Jangan gunakan untuk menunjuk manusia atau atasan kerja."},scenario:{title:"Membeli Alat Tulis di Toko Buku Tokyo",setting:"Toko Alat Tulis Maruzen Ginza",narrative:"Budi sedang memilih buku kamus dan menanyakan jenis produk kepada pramuniaga toko."}},dialogue:[{id:"d1",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"すみません、これは 日本語の 辞書【じしょ】ですか。",furigana:"すみません、これは 日本語の 辞書ですか。",romaji:"Sumimasen, kore wa Nihongo no jisho desu ka.",idText:"Permisi, apakah ini kamus bahasa Jepang?"},{id:"d2",speaker:"Tenin",speakerRole:"Pramuniaga Toko",avatar:"🧑‍💼",jp:"はい、それは 初級の 日本語辞典です。",furigana:"はい、それは 初級の 日本語辞典です。",romaji:"Hai, sore wa shokyuu no Nihongo jiten desu.",idText:"Ya, itu adalah kamus bahasa Jepang tingkat dasar."},{id:"d3",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"あそこに ある あれは 何ですか。",furigana:"あそこに ある あれは 何ですか。",romaji:"Asoko ni aru are wa nan desu ka.",idText:"Yang ada di sebelah sana itu apa?"},{id:"d4",speaker:"Tenin",speakerRole:"Pramuniaga Toko",avatar:"🧑‍💼",jp:"あれは 漢字練習帳です。とても 人気がありますよ。",furigana:"あれは 漢字練習帳です。とても 人気がありますよ。",romaji:"Are wa Kanji renshuuchou desu. Totemo ninki ga arimasu yo.",idText:"Itu adalah buku latihan Kanji. Sangat populer lho."}],vocab_breakdown:[{id:"v1",word:"これ",reading:"これ",romaji:"kore",meaning:"Ini (benda dekat pembicara)",nuance:"Digunakan untuk barang yang berada dalam jangkauan tangan pembicara.",exampleSentence:{jp:"これは ペンです。",furigana:"これは ペンです。",romaji:"Kore wa pen desu.",idText:"Ini adalah pulpen."}},{id:"v2",word:"それ",reading:"それ",romaji:"sore",meaning:"Itu (benda dekat lawan bicara)",nuance:"Digunakan untuk barang yang berada dekat lawan bicara.",exampleSentence:{jp:"それは じしょです。",furigana:"それは 辞書です。",romaji:"Sore wa jisho desu.",idText:"Itu adalah kamus."}},{id:"v3",word:"あれ",reading:"あれ",romaji:"are",meaning:"Itu (jauh dari keduanya)",nuance:"Digunakan untuk barang yang posisinya jauh dari pembicara dan lawan bicara.",exampleSentence:{jp:"あれは くるまです。",furigana:"あれは 車です。",romaji:"Are wa kuruma desu.",idText:"Itu adalah mobil."}},{id:"v4",word:"なん",reading:"なん",romaji:"nan",meaning:"Apa (kata tanya)",nuance:'Biasa dipadukan dengan ですか menjadi "Nan desu ka?" (何ですか). Berubah menjadi なに (nani) jika berdiri sendiri atau diikuti partikel tertentu seperti が atau を (misal 何を/nani o).',exampleSentence:{jp:"これは なんですか。",furigana:"これは 何ですか。",romaji:"Kore wa nan desu ka.",idText:"Ini apa?"}}],explanations:[{id:"exp1",grammarId:"gn5-00007",title:"Kata Tunjuk Mandiri: これ / それ / あれ",formula:"これ / それ / あれ + は + [Kata Benda] + です",meaning:"Menunjuk benda berdasarkan 3 zona jarak relatif dari pembicara dan lawan bicara.",nuanceNotes:"Kore = dekat saya, Sore = dekat kamu, Are = jauh di sana.",examples:[{jp:"これは わたしのかぎです。",furigana:"これは 私の鍵です。",romaji:"Kore wa watashi no kagi desu.",idText:"Ini adalah kunci saya."}]},{id:"exp2",grammarId:"gn5-00008",title:"Kata Tanya Benda: どれ & 何 (なん)",formula:"これは なん ですか / どれ ですか",meaning:"Menanyakan identitas benda atau memilih opsi dari kelompok barang.",nuanceNotes:'Gunakan "Nan desu ka" untuk menanyakan nama benda, dan "Dore" untuk memilih satu dari beberapa opsi.',examples:[{jp:"あなたの かさは どれですか。",furigana:"あなたの 傘は どれですか。",romaji:"Anata no kasa wa dore desu ka.",idText:"Payung milik Anda yang mana?"}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Arti Kontekstual): Jika barang berada di dekat lawan bicara Anda, kata tunjuk apa yang tepat?",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["それ (Sore)","これ (Kore)","あれ (Are)","どれ (Dore)"],correctAnswer:"それ (Sore)",explanation:"Sore digunakan untuk barang yang posisinya berada di area lawan bicara.",diagnosticFeedback:{"これ (Kore)":"Kore untuk benda di dekat Anda (pembicara), bukan di dekat teman bicara.","あれ (Are)":"Are untuk benda yang jauh dari Anda berdua.","どれ (Dore)":'Dore adalah kata tanya ("yang mana").'}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Pilihan Kata): Lengkapi pertanyaan: "Ini apa?"',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["なん","だれ","どこ","いつ"],correctAnswer:"なん",explanation:"Nan (apa) digunakan untuk menanyakan benda.",diagnosticFeedback:{だれ:"Dare untuk menanyakan orang (siapa).",どこ:"Doko untuk menanyakan tempat (di mana).",いつ:"Itsu untuk menanyakan waktu (kapan)."}},{id:"drill-3",type:"reorder",instruction:'Langkah 3 (Susun Kalimat): Susun: "Itu adalah kamus"',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["それは じしょ です","じしょ それは です","じしょ です それは","それは です じしょ"],correctAnswer:"それは じしょ です",explanation:"Sore wa (topik) + jisho (predikat) + desu.",diagnosticFeedback:{"じしょ それは です":'Jebakan Susunan: Urutan kata pada frasa "じしょ それは です" terbalik atau tidak selaras dengan struktur kalimat bahasa Jepang yang alami.',"じしょ です それは":'Jebakan Susunan: Urutan kata pada frasa "じしょ です それは" terbalik atau tidak selaras dengan struktur kalimat bahasa Jepang yang alami.',"それは です じしょ":'Jebakan Susunan: Urutan kata pada frasa "それは です じしょ" terbalik atau tidak selaras dengan struktur kalimat bahasa Jepang yang alami.'},tokens:["それは","じしょ","です"],correctOrder:["0","1","2"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Kesalahan): Manakah susunan kalimat yang SALAH?",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["これ ほんは わたしのです。","これは わたしの ほんです。","あれは くるまです。"],correctAnswer:"これ ほんは わたしのです。",explanation:'Kore tidak boleh langsung menempel di depan kata benda! Harus menjadi "Kono hon" atau "Kore wa hon desu".',diagnosticFeedback:{"これは わたしの ほんです。":'Jebakan Partikel: Pilihan "これは わたしの ほんです。" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.',"あれは くるまです。":'Jebakan Partikel: Pilihan "あれは くるまです。" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.'}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Nyata): Rekan kerja menunjuk buku di dekat Anda dan bertanya: "それは なんですか。". Bagaimana jawaban awal Anda?',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["これは にほんごの ほんです。","それは にほんごの ほんです。","あれは にほんごの ほんですどれ。","だれ ですか。"],correctAnswer:"これは にほんごの ほんです。",explanation:'Karena barang berada di dekat Anda, saat menjawab Anda menyebutnya "Kore".',diagnosticFeedback:{"それは にほんごの ほんです。":'Jebakan Partikel: Pilihan "それは にほんごの ほんです。" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.',"あれは にほんごの ほんですどれ。":'Jebakan Partikel: Pilihan "あれは にほんごの ほんですどれ。" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.',"だれ ですか。":'Jebakan Partikel: Pilihan "だれ ですか。" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.'}}],can_do_challenge:{statement:"Mampu menunjuk dan menanyakan nama barang di sekitar menggunakan Kore, Sore, Are.",situation:"Anda sedang berada di kantor dan ingin menanyakan nama dokumen di atas meja rekan kerja.",promptTask:"Tunjuk dokumen di meja rekan kerja dan tanyakan itu apa!",modelAnswer:"すみません、それは 何の しょるいですか。",modelAnswerId:"Sumimasen, sore wa nan no shorui desu ka.",culturalEtiquette:"Tunjuk dengan telapak tangan terbuka menghadap ke atas, hindari mengacungkan jari telunjuk tunggal.",skillUnlocked:["Bisa membedakan zona jarak Kore / Sore / Are","Bisa bertanya nama barang dengan 何ですか"],pocketSummary:{keyFormula:"これ (Dekat saya) / それ (Dekat kamu) / あれ (Jauh) + は [Nomina] です",coreWords:["これ (Ini)","それ (Itu)","あれ (Itu jauh)","なん (Apa)"],coreWarning:"Jangan gunakan Kore/Are untuk menunjuk orang!",quickDialogue:"A: これは なんですか？ → B: それは じしょです。"}},pocket_summary:{keyFormula:"これ (Dekat saya) / それ (Dekat kamu) / あれ (Jauh) + は [Nomina] です",coreWords:["これ (Ini)","それ (Itu)","あれ (Itu jauh)","なん (Apa)"],coreWarning:"Jangan gunakan Kore/Are untuk menunjuk orang!",quickDialogue:"A: これは なんですか？ → B: それは じしょです。"}},"les-n5-u02-02":{pedagogical_framework:{what:{summary:"Pola kata penunjuk atributif この / その / あの / どの yang wajib langsung menempel di depan kata benda.",canDo:'Bisa merinci barang spesifik ("buku yang ini", "payung yang itu") dan menanyakan pilihan spesifik di antara banyak opsi.',targetPatterns:["この [Nomina] は〜です","その [Nomina]","あの [Nomina]","どの [Nomina] ですか"],coreVocabSample:["この","その","あの","どの","かばん","かさ","ひと","いくら"]},sensei_context:{sceneIntro:'Ketika ada banyak barang sejenis berjejer di etalase toko atau gantungan payung, kita harus menyebutkan secara spesifik: "Payung yang mana milikmu?".',dailyMission:"Mampu menggunakan pasangan Kono/Sono/Ano/Dono bersama kata benda secara tepat untuk memilih atau mendeskripsikan barang.",whyOrder:"Setelah menguasai Kore/Sore/Are mandiri, otakmu siap membedakan bentuk atributif Kono/Sono/Ano yang langsung memodifikasi kata benda di depannya."},cultural_notes:{title:"Menunjuk Orang Secara Halus dengan Ano Hito / Ano Kata",etiquette:'Jika menunjuk seseorang yang posisinya agak jauh, sebutlah "Ano kata" (ragam sangat hormat) atau "Ano hito" (ragam netral). Jangan pernah menunjuk dengan jari!',taboos:'Pantang membiarkan kata "Kono" berdiri sendiri tanpa kata benda (misal: "Kono wa ikura desu ka?" adalah salah fatal!).'},pronunciation_tips:{title:"Ritme Bunyi Kono / Sono / Ano",moraNote:"Kono, Sono, Ano, Dono mengalir langsung ke kata benda berikutnya tanpa jeda nafas yang canggung.",soundTip:'Ucapkan "Kono kaban" laksana satu kesatuan frasa yang harmonis.'},common_pitfalls:[{title:"Tertukar Penggunaan Kore vs Kono",caseScenario:"Memakai Kono sendirian diikuti partikel wa.",pitfallWarning:'"このは わたしの ペンです。" (Kono wa...)',rightSolution:'"これは わたしの ペンです。" atau "この ペンは わたしのです。"',explanation:'Kono WAJIB diikuti kata benda ("kono pen"). Kore berdiri mandiri diikuti partikel ("kore wa").'},{title:"Menanyakan Pilihan Menggunakan Dore Nomina",caseScenario:'Ingin bertanya "Tas yang mana" tetapi memakai Dore Kaban.',pitfallWarning:'"どれ かばんが あなたのですか。"',rightSolution:'"どの かばんが あなたのですか。"',explanation:"Di depan kata benda, kata tanyanya adalah どの (Dono), bukan どれ (Dore)."}],who_and_when:{situational_context:"Memilih produk spesifik di toko pakaian/elektronik, mengambil payung di tempat penitipan, mengenali orang di foto.",social_relations:"Sopan standar (Teineigo) untuk percakapan transaksi dan sosial.",when_not_to_use:"Jangan gunakan Kono/Sono sendirian tanpa kata benda."},scenario:{title:"Mengambil Payung di Rak Penitipan Restoran Tokyo",setting:"Pintu Masuk Restoran Ramen Shibuya",narrative:"Setelah selesai makan siang saat hujan deras, Budi mencari payungnya di rak penitipan bersama pelayan restoran."}},dialogue:[{id:"d1",speaker:"Pelayan",speakerRole:"Staf Restoran",avatar:"🧑‍🍳",jp:"お客様、どの傘が お客様のですか。",furigana:"お客様、どの傘が お客様のですか。",romaji:"Okyaku-sama, dono kasa ga okyaku-sama no desu ka.",idText:"Tuan pelanggan, payung yang mana milik Anda?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"その 青い傘が 私のです。",furigana:"その 青い傘が 私のです。",romaji:"Sono aoi kasa ga watashi no desu.",idText:"Payung yang biru itu milik saya."},{id:"d3",speaker:"Pelayan",speakerRole:"Staf Restoran",avatar:"🧑‍🍳",jp:"こちらですね。どうぞ、お忘れ物の ないように。",furigana:"こちらですね。どうぞ、お忘れ物の ないように。",romaji:"Kochira desu ne. Douzo, owasuremono no nai you ni.",idText:"Yang ini ya. Silakan, semoga tidak ada barang tertinggal."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ありがとうございます。助かりました。",furigana:"ありがとうございます。助かりました。",romaji:"Arigatou gozaimasu. Tasakarimashita.",idText:"Terima kasih banyak. Sangat membantu."}],vocab_breakdown:[{id:"v1",word:"この",reading:"この",romaji:"kono",meaning:"... ini (wajib diikuti kata benda)",nuance:"Menempel langsung di depan kata benda yang berada di dekat pembicara.",exampleSentence:{jp:"この かばんは わたしのです。",furigana:"この 鞄は 私のです。",romaji:"Kono kaban wa watashi no desu.",idText:"Tas ini adalah milik saya."}},{id:"v2",word:"その",reading:"その",romaji:"sono",meaning:"... itu (wajib diikuti kata benda)",nuance:"Menempel di depan kata benda yang berada di dekat lawan bicara.",exampleSentence:{jp:"その かさを ください。",furigana:"その 傘を ください。",romaji:"Sono kasa wo kudasai.",idText:"Tolong berikan payung itu."}},{id:"v3",word:"あの",reading:"あの",romaji:"ano",meaning:"... itu jauh (wajib diikuti kata benda)",nuance:"Menempel di depan kata benda yang jauh dari kedua pembicara.",exampleSentence:{jp:"あの ひとは だれですか。",furigana:"あの 人は 誰ですか。",romaji:"Ano hito wa dare desu ka.",idText:"Orang di sebelah sana itu siapa?"}},{id:"v4",word:"どの",reading:"どの",romaji:"dono",meaning:"... yang mana (kata tanya penentu)",nuance:"Wajib diikuti kata benda saat memilih dari sekumpulan opsi.",exampleSentence:{jp:"どの シャツが いいですか。",furigana:"どの シャツが いいですか。",romaji:"Dono shatsu ga ii desu ka.",idText:"Kemeja yang mana yang bagus?"}}],explanations:[{id:"exp1",grammarId:"gn5-00009",title:"Kata Penunjuk Atributif: この / その / あの + Nomina",formula:"この / その / あの + [Kata Benda] + は〜です",meaning:"Merinci benda spesifik yang sedang dibicarakan.",nuanceNotes:"Wajib langsung menempel di depan kata benda tanpa partikel perantara.",examples:[{jp:"この ペンは 100えんです。",furigana:"この ペンは 100円です。",romaji:"Kono pen wa hyaku-en desu.",idText:"Pulpen ini harganya 100 yen."}]},{id:"exp2",grammarId:"gn5-00010",title:"Menanyakan Opsi Spesifik: どの + Nomina",formula:"どの + [Kata Benda] + が〜ですか",meaning:"Menanyakan pilihan di antara 3 benda atau lebih.",nuanceNotes:"Kata tanya どの di posisi subjek biasanya dipasangkan dengan partikel が.",examples:[{jp:"どの かばんが あなたのですか。",furigana:"どの 鞄が あなたのですか。",romaji:"Dono kaban ga anata no desu ka.",idText:"Tas yang mana yang merupakan milik Anda?"}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kontekstual): Jika ingin mengatakan "Buku ini" dalam bahasa Jepang, manakah padanan yang benar?',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["この ほん (Kono hon)","これ ほん (Kore hon)","その ほん (Sono hon)","どれ ほん (Dore hon)"],correctAnswer:"この ほん (Kono hon)",explanation:"Kata tunjuk yang menempel langsung ke kata benda adalah この (kono).",diagnosticFeedback:{"これ ほん (Kore hon)":"Kore tidak boleh menempel langsung ke kata benda.","その ほん (Sono hon)":'Sono hon berarti "buku itu", bukan "buku ini".',"どれ ほん (Dore hon)":"Dore tidak menempel ke kata benda (gunakan dono)."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Pilihan Kata): Lengkapi kalimat: "Payung yang mana milik Anda?"',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["どの","どれ","なに","どこ"],correctAnswer:"どの",explanation:"Di depan kata benda kasa (payung), kata tanyanya adalah どの (dono).",diagnosticFeedback:{どれ:"Dore berdiri mandiri dan tidak menempel di depan kata benda.",なに:'Nani berarti apa, bukan penentu "yang mana".',どこ:"Doko menanyakan lokasi (di mana)."}},{id:"drill-3",type:"reorder",instruction:'Langkah 3 (Susun Kalimat): Susun: "Payung itu milik saya"',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["その かさは わたしのです","かさは その わたしのです","かさは わたしのです その","その わたしのです かさは"],correctAnswer:"その かさは わたしのです",explanation:"Sono kasa wa (topik spesifik) + watashi no desu (predikat).",diagnosticFeedback:{"かさは その わたしのです":'Jebakan Susunan: Urutan kata pada frasa "かさは その わたしのです" terbalik atau tidak selaras dengan struktur kalimat bahasa Jepang yang alami.',"かさは わたしのです その":'Jebakan Susunan: Urutan kata pada frasa "かさは わたしのです その" terbalik atau tidak selaras dengan struktur kalimat bahasa Jepang yang alami.',"その わたしのです かさは":'Jebakan Susunan: Urutan kata pada frasa "その わたしのです かさは" terbalik atau tidak selaras dengan struktur kalimat bahasa Jepang yang alami.'},tokens:["その","かさは","わたしのです"],correctOrder:["0","1","2"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Kesalahan): Manakah penggunaan kata tunjuk yang SALAH?",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["このは 100円です。","この ペンは 100円です。","これは 100円です。"],correctAnswer:"このは 100円です。",explanation:'Kono tidak boleh berdiri sendiri tanpa kata benda! Gunakan "Kore wa 100-en desu" atau "Kono pen wa 100-en desu".',diagnosticFeedback:{"この ペンは 100円です。":'Jebakan Partikel: Pilihan "この ペンは 100円です。" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.',"これは 100円です。":'Jebakan Partikel: Pilihan "これは 100円です。" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.'}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Nyata): Seseorang bertanya: "どの かばんが あなたのですか。". Menunjuk tas hitam di dekat Anda, apa respons terbaik?',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["この くろい かばんが わたしのです。","これ かばんが わたしのです。","どこ ですか。","どの かばんです。"],correctAnswer:"この くろい かばんが わたしのです。",explanation:'Menegaskan tas hitam di dekat pembicara dengan pola "Kono kuroi kaban ga watashi no desu".',diagnosticFeedback:{"これ かばんが わたしのです。":'Jebakan Partikel: Pilihan "これ かばんが わたしのです。" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.',"どこ ですか。":'Jebakan Partikel: Pilihan "どこ ですか。" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.',"どの かばんです。":'Jebakan Partikel: Pilihan "どの かばんです。" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.'}}],can_do_challenge:{statement:"Mampu mendeskripsikan dan memilih barang spesifik menggunakan Kono, Sono, Ano, Dono + Kata Benda.",situation:"Anda sedang berada di kasir toko dan ingin menunjuk tas spesifik yang ingin dibeli.",promptTask:"Katakan bahwa Anda menginginkan tas yang berwarna biru itu!",modelAnswer:"すみません、その 青い かばんを ください。",modelAnswerId:"Sumimasen, sono aoi kaban wo kudasai.",culturalEtiquette:"Ucapkan dengan jelas sambil menunjuk dengan telapak tangan terbuka.",skillUnlocked:["Menguasai atributif この / その / あの + Nomina","Menguasai kata tanya selektif どの + Nomina"],pocketSummary:{keyFormula:"この / その / あの / どの + [Kata Benda]",coreWords:["この (Ini...)","その (Itu...)","あの (Itu jauh...)","どの (Yang mana...)"],coreWarning:"Kono/Sono/Ano/Dono WAJIB menempel pada kata benda!",quickDialogue:"A: どの かさですか？ → B: その あおい かさです。"}},pocket_summary:{keyFormula:"この / その / あの / どの + [Kata Benda]",coreWords:["この (Ini...)","その (Itu...)","あの (Itu jauh...)","どの (Yang mana...)"],coreWarning:"Kono/Sono/Ano/Dono WAJIB menempel pada kata benda!",quickDialogue:"A: どの かさですか？ → B: その あおい かさです。"}}},e={"les-n5-u03-01":{pedagogical_framework:{what:{summary:"Pola pembedaan predikat keberadaan benda mati (〜があります) dan makhluk bernyawa/bergerak (〜がいます).",canDo:"Bisa menyatakan keberadaan benda fasilitas (meja, kunci, kulkas) dan makhluk hidup (orang, kucing, anjing) secara tepat tanpa tertukar.",targetPatterns:["〜があります","〜がいます","が (subjek keberadaan)"],coreVocabSample:["ある","いる","ねこ","いぬ","ひと","へや","つくえ","かぎ","テレビ","れいぞうこ"]},sensei_context:{sceneIntro:"Bayangkan kamu baru saja pindah ke asrama kerja (ryou) atau apartemen di Tokyo. Sakura-san, seniormu, sedang mengecek kelengkapan fasilitas kamar dan memperkenalkan lingkungan asrama.",dailyMission:'Mampu membedakan dengan lancar kapan harus menggunakan "arimasu" untuk perabot/benda dan "imasu" untuk orang/hewan di sekitar tempat tinggal.',whyOrder:'Kenapa pola ini sangat krusial dipelajari sekarang? Karena dalam bahasa Indonesia kita hanya punya satu kata "ada". Lidah Indonesia sering refleks menyebut "kucing arimasu", padahal itu terdengar fatal seperti menganggap hewan hidup sebagai barang mati!'},cultural_notes:{title:"Konsep Kehidupan (Seimei) dalam Tata Bahasa Jepang",etiquette:"Orang Jepang membedakan secara tegas hal yang memiliki kehendak bergerak sendiri (makhluk bernyawa: orang, serangga, hewan memakai います) dan hal yang statis/pasif (tumbuhan, perabot, gedung memakai あります). Uniknya, robot canggih atau karakter fiksi terkadang diperlakukan dengan います bila dianggap hidup!",taboos:'Jangan pernah menggunakan "arimasu" saat membicarakan anggota keluarga atau rekan kerja (misal: "Budi-san ga arimasu"), karena ini merendahkan martabat manusia menjadi setara barang!'},pronunciation_tips:{title:"Intonasi Partikel Ga dan Pelafalan Arimasu/Imasu",moraNote:'Partikel "ga" (が) diucapkan ringan tanpa penekanan ledakan, menempel cepat pada kata benda di depannya.',soundTip:`Pada kata "arimasu" dan "imasu", vokal "u" di akhir dilesapkan laksana hembusan napas ("arimas'", "imas'"). Jangan membaca dengan vokal "u" bulat tebal.`},common_pitfalls:[{title:'Jebakan Kata Tunggal "Ada" (Menyebut Kucing dengan Arimasu)',caseScenario:'Melihat ada kucing asrama lalu spontan menerjemahkan kata "ada" secara harfiah.',pitfallWarning:'"へやに ねこが あります。" (Heya ni neko ga arimasu)',rightSolution:'"へやに ねこが います。" (Heya ni neko ga imasu)',explanation:'Kucing adalah makhluk bernyawa yang bergerak aktif. Wajib menggunakan "imasu". Menggunakan "arimasu" memberi konotasi janggal bahwa kucing tersebut adalah patung pajangan atau sudah mati.'},{title:'Salah Partikel: Memakai "o" alih-alih "ga" untuk Keberadaan',caseScenario:"Mengira kalimat keberadaan menggunakan objek langsung seperti pola kalimat transitif.",pitfallWarning:'"テレビを あります。" (Terebi o arimasu)',rightSolution:'"テレビが あります。" (Terebi ga arimasu)',explanation:'Kata kerja keberadaan (arimasu/imasu) bersifat intransitif (keadaan otomatis). Entitas yang ada ditandai dengan partikel subjek "ga" (が), bukan partikel objek "o" (を).'}],who_and_when:{situational_context:"Mengecek inventaris kamar asrama, memesan kamar hotel, mengonfirmasi keberadaan staf di kantor, atau melihat hewan peliharaan di taman.",social_relations:"Ragam sopan standar (Teineigo) yang lazim digunakan kepada teman baru, staf asrama, atau rekan kerja kantor.",when_not_to_use:'Untuk tumbuhan seperti pohon atau bunga, meskipun makhluk hidup biologis, bahasa Jepang umumnya menggolongkannya ke dalam "arimasu" karena tidak berpindah tempat sendiri.'},scenario:{title:"Orientasi Asrama Baru Bersama Sakura-san",setting:"Kamar Asrama Karyawan di Edogawa, Tokyo",narrative:"Budi baru selesai menurunkan koper di kamar asrama. Sakura datang membawakan kunci cadangan dan memperkenalkan kucing peliharaan asrama bernama Mii-chan."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Senior Jepang",avatar:"👩‍💼",jp:"ブディさん、部屋【へや】の 中【なか】に 何【なに】か ありますか。",furigana:"ブディさん、部屋の 中に 何か ありますか。",romaji:"Budi-san, heya no naka ni nanika arimasu ka.",idText:"Budi-san, apakah ada sesuatu (perabot) di dalam kamar?",note:"Menunjuk ke dalam kamar asrama"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、ベッドと 机【つくえ】が あります。テレビも あります。",furigana:"はい、ベッドと 机が あります。テレビも あります。",romaji:"Hai, beddo to tsukue ga arimasu. Terebi mo arimasu.",idText:"Ya, ada ranjang dan meja. Televisi juga ada."},{id:"d3",speaker:"Sakura",speakerRole:"Senior Jepang",avatar:"👩‍💼",jp:"よかったです。冷蔵庫【れいぞうこ】は ありますか。",furigana:"よかったです。冷蔵庫は ありますか。",romaji:"Yokatta desu. Reizouko wa arimasu ka.",idText:"Syukurlah. Kulkas apakah ada?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"いいえ、冷蔵庫【れいぞうこ】は ありません。",furigana:"いいえ、冷蔵庫は ありません。",romaji:"Iie, reizouko wa arimasen.",idText:"Tidak, kulkas tidak ada."},{id:"d5",speaker:"Sakura",speakerRole:"Senior Jepang",avatar:"👩‍💼",jp:"そうですか。あ、ドアの 前【まえ】に 誰【だれ】か いますよ。",furigana:"そうですか。あ、ドアの 前に 誰か いますよ。",romaji:"Sou desu ka. A, doa no mae ni dareka imasu yo.",idText:"Begitu ya. Eh, di depan pintu ada seseorang lho.",note:"Sakura menoleh ke arah pintu lorong"},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"あ、猫【ねこ】ですね！かわいいです。",furigana:"あ、猫ですね！かわいいです。",romaji:"A, neko desu ne! Kawaii desu.",idText:"Ah, kucing ya! Lucunya."},{id:"d7",speaker:"Sakura",speakerRole:"Senior Jepang",avatar:"👩‍💼",jp:"はい、寮【りょう】の 猫【ねこ】です。名前は ミーちゃんです。",furigana:"はい、寮の 猫です。名前は ミーちゃんです。",romaji:"Hai, ryou no neko desu. Namae wa Mii-chan desu.",idText:"Iya, ini kucing asrama. Namanya Mii-chan."},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"寮官【りょうかん】の おじさんも ロビーに いますか。",furigana:"寮官の おじさんも ロビーに いますか。",romaji:"Ryoukan no ojisan mo robii ni imasu ka.",idText:"Apakah bapak pengelola asrama juga ada di lobi?"},{id:"d9",speaker:"Sakura",speakerRole:"Senior Jepang",avatar:"👩‍💼",jp:"はい、ロビーに いますよ。後【あと】で 挨拶【あいさつ】に 行【い】きましょう。",furigana:"はい、ロビーに いますよ。後で 挨拶に 行きましょう。",romaji:"Hai, robii ni imasu yo. Ato de aisatsu ni ikimashou.",idText:"Ya, beliau ada di lobi. Nanti kita pergi menyapa beliau ya."}],vocab_breakdown:[{id:"v1",word:"ある",reading:"ある",romaji:"aru",meaning:"ada (benda mati/tumbuhan)",nuance:"Bentuk sopan: あります (arimasu). Bentuk negatif: ありません (arimasen). Dipakai untuk benda yang tidak berkehendak pindah sendiri.",particleTip:"〜が あります (ada benda...)",exampleSentence:{jp:"へやに つくえが あります。",furigana:"部屋に 机が あります。",romaji:"Heya ni tsukue ga arimasu.",idText:"Di kamar ada meja."}},{id:"v2",word:"いる",reading:"いる",romaji:"iru",meaning:"ada (makhluk bernyawa: manusia, hewan)",nuance:"Bentuk sopan: います (imasu). Bentuk negatif: いません (imasen). Khusus untuk entitas bernyawa yang bergerak bebas.",particleTip:"〜が います (ada orang/hewan...)",exampleSentence:{jp:"にわに ねこが います。",furigana:"庭に 猫が います。",romaji:"Niwa ni neko ga imasu.",idText:"Di halaman ada kucing."}},{id:"v3",word:"ねこ",reading:"ねこ",romaji:"neko",meaning:"kucing",nuance:"Makhluk hidup peliharaan umum di Jepang, selalu dipasangkan dengan います.",particleTip:"ねこが います。(Ada kucing.)",exampleSentence:{jp:"かわいい ねこが います。",furigana:"可愛い 猫が います。",romaji:"Kawaii neko ga imasu.",idText:"Ada kucing yang lucu."}},{id:"v4",word:"いぬ",reading:"いぬ",romaji:"inu",meaning:"anjing",nuance:"Makhluk bernyawa, selalu dipasangkan dengan います.",particleTip:"いぬが います。(Ada anjing.)",exampleSentence:{jp:"こうえんに いぬが います。",furigana:"公園に 犬が います。",romaji:"Kouen ni inu ga imasu.",idText:"Di taman ada anjing."}},{id:"v5",word:"れいぞうこ",reading:"れいぞうこ",romaji:"reizouko",meaning:"kulkas / lemari pendingin",nuance:"Perabot elektronik rumah tangga, benda mati -> dipasangkan dengan あります.",particleTip:"れいぞうこが あります。(Ada kulkas.)",exampleSentence:{jp:"だいどころに れいぞうこが あります。",furigana:"台所に 冷蔵庫が あります。",romaji:"Daidokoro ni reizouko ga arimasu.",idText:"Di dapur ada kulkas."}},{id:"v6",word:"へや",reading:"へや",romaji:"heya",meaning:"kamar / ruangan",nuance:"Ruangan tempat tinggal atau kamar asrama.",exampleSentence:{jp:"わたしの へやは 2かいに あります。",furigana:"私の 部屋は 2階に あります。",romaji:"Watashi no heya wa nikai ni arimasu.",idText:"Kamar saya ada di lantai 2."}},{id:"v7",word:"つくえ",reading:"つくえ",romaji:"tsukue",meaning:"meja belajar / meja kerja",exampleSentence:{jp:"つくえの うえに ほんが あります。",furigana:"机の 上に 本が あります。",romaji:"Tsukue no ue ni hon ga arimasu.",idText:"Di atas meja ada buku."}},{id:"v8",word:"テレビ",reading:"テレビ",romaji:"terebi",meaning:"televisi",exampleSentence:{jp:"へやに テレビが あります。",furigana:"部屋に テレビが あります。",romaji:"Heya ni terebi ga arimasu.",idText:"Di kamar ada TV."}}],explanations:[{id:"exp-u03-01-1",grammarId:"gn5-00061",title:"Pola Inti: Pembedaan Arimasu vs Imasu",formula:"[Benda Mati] が あります / [Makhluk Hidup] が います",meaning:"Menyatakan keberadaan suatu objek, perabot, atau makhluk hidup di suatu tempat.",nuanceNotes:"Bahasa Jepang mewajibkan pembagian entitas: benda mati atau benda tidak bernyawa (buku, meja, uang, gedung) memakai あります (arimasu). Sebaliknya manusia dan hewan (anak, guru, anjing, burung) memakai います (imasu). Subjek entitas selalu ditandai partikel が (ga).",patternLogic:"Pola pikir bahasa Jepang membedakan keberadaan pasif (arimasu) dan keberadaan aktif berkehendak (imasu).",examples:[{jp:"つくえの うえに ほんが あります。",furigana:"机の 上に 本が あります。",romaji:"Tsukue no ue ni hon ga arimasu.",idText:"Ada buku di atas meja."},{jp:"ロビーに たなかさんが います。",furigana:"ロビーに 田中さんが います。",romaji:"Robii ni Tanaka-san ga imasu.",idText:"Ada Tanaka-san di lobi."}]},{id:"exp-u03-01-2",grammarId:"gn5-00006",title:"Bentuk Penyangkalan (Negatif) Keberadaan",formula:"〜が ありません (Tidak ada benda) / 〜が いません (Tidak ada orang/hewan)",meaning:"Menyatakan ketidakadaan suatu entitas atau meniadakan keberadaan.",nuanceNotes:'Bila menyatakan sesuatu tidak ada, ubah "arimasu" menjadi "arimasen", dan "imasu" menjadi "imasen". Jika kata benda dijadikan topik pembicaraan ("soal kulkas..."), partikel "ga" dapat berganti menjadi "wa" (contoh: れいぞうこは ありません).',examples:[{jp:"へやに れいぞうこは ありません。",furigana:"部屋に 冷蔵庫は ありません。",romaji:"Heya ni reizouko wa arimasen.",idText:"Di kamar tidak ada kulkas."},{jp:"きょうしつに だれも いません。",furigana:"教室に 誰も いません。",romaji:"Kyoushitsu ni dare mo imasen.",idText:"Di kelas tidak ada siapa pun."}]}],drills:[{id:"drill-u03-01-1",type:"vocab_context",instruction:'Langkah 1 (Arti & Konsep): Manakah pasangan kata kerja keberadaan yang tepat untuk "kucing" dan "kulkas"?',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["Kucing: います | Kulkas: あります","Kucing: あります | Kulkas: います","Kucing: です | Kulkas: あります","Kucing: います | Kulkas: です"],correctAnswer:"Kucing: います | Kulkas: あります",explanation:"Kucing adalah makhluk bernyawa (います), sedangkan kulkas adalah perabot mati (あります).",diagnosticFeedback:{"Kucing: あります | Kulkas: います":'Jebakan Konjugasi: Bentuk predikat "Kucing: あります | Kulkas: います" tidak sesuai dengan kala waktu (tenses) atau tingkat kesantunan kalimat.',"Kucing: です | Kulkas: あります":'Jebakan Partikel: Pilihan "Kucing: です | Kulkas: あります" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.',"Kucing: います | Kulkas: です":'Jebakan Partikel: Pilihan "Kucing: います | Kulkas: です" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.'}},{id:"drill-u03-01-2",type:"cloze",instruction:"Langkah 2 (Isi Partikel): Lengkapi kalimat: 「へやに テレビ（　）あります。」",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["が","を","は","で"],correctAnswer:"が",explanation:"Dalam kalimat keberadaan, entitas yang ada ditandai dengan partikel subjek が (ga).",diagnosticFeedback:{を:'Jebakan Partikel: Pilihan "を" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.',は:'Jebakan Partikel: Pilihan "は" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.',で:'Jebakan Partikel: Pilihan "で" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.'}},{id:"drill-u03-01-3",type:"reorder",instruction:'Langkah 3 (Susun Kalimat): Susun kepingan kata berikut menjadi kalimat: "Di kamar ada kucing."',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["へやに ねこが います。","ねこが へやに います。","ねこが います。 へやに","へやに います。 ねこが"],correctAnswer:"へやに ねこが います。",explanation:"Susunan alami: [Lokasi] に + [Subjek Bernyawa] が + います。",diagnosticFeedback:{"ねこが へやに います。":'Jebakan Susunan: Urutan kata pada frasa "ねこが へやに います。" terbalik atau tidak selaras dengan struktur kalimat bahasa Jepang yang alami.',"ねこが います。 へやに":'Jebakan Susunan: Urutan kata pada frasa "ねこが います。 へやに" terbalik atau tidak selaras dengan struktur kalimat bahasa Jepang yang alami.',"へやに います。 ねこが":'Jebakan Susunan: Urutan kata pada frasa "へやに います。 ねこが" terbalik atau tidak selaras dengan struktur kalimat bahasa Jepang yang alami.'},tokens:["へやに","ねこが","います。"],correctOrder:["0","1","2"]},{id:"drill-u03-01-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Kalimat Alami): Manakah kalimat yang benar dan berterima secara wajar?",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["こうえんに いぬが います。","こうえんに いぬが あります。","こうえんに いぬを います。"],correctAnswer:"こうえんに いぬが います。",explanation:'Anjing adalah hewan (makhluk hidup), maka wajib memakai "ga imasu", bukan "arimasu" atau partikel "o".',diagnosticFeedback:{"こうえんに いぬが あります。":"Jebakan Benda Mati: Anjing adalah hewan bernyawa, pantang menggunakan あります!","こうえんに いぬを います。":"Jebakan Partikel: Keberadaan adalah intransitif, gunakan partikel が, jangan partikel を!"}},{id:"drill-u03-01-5",type:"response",instruction:"Langkah 5 (Respons Situasional): Rekan kerjamu bertanya: 「ロビーに だれか いますか。」 Bagaimanakah jawabanmu bila di lobi ada Tanaka-san?",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["はい、たなかさんが います。","はい、たなかさんが あります。","いいえ、たなかさんが います。","はい、つくえが います。"],correctAnswer:"はい、たなかさんが います。",explanation:'Menyatakan keberadaan orang menggunakan "はい、[Nama Orang]さんが います。"',diagnosticFeedback:{"はい、たなかさんが あります。":"Fatal: Tanaka-san adalah manusia, pantang disebut dengan あります!","いいえ、たなかさんが います。":'Kontradiktif: Menggunakan kata "iie" padahal Tanaka-san ada di sana.',"はい、つくえが います。":"Salah konteks dan kategori: Pertanyaan menanyakan orang (dareka), bukan meja (benda mati)."}}],can_do_challenge:{statement:"Bisa menyatakan keberadaan perabot kamar dan hewan peliharaan secara tepat tanpa tertukar.",situation:"Sedang mengecek isi kamar asrama bersama pengelola asrama atau rekan sekamar.",promptTask:"Katakan bahwa di kamarmu ada meja dan televisi, serta di luar ada kucing!",modelAnswer:"へやに つくえと テレビが あります。そとに ねこが います。",modelAnswerId:"Di kamar ada meja dan TV. Di luar ada kucing.",culturalEtiquette:"Gunakan intonasi ramah dan pastikan pembedaan arimasu/imasu terdengar jelas.",skillUnlocked:["Menguasai pembedaan esensial benda mati (arimasu) dan makhluk bernyawa (imasu)","Mampu mendeskripsikan inventaris kamar asrama dengan partikel ga"],pocketSummary:{keyFormula:"[Benda Mati] が あります / [Makhluk Hidup] が います",coreWords:["ある (ada - benda)","いる (ada - bernyawa)","ねこ (kucing)","つくえ (meja)"],coreWarning:"JANGAN PERNAH menyebut manusia/hewan dengan arimasu (dianggap barang mati)!",quickDialogue:"A: なにか ありますか？ → B: つくえが あります。ねこも います。"}},pocket_summary:{keyFormula:"[Benda Mati] が あります / [Makhluk Hidup] が います",coreWords:["ある (benda mati)","いる (makhluk hidup)","ねこ (kucing)","つくえ (meja)"],coreWarning:"JANGAN PERNAH memakai arimasu untuk orang atau hewan peliharaan!",quickDialogue:"A: なにか ありますか？ → B: テレビが あります。ねこが います。"}},"les-n5-u03-02":{pedagogical_framework:{what:{summary:"Pola penunjuk posisi spasial detail (atas, bawah, dalam, depan, belakang, samping) dengan partikel lokasi に (ni).",canDo:"Bisa mendeskripsikan letak benda atau seseorang secara akurat (misal: kunci ada di atas meja, kucing di bawah kursi).",targetPatterns:["〜の [Posisi] に あります/います","に (penanda letak keberadaan)"],coreVocabSample:["うえ","した","まえ","うしろ","なか","そと","となり","あいだ","いす","ほん","かばん"]},sensei_context:{sceneIntro:"Kamu sedang bersiap-siap berangkat bekerja atau kuliah, tetapi kartu izin tinggal (Zairyu Card) atau kuncimu terselip. Kamu mencari barang tersebut bersama rekanmu di kamar.",dailyMission:'Mampu menanyakan dan menunjukkan letak persis suatu benda di atas, bawah, dalam laci, atau di samping perabot lain menggunakan partikel "ni".',whyOrder:'Dalam bahasa Indonesia kita menyebut "di atas meja", susunannya [posisi + benda]. Namun dalam bahasa Jepang susunannya dibalik: [Benda + NO + Posisi + NI]. Menguasai struktur terbalik ini adalah kunci agar kamu tidak salah paham saat diperintah mencari alat kerja!'},cultural_notes:{title:"Kerapian dan Lokasi Tetap (Teiichi) di Lingkungan Kerja Jepang",etiquette:"Di Jepang ada prinsip 5S (Seiri, Seiton, Seisou, Seiketsu, Shitsuke). Setiap barang perkakas atau dokumen memiliki lokasi penyimpanan tetap (Teiichi / 定位置). Menyebutkan posisi barang dengan presisi adalah kecakapan wajib di tempat kerja.",taboos:'Waspadai kata "tonari" (隣) vs "yoko" (横). "Tonari" hanya digunakan untuk dua benda sejenis yang berdampingan (gedung di sebelah gedung, orang di samping orang). Jangan gunakan "tonari" untuk anjing di samping mobil!'},pronunciation_tips:{title:"Intonasi Partikel No dan Ni pada Keterangan Tempat",moraNote:'Frasa posisi dibaca mengalir sebagai satu kesatuan nafas: "tsukue-no-ue-ni", jangan terputus-putus gagap.',soundTip:'Partikel "ni" (に) diucapkan pendek dan lugas, menandai titik target keberadaan.'},common_pitfalls:[{title:"Jebakan Urutan Spasial Terbalik (Pengaruh Bahasa Indonesia)",caseScenario:'Ingin mengatakan "di atas meja", lalu menyusun "ue no tsukue".',pitfallWarning:'"うえの つくえに かぎが あります。" (Ue no tsukue ni kagi ga arimasu)',rightSolution:'"つくえの うえに かぎが あります。" (Tsukue no ue ni kagi ga arimasu)',explanation:"Di bahasa Indonesia: [di atas] [meja]. Di bahasa Jepang: [meja] の [atas] に. Benda acuan selalu berada di depan partikel の (no)!"},{title:"Tertukar Partikel Ni (Letak) dan De (Tempat Aktivitas)",caseScenario:'Memakai partikel "de" untuk kalimat keberadaan yang tidak ada aktivitas aksi.',pitfallWarning:'"へやで テレビが あります。" (Heya de terebi ga arimasu)',rightSolution:'"へやに テレビが あります。" (Heya ni terebi ga arimasu)',explanation:'Partikel "de" (で) dipakai untuk lokasi terjadinya suatu kegiatan/aksi (makan, belajar, bekerja). Sedangkan keberadaan statis (arimasu/imasu) WAJIB memakai partikel "ni" (に).'}],who_and_when:{situational_context:"Mencari barang hilang, meletakkan alat kerja di pabrik/toko, atau memberi petunjuk arah di dalam ruangan.",social_relations:"Dapat dipakai kepada siapa saja, baik rekan kerja, atasan, maupun pelanggan dalam situasi sehari-hari.",when_not_to_use:'Bila ada aktivitas aktif yang terjadi di tempat tersebut (misal: "belajar di kamar"), gunakan partikel で (de), bukan に (ni).'},scenario:{title:"Mencari Kunci Asrama yang Terselip",setting:"Ruang Kamar Asrama Budi",narrative:"Budi hendak berangkat bersama Sakura, tetapi kunci kamar asramanya tidak ada di saku. Sakura membantu mencari di sekeliling meja dan sofa."}},dialogue:[{id:"d1",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"さくらさん、すみません。部屋【へや】の 鍵【かぎ】が ありません。",furigana:"さくらさん、すみません。部屋の 鍵が ありません。",romaji:"Sakura-san, sumimasen. Heya no kagi ga arimasen.",idText:"Sakura-san, maaf. Kunci kamar saya tidak ada."},{id:"d2",speaker:"Sakura",speakerRole:"Senior Jepang",avatar:"👩‍💼",jp:"えっ、鍵【かぎ】ですか。机【つくえ】の 上【うえ】に ありませんか。",furigana:"えっ、鍵ですか。机の 上に ありませんか。",romaji:"E', kagi desu ka. Tsukue no ue ni arimasen ka.",idText:"Eh, kunci? Apakah tidak ada di atas meja?"},{id:"d3",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"机【つくえ】の 上【うえ】には 本【ほん】と ノートだけ あります。鍵【かぎ】は ありません。",furigana:"机の 上には 本と ノートだけ あります。鍵は ありません。",romaji:"Tsukue no ue ni wa hon to nooto dake arimasu. Kagi wa arimasen.",idText:"Di atas meja hanya ada buku dan catatan. Kunci tidak ada."},{id:"d4",speaker:"Sakura",speakerRole:"Senior Jepang",avatar:"👩‍💼",jp:"鞄【かばん】の 中【なか】は どうですか。見【み】て みましたか。",furigana:"鞄の 中は どうですか。見て みましたか。",romaji:"Kaban no naka wa dou desu ka. Mite mimashita ka.",idText:"Di dalam tas bagaimana? Sudah coba lihat?"},{id:"d5",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"あ、鞄【かばん】の 中【なか】にも ありません！どうしよう...",furigana:"あ、鞄の 中にも ありません！どうしよう...",romaji:"A, kaban no naka ni mo arimasen! Dou shiyou...",idText:"Ah, di dalam tas pun tidak ada! Bagaimana ini..."},{id:"d6",speaker:"Sakura",speakerRole:"Senior Jepang",avatar:"👩‍💼",jp:"あ、ブディさん！椅子【いす】の 下【した】を 見【み】てください。ほら、あそこに ありますよ！",furigana:"あ、ブディさん！椅子の 下を 見てください。ほら、あそこに ありますよ！",romaji:"A, Budi-san! Isu no shita o mite kudasai. Hora, asoko ni arimasu yo!",idText:"Ah, Budi-san! Coba lihat di bawah kursi. Tuh, ada di sana lho!",note:"Sakura menunjuk ke kolong kursi meja belajar"},{id:"d7",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"わあ、本当だ！椅子【いす】の 下【した】に ありました！ありがとうございます、さくらさん。",furigana:"わあ、本当だ！椅子の 下に ありました！ありがとうございます、さくらさん。",romaji:"Waa, hontou da! Isu no shita ni arimashita! Arigatou gozaimasu, Sakura-san.",idText:"Wah, benar sekali! Ada di bawah kursi! Terima kasih banyak, Sakura-san."}],vocab_breakdown:[{id:"v1",word:"うえ",reading:"うえ",romaji:"ue",meaning:"atas",nuance:"Posisi di atas permukaan benda acuan.",particleTip:"Acuan + の + うえ (atasnya benda acuan).",exampleSentence:{jp:"つくえの うえに ほんが あります。",furigana:"机の 上に 本が あります。",romaji:"Tsukue no ue ni hon ga arimasu.",idText:"Di atas meja ada buku."}},{id:"v2",word:"した",reading:"した",romaji:"shita",meaning:"bawah / kolong",nuance:"Posisi di bawah atau kolong benda acuan.",particleTip:"いすの した (bawah kursi).",exampleSentence:{jp:"いすの したに ねこが います。",furigana:"椅子の 下に 猫が います。",romaji:"Isu no shita ni neko ga imasu.",idText:"Di bawah kursi ada kucing."}},{id:"v3",word:"なか",reading:"なか",romaji:"naka",meaning:"dalam / bagian dalam",nuance:"Posisi interior suatu wadah, ruangan, atau tas.",particleTip:"かばんの なか (dalam tas).",exampleSentence:{jp:"はこの なかに なにか ありますか。",furigana:"箱の 中に 何か ありますか。",romaji:"Hako no naka ni nanika arimasu ka.",idText:"Apakah ada sesuatu di dalam kotak?"}},{id:"v4",word:"そと",reading:"そと",romaji:"soto",meaning:"luar",exampleSentence:{jp:"へやの そとに いぬが います。",furigana:"部屋の 外に 犬が います。",romaji:"Heya no soto ni inu ga imasu.",idText:"Di luar kamar ada anjing."}},{id:"v5",word:"まえ",reading:"まえ",romaji:"mae",meaning:"depan",exampleSentence:{jp:"ドアの まえに だれか います。",furigana:"ドアの 前に 誰か います。",romaji:"Doa no mae ni dareka imasu.",idText:"Di depan pintu ada seseorang."}},{id:"v6",word:"うしろ",reading:"うしろ",romaji:"ushiro",meaning:"belakang",exampleSentence:{jp:"くるまの うしろに じてんしゃが あります。",furigana:"車の 後ろに 自転車が あります。",romaji:"Kuruma no ushiro ni jitensha ga arimasu.",idText:"Di belakang mobil ada sepeda."}},{id:"v7",word:"となり",reading:"となり",romaji:"tonari",meaning:"sebelah / samping (sejenis)",exampleSentence:{jp:"ぎんこうの となりに ゆうびんきょくが あります。",furigana:"銀行の 隣に 郵便局が あります。",romaji:"Ginkou no tonari ni yuubinkyoku ga arimasu.",idText:"Di sebelah bank ada kantor pos."}},{id:"v8",word:"あいだ",reading:"あいだ",romaji:"aida",meaning:"antara (di antara dua titik)",nuance:"A と B の あいだ (di antara A dan B).",exampleSentence:{jp:"ほんと ノートの あいだに ペンが あります。",furigana:"本と ノートの 間に ペンが あります。",romaji:"Hon to nooto no aida ni pen ga arimasu.",idText:"Di antara buku dan buku catatan ada pulpen."}},{id:"v9",word:"かぎ",reading:"かぎ",romaji:"kagi",meaning:"kunci",exampleSentence:{jp:"へやの かぎが ありません。",furigana:"部屋の 鍵が ありません。",romaji:"Heya no kagi ga arimasen.",idText:"Kunci kamar tidak ada."}},{id:"v10",word:"いす",reading:"いす",romaji:"isu",meaning:"kursi",exampleSentence:{jp:"いすの うえに かばんが あります。",furigana:"椅子の 上に 鞄が あります。",romaji:"Isu no ue ni kaban ga arimasu.",idText:"Di atas kursi ada tas."}}],explanations:[{id:"exp-u03-02-1",grammarId:"gn5-00009",title:"Formula Penunjuk Posisi Spasial",formula:"[Benda Acuan] の [Posisi: 上/下/中/前/後/隣] に [Subjek] が あります/います",meaning:"Menjelaskan titik koordinat lokasi suatu benda atau seseorang relatif terhadap benda acuan.",nuanceNotes:'Selalu letakkan benda patokan di awal sebelum partikel の (no). Contoh: "meja" adalah patokan, "atas" adalah posisi -> つくえの うえ (tsukue no ue). Kemudian tambahkan partikel に (ni) untuk menunjukkan koordinat keberadaan tempat.',examples:[{jp:"つくえの うえに かぎが あります。",furigana:"机の 上に 鍵が あります。",romaji:"Tsukue no ue ni kagi ga arimasu.",idText:"Kunci ada di atas meja."},{jp:"いすの したに ねこが います。",furigana:"椅子の 下に 猫が います。",romaji:"Isu no shita ni neko ga imasu.",idText:"Kucing ada di bawah kursi."}]},{id:"exp-u03-02-2",grammarId:"gn5-00062",title:"Pola Samping: となり (Tonari) vs よこ (Yoko)",formula:"A の となり (bersebelahan sejenis) / A の よこ (posisi horizontal apa saja)",meaning:"Membedakan konsep samping dalam tata ruang bahasa Jepang.",nuanceNotes:"となり (tonari) menyiratkan hubungan berdampingan yang setara/sejenis (misal: rumah di samping rumah, orang di sebelah orang). Sedangkan よこ (yoko) murni menunjukkan koordinat sumbu horizontal kiri/kanan tanpa memandang jenis bendanya.",examples:[{jp:"ぎんこうの となりに ゆうびんきょくが あります。",furigana:"銀行の 隣に 郵便局が あります。",romaji:"Ginkou no tonari ni yuubinkyoku ga arimasu.",idText:"Di sebelah bank ada kantor pos."}]}],drills:[{id:"drill-u03-02-1",type:"vocab_context",instruction:"Langkah 1 (Arti & Arah): Apakah arti frasa bahasa Jepang 「つくえの した」?",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["Bawah meja","Atas meja","Dalam meja","Samping meja"],correctAnswer:"Bawah meja",explanation:"した (shita) berarti bawah. Maka つくえの した berarti bawah meja.",diagnosticFeedback:{"Atas meja":'Pilihan "Atas meja" keliru karena tidak selaras dengan kaidah pola gn5-00009.',"Dalam meja":'Pilihan "Dalam meja" keliru karena tidak selaras dengan kaidah pola gn5-00009.',"Samping meja":'Pilihan "Samping meja" keliru karena tidak selaras dengan kaidah pola gn5-00009.'}},{id:"drill-u03-02-2",type:"cloze",instruction:"Langkah 2 (Isi Partikel): Lengkapi kalimat: 「かぎは かばんの なか（　）あります。」",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["に","で","を","と"],correctAnswer:"に",explanation:"Partikel に (ni) adalah penanda letak keberadaan bagi verba あります/います.",diagnosticFeedback:{で:'Jebakan Partikel: Pilihan "で" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.',を:'Jebakan Partikel: Pilihan "を" tidak tepat untuk peran gramatikal kalimat ini. Pelajari fungsi partikel terkait.',と:'Pilihan "と" keliru karena tidak selaras dengan kaidah pola gn5-00009.'}},{id:"drill-u03-02-3",type:"reorder",instruction:'Langkah 3 (Susun Kalimat): Susun kepingan kata berikut menjadi kalimat: "Kucing ada di bawah kursi."',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["いすの したに ねこが います。","したに いすの ねこが います。","したに ねこが います。 いすの","いすの ねこが います。 したに"],correctAnswer:"いすの したに ねこが います。",explanation:"Susunan baku: [Benda Acuan] の [Posisi] に + [Subjek] が + います。",diagnosticFeedback:{"したに いすの ねこが います。":'Jebakan Susunan: Urutan kata pada frasa "したに いすの ねこが います。" terbalik atau tidak selaras dengan struktur kalimat bahasa Jepang yang alami.',"したに ねこが います。 いすの":'Jebakan Susunan: Urutan kata pada frasa "したに ねこが います。 いすの" terbalik atau tidak selaras dengan struktur kalimat bahasa Jepang yang alami.',"いすの ねこが います。 したに":'Jebakan Susunan: Urutan kata pada frasa "いすの ねこが います。 したに" terbalik atau tidak selaras dengan struktur kalimat bahasa Jepang yang alami.'},tokens:["いすの","したに","ねこが","います。"],correctOrder:["0","1","2","3"]},{id:"drill-u03-02-4",type:"trap_detect",instruction:'Langkah 4 (Deteksi Kalimat Alami): Manakah susunan kalimat yang benar saat ingin menyatakan "Buku ada di atas meja"?',sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["ほんは つくえの うえに あります。","ほんは うえの つくえに あります。","ほんは つくえの うえで あります。"],correctAnswer:"ほんは つくえの うえに あります。",explanation:"Benda acuan berada sebelum partikel の (つくえの うえ), dan partikel letak statis adalah に (ni).",diagnosticFeedback:{"ほんは うえの つくえに あります。":'Jebakan Urutan Terbalik: "Ue no tsukue" berarti "meja bagian atas", bukan "di atas meja"!',"ほんは つくえの うえで あります。":"Jebakan Partikel: Partikel で adalah tempat aktivitas aksi, keberadaan wajib memakai に!"}},{id:"drill-u03-02-5",type:"response",instruction:"Langkah 5 (Respons Situasional): Temanmu bertanya panik: 「わたしの さいふは どこですか。」 Kamu melihat dompetnya ada di dalam tas. Apa jawabanmu?",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["かばんの なかに ありますよ。","かばんの なかに いますよ。","かばんの したに いますよ。","つくえの うえに いますよ。"],correctAnswer:"かばんの なかに ありますよ。",explanation:"Dompet (saifu) adalah benda mati, berada di dalam tas -> かばんの なかに ありますよ。",diagnosticFeedback:{"かばんの なかに いますよ。":"Fatal: Dompet adalah barang mati, jangan memakai います!","かばんの したに いますよ。":"Salah posisi dan salah verba: Dompet ada di dalam (naka), bukan di bawah (shita), dan wajib arimasu.","つくえの うえに いますよ。":"Salah tempat dan salah verba."}}],can_do_challenge:{statement:"Bisa mendeskripsikan lokasi letak barang dan orang secara presisi dengan kata posisi spasial.",situation:"Sedang mencari barang kantor atau barang asrama yang terselip bersama rekan kerja.",promptTask:"Beri tahu rekanmu bahwa kuncinya ada di atas meja, dan dompetnya ada di dalam tas!",modelAnswer:"かぎは つくえの うえに あります。さいふは かばんの なかに あります。",modelAnswerId:"Kunci ada di atas meja. Dompet ada di dalam tas.",culturalEtiquette:"Tunjuk ke arah benda dengan telapak tangan terbuka ke atas, jangan menunjuk dengan satu jari telunjuk.",skillUnlocked:["Menguasai koordinat spasial bahasa Jepang (ue, shita, naka, mae, ushiro, tonari)","Mampu membantu rekan kerja menemukan barang dengan presisi di lingkungan kerja"],pocketSummary:{keyFormula:"[Acuan] の [Posisi] に [Benda/Orang] が あります/います",coreWords:["うえ (atas)","した (bawah)","なか (dalam)","となり (sebelah)"],coreWarning:"Urutan bahasa Jepang: [Benda Acuan] DULU baru [Posisi]! (Bukan kebalik)",quickDialogue:"A: かぎは どこですか？ → B: つくえの うえに ありますよ。"}},pocket_summary:{keyFormula:"[Acuan] の [Posisi] に あります/います",coreWords:["うえ (atas)","した (bawah)","なか (dalam)","まえ (depan)"],coreWarning:"Benda acuan selalu di depan の (tsukue no ue, bukan ue no tsukue)!",quickDialogue:"A: どこに ありますか？ → B: いすの したに あります。"}}},i={"les-n5-u04-01":{pedagogical_framework:{what:{summary:"Verba transitif dengan partikel penanda objek を (wo/o), permohonan santun 〜をください, dan frekuensi kerja 毎日 (mainichi).",canDo:"Bisa menyatakan aktivitas konsumsi, pemrosesan dokumen, dan rutinitas kerja harian secara sopan.",targetPatterns:["[Objek] を [Verba Transitif]","〜を ください","毎日 (mainichi)"],coreVocabSample:["コーヒー","ほん","レポート","まいにち","よみます","のみます"]},sensei_context:{sceneIntro:"Pagi hari di ruang istirahat kantor. Tanaka-senpai menanyakan rutinitas pagi Budi sebelum memulai shift kerja.",dailyMission:"Gunakan partikel を dengan tepat untuk menandai objek kata kerja, dan minta berkas/dokumen dengan 〜をください.",whyOrder:'Setelah bisa memperkenalkan diri dan menunjuk benda (Unit 1–3), sekarang kita belajar "beraksi" dengan kata kerja transitif!'},cultural_notes:{title:"Etika Minum Kopi Pagi & Menerima Dokumen Kerja",etiquette:'Gunakan kedua tangan saat menerima dokumen atau cangkir teh dari senior, sembari mengangguk dan berucap "Arigatou gozaimasu".',taboos:'Jangan melafalkan partikel を sebagai "wo" tebal. Dalam percakapan modern, aksara を dilafalkan sama persis dengan "o".'},pronunciation_tips:{title:"Pelafalan Partikel を (o)",moraNote:"Partikel を diucapkan satu ketukan mora tanpa jeda pemisah dari kata benda sebelumnya.",soundTip:'Lafalkan "hon o" secara menyatu halus: "hon-o", bukan "hon... WO".'},common_pitfalls:[{title:'Jebakan Menyelipkan Kata "Di" Sebelum Objek',caseScenario:'Refleks menyusun kalimat seperti bahasa Indonesia: "Saya membaca di buku".',pitfallWarning:'"ほん で よみます。" (Salah)',rightSolution:'"ほん を よみます。" (Benar)',explanation:"Objek langsung yang dibaca atau dikonsumsi selalu ditandai partikel を, bukan で."},{title:"Salah Meletakkan Posisi Predikat (SVO vs SOV)",caseScenario:"Menaruh kata kerja sebelum objek seperti bahasa Indonesia.",pitfallWarning:'"のみます コーヒー を。" (Salah)',rightSolution:'"コーヒー を のみます。" (Benar)',explanation:"Bahasa Jepang selalu menaruh kata kerja di akhir kalimat: Objek + を + Verba."}],who_and_when:{situational_context:"Pagi hari saat briefing kerja, memesan kopi di kafetaria, atau meminta formulir.",social_relations:"Ragam sopan (Teineigo) yang sangat tepat untuk berbicara dengan atasan atau senior kerja.",when_not_to_use:"Jangan memakai 〜をちょうだい kepada atasan; gunakan 〜をください."},scenario:{title:"Rutinitas Pagi di Kantor Shinjuku",setting:"Ruang istirahat staf, pukul 08.45",narrative:"Tanaka menyapa Budi yang sedang membaca berkas panduan kerja di meja istirahat sebelum briefing dimulai."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"ブディさん、おはようございます。朝【あさ】早【はや】いですね。",furigana:"ブディさん、おはようございます。朝早いですね。",romaji:"Budi-san, ohayou gozaimasu. Asa hayai desu ne.",idText:"Selamat pagi, Budi-san. Pagi sekali ya datangnya."},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"田中【たなか】さん、おはようございます！毎日【まいにち】８時【はちじ】に 来【き】ます。",furigana:"田中さん、おはようございます！毎日８時に 来ます。",romaji:"Tanaka-san, ohayou gozaimasu! Mainichi hachiji ni kimasu.",idText:"Selamat pagi, Tanaka-san! Setiap hari saya datang pukul delapan."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"何【なに】を 読【よ】んでいますか？",furigana:"何を 読んでいますか？",romaji:"Nani o yonde imasu ka?",idText:"Sedang membaca apa?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"仕事【しごと】の マニュアルを 読【よ】みます。それから コーヒーを のみます。",furigana:"仕事の マニュアルを 読みます。それから コーヒーを 飲みます。",romaji:"Shigoto no manyuaru o yomimasu. Sore kara ko-hi- o nomimasu.",idText:"Saya membaca buku panduan kerja. Setelah itu saya minum kopi."},{id:"d5",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"ブディさん、熱【あつ】い お茶【ちゃ】も ありますよ。",furigana:"ブディさん、熱い お茶も ありますよ。",romaji:"Budi-san, atsui ocha mo arimasu yo.",idText:"Budi-san, ada teh panas juga lho."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"あ、ありがとうございます。その お茶【ちゃ】を ください。",furigana:"あ、ありがとうございます。その お茶を ください。",romaji:"A, arigatou gozaimasu. Sono ocha o kudasai.",idText:"Ah, terima kasih banyak. Tolong berikan teh itu ya."},{id:"d7",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"朝【あさ】の 準備【じゅんび】が いいですね。今日も 頑張【がんば】りましょう。",furigana:"朝の 準備が いいですね。今日も 頑張りましょう。",romaji:"Asa no junbi ga ii desu ne. Kyou mo gambarimashou.",idText:"Persiapan pagi yang bagus. Hari ini mari kita bersemangat juga."},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！今日も よろしく お願【ねが】いします。",furigana:"はい！今日も よろしく お願いします。",romaji:"Hai! Kyou mo yoroshiku onegaishimasu.",idText:"Baik! Mohon bimbingannya hari ini juga."}],vocab_breakdown:[{id:"vg-n5-00011",word:"帰る",reading:"かえる",romaji:"kaeru",meaning:"pulang, kembali ke rumah",pos:"verb-u",nuance:"Godan meski berakhiran る. Beda dengan 戻る (kembali ke tempat sebelumnya).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"６時に家に帰ります。",furigana:"６時に家に帰ります。",romaji:"",idText:"Saya pulang jam 6."}},{id:"vg-n5-00012",word:"書く",reading:"かく",romaji:"kaku",meaning:"menulis",pos:"verb-u",nuance:"図書館 = perpustakaan umum. Beda: 本屋 (honya) = toko buku.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"図書館で本を借りることができます。",furigana:"図書館で本を借りることができます。",romaji:"",idText:"Di perpustakaan bisa meminjam buku."}},{id:"vg-n5-00019",word:"住む",reading:"すむ",romaji:"sumu",meaning:"tinggal, menetap",pos:"verb-u",nuance:"Untuk tempat tinggal permanen. 〜に住む pakai partikel に.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"東京に住んでいます。",furigana:"東京に住んでいます。",romaji:"",idText:"Saya tinggal di Tokyo."}},{id:"vg-n5-00030",word:"働く",reading:"はたらく",romaji:"hataraku",meaning:"bekerja",pos:"verb-u",nuance:"寝る = tidur/berbaring. 寝る時間 = jam tidur. Berbeda: 眠る (nemuru) = tertidur (intransitif).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"会社で働いています。",furigana:"会社で働いています。",romaji:"",idText:"Saya bekerja di perusahaan."}},{id:"vg-n5-00031",word:"話す",reading:"はなす",romaji:"hanasu",meaning:"berbicara",pos:"verb-u",nuance:"はたらく (働く) = bekerja (aktif). Berbeda: 仕事する (aktivitas kerja).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"日本語で話しましょう。",furigana:"日本語で話しましょう。",romaji:"",idText:"Ayo bicara dalam bahasa Jepang."}},{id:"vg-n5-00033",word:"読む",reading:"よむ",romaji:"yomu",meaning:"membaca",pos:"verb-u",nuance:"郵便局 = kantor pos. 郵便 = surat/pos. 郵便局でお金を送る = kirim uang di kantor pos.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"郵便局で荷物を送りました。",furigana:"郵便局で荷物を送りました。",romaji:"",idText:"Saya mengirim paket di kantor pos."}},{id:"vg-n5-00152",word:"仕事",reading:"しごと",romaji:"shigoto",meaning:"pekerjaan, kerja",pos:"verb-suru",nuance:"Umum untuk pekerjaan sehari-hari. Lebih formal: 業務 (gyoumu). Juga bisa pakai +する: 仕事する.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"仕事は何時に終わりますか。",furigana:"仕事は何時に終わりますか。",romaji:"",idText:"Kerja selesai jam berapa?"}},{id:"vg-n5-00187",word:"きく",reading:"きく",romaji:"kiku",meaning:"mendengarkan; bertanya",pos:"verb-u",nuance:"聞く = mendengarkan (musik, dll) ATAU bertanya. 聞こえる = terdengar (involuntar).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"音楽を聞きながら勉強します。",furigana:"音楽を聞きながら勉強します。",romaji:"",idText:"Saya belajar sambil mendengarkan musik."}},{id:"vg-n5-00188",word:"きる",reading:"きる",romaji:"kiru",meaning:"memakai (pakaian atas)",pos:"verb-ru",nuance:"着る = pakaian atas (kemeja, jaket, kimono). Beda: はく = bawah, かぶる = kepala.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"今日は白いシャツを着ています。",furigana:"今日は白いシャツを着ています。",romaji:"",idText:"Hari ini saya memakai kemeja putih."}},{id:"vg-n5-00193",word:"しぬ",reading:"しぬ",romaji:"shinu",meaning:"meninggal; mati",pos:"verb-u",nuance:"死ぬ = satu-satunya verb-u dengan ending ぬ. 亡くなる lebih halus untuk orang.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"その木は枯れて死にました。",furigana:"その木は枯れて死にました。",romaji:"",idText:"Pohon itu layu dan mati."}}],explanations:[{id:"exp-1",grammarId:"gn5-00007",title:"Pola: を (objek)",formula:"N + を + V",meaning:"partikel objek langsung",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"を (objek)",idText:"partikel objek langsung"}],examples:[{jp:"ごはんをたべます。",romaji:"",idText:"Makan nasi."},{jp:"にほんごをべんきょうします。",romaji:"",idText:"Belajar bahasa Jepang."},{jp:"おんがくをききます。",romaji:"",idText:"Mendengarkan musik."}]},{id:"exp-2",grammarId:"gn5-00089",title:"Pola: V-ます (習慣・事実)",formula:"V (ます-form)",meaning:"V secara teratur / V sebagai kenyataan atau rutinitas",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"V-ます (習慣・事実)",idText:"V secara teratur / V sebagai kenyataan atau rutinitas"}],examples:[{jp:"毎日、電車で会社へ行きます。",romaji:"",idText:"Setiap hari saya pergi ke kantor naik kereta."},{jp:"朝ごはんを食べます。",romaji:"",idText:"Saya makan sarapan (setiap hari)."},{jp:"6時に起きます。",romaji:"",idText:"Saya bangun jam 6."}]},{id:"exp-3",grammarId:"gn5-00034",title:"Pola: 〜ながら",formula:"V-ます語幹 + ながら",meaning:"sambil ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ながら",idText:"sambil ..."}],examples:[{jp:"おんがくをききながらべんきょうします。",romaji:"",idText:"Belajar sambil mendengarkan musik."},{jp:"あるきながらはなします。",romaji:"",idText:"Berbicara sambil berjalan."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah padanan arti kata "毎日 (まいにち)".',sentencePrompt:'Kata "毎日" artinya adalah:',options:["Setiap hari","Minggu depan","Kemarin lusa","Bulan lalu"],correctAnswer:"Setiap hari",explanation:'"毎日 (まいにち)" memiliki arti "setiap hari".',diagnosticFeedback:{"Minggu depan":"Salah: Minggu depan adalah 来週 (raishuu).","Kemarin lusa":"Salah: Kemarin lusa adalah おととい (ototoi).","Bulan lalu":"Salah: Bulan lalu adalah 先月 (sengetsu)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Isian Partikel): Pilihlah partikel penanda objek yang tepat.",sentencePrompt:"私【わたし】は 朝【あさ】コーヒー _____ のみます。",options:["を","に","で","は"],correctAnswer:"を",explanation:"Verba transitif 飲みます (minum) membutuhkan partikel を untuk menandai minuman sebagai objek.",diagnosticFeedback:{に:"Salah: Partikel に menandai tujuan atau titik waktu, bukan objek minuman.",で:"Salah: Partikel で menandai tempat berlangsungnya aksi, bukan objek penderita.",は:"Salah: Partikel は adalah penanda topik yang sudah terisi di awal kalimat."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Urutkan kata-kata berikut menjadi kalimat SOV yang tepat.",sentencePrompt:"Susunan kalimat yang tepat:",options:["私【わたし】は マニュアルを 読【よ】みます","マニュアルを 読【よ】みます 私【わたし】は","読【よ】みます 私【わたし】は マニュアルを","私【わたし】は 読【よ】みます マニュアルを"],correctAnswer:"私【わたし】は マニュアルを 読【よ】みます",explanation:"Struktur baku bahasa Jepang adalah Topik (私は) + Objek (マニュアルを) + Predikat (読みます).",diagnosticFeedback:{"マニュアルを 読【よ】みます 私【わたし】は":"Jebakan: Topik diletakkan di akhir kalimat.","読【よ】みます 私【わたし】は マニュアルを":"Jebakan: Kata kerja di awal kalimat menyalahi aturan SOV.","私【わたし】は 読【よ】みます マニュアルを":"Jebakan SVO: Memindahkan objek ke belakang kata kerja."},tokens:["私【わたし】は","マニュアルを","読【よ】みます"],correctOrder:["0","1","2"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Jebakan): Pilihlah kalimat yang benar dan alami.",sentencePrompt:"Manakah permintaan dokumen yang benar secara sopan?",options:["その レポートを ください。","その レポートで ください。","その レポートに ください。","レポート ください その。"],correctAnswer:"その レポートを ください。",explanation:"Meminta benda memakai pola [Kata Benda] + を ください.",diagnosticFeedback:{"その レポートで ください。":"Jebakan: Partikel で keliru dipakai untuk permintaan barang.","その レポートに ください。":"Jebakan: Partikel に salah untuk pola kudasai.","レポート ください その。":"Jebakan: Susunan kata terbalik acak."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat rekan kerja menawarkan "熱【あつ】い お茶【ちゃ】も ありますよ", respons terbaikmu adalah:',sentencePrompt:"Pilihlah respons yang paling sopan:",options:["ありがとうございます。その お茶【ちゃ】を ください。","いいえ、だめです。","お茶【ちゃ】は さようなら。","ごめんなさい、お茶【ちゃ】です。"],correctAnswer:"ありがとうございます。その お茶【ちゃ】を ください。",explanation:"Menyatakan terima kasih dan meminta teh dengan santun menggunakan をください.",diagnosticFeedback:{"いいえ、だめです。":"Terlalu kasar dan tidak sopan menolak tawaran rekan kerja.","お茶【ちゃ】は さようなら。":"Sayounara berarti selamat tinggal perpisahan, tidak nyambung.","ごめんなさい、お茶【ちゃ】です。":"Gomen nasai digunakan untuk meminta maaf atas kesalahan."}}],can_do_challenge:{statement:"Bisa menyatakan aktivitas konsumsi dan rutinitas kerja harian.",situation:"Mengobrol santai dengan supervisor sebelum jam kerja dimulai.",promptTask:"Katakan bahwa kamu membaca berkas dan minum teh setiap hari!",modelAnswer:"私【わたし】は 毎日【まいにち】書類【しょるい】を 読【よ】みます。それから お茶【ちゃ】を のみます。",modelAnswerId:"Saya setiap hari membaca dokumen. Setelah itu saya minum teh.",culturalEtiquette:"Gunakan partikel を secara jelas dan akhiran ます yang sopan.",skillUnlocked:["Menguasai verba transitif penanda objek を","Menguasai pola permohonan 〜をください"]},pocket_summary:{keyFormula:"[Kata Benda] を [Kata Kerja Transitif]",coreWords:["まいにち","のみます","よみます","ください"],coreWarning:"Objek langsung selalu menggunakan partikel を dan diletakkan sebelum predikat kerja.",quickDialogue:"A: 何を のみますか。 → B: コーヒーを のみます。"}},"les-n5-u04-02":{pedagogical_framework:{what:{summary:"Penanda waktu spesifik dengan partikel に, tempat berlangsungnya aktivitas dengan で, dan perkiraan waktu 〜ごろ.",canDo:"Bisa membuat janji temu, melaporkan jam mulai kerja, dan menyebutkan lokasi makan siang.",targetPatterns:["[Waktu Angka] に","[Tempat Aksi] で","〜ごろ (sekitar)"],coreVocabSample:["じかん","ひるやすみ","しょくどう","かいぎしつ","９じ","１２じ"]},sensei_context:{sceneIntro:"Di tempat kerja di Jepang, ketepatan waktu (Jikan Genshu) adalah harga mati. Tanaka-senpai menjelaskan jadwal shift dan istirahat siang.",dailyMission:"Mampu menyebutkan jam kerja dengan partikel に dan tempat aktivitas dengan partikel で secara akurat.",whyOrder:"Setelah bisa melakukan aksi, kita harus mengikat aksi tersebut ke waktu dan lokasi yang tepat."},cultural_notes:{title:"Prinsip Ketepatan Waktu Kerja Jepang (時間厳守 - Jikan Genshu)",etiquette:'Di Jepang, "hadir jam 9" berarti sudah siap di meja kerja pukul 08.50 (10 menit sebelum jam kerja). Datang pas jam 09.00 dianggap mepet.',taboos:"Jangan beri partikel に pada kata waktu relatif seperti 今日 (kyou), 明日 (ashita), 毎日 (mainichi). Partikel に hanya untuk angka jam/hari pasti!"},pronunciation_tips:{title:"Pelafalan Angka Jam",moraNote:'Perhatikan 4 jam dilafalkan "yo-ji" (bukan yon-ji), 7 jam dilafalkan "shichi-ji", 9 jam dilafalkan "ku-ji" (bukan kyuu-ji).',soundTip:'Lafalkan "kuji ni" dengan nada mengalir tanpa menekan keras kata depannya.'},common_pitfalls:[{title:"Memasang Partikel に pada Kata Keterangan Waktu Relatif",caseScenario:"Menambahkan に setelah kata kyou atau ashita.",pitfallWarning:'"きょう に はたらきます。" (Salah)',rightSolution:'"きょう はたらきます。" (Benar)',explanation:"Kata waktu relatif (hari ini, besok, lusa) tidak boleh diberi partikel に."},{title:"Tertukar Antara Partikel に (Keberadaan) vs で (Tempat Aksi)",caseScenario:"Menggunakan に untuk tempat makan atau bekerja.",pitfallWarning:'"しょくどう に ひるごはんを たべます。" (Salah)',rightSolution:'"しょくどう で ひるごはんを たべます。" (Benar)',explanation:"Tempat berlangsungnya aktivitas aktif (makan, kerja) wajib memakai で, bukan に."}],who_and_when:{situational_context:"Mengatur janji temu, menentukan jam makan siang, atau konfirmasi jadwal shift.",social_relations:"Ragam sopan standar (Teineigo) kepada rekan kerja dan atasan.",when_not_to_use:'Jangan salah mengucapkan 9 jam sebagai "kyuu-ji"; selalu ucapkan "ku-ji".'},scenario:{title:"Koordinasi Jam Makan Siang dan Rapat Shift",setting:"Lorong kantor lantai 2, pukul 11.30",narrative:"Budi menanyakan jam istirahat siang dan lokasi rapat kepada Sakura-san."}},dialogue:[{id:"d1",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"さくらさん、昼休【ひるやす】みは 何時【なんじ】からですか。",furigana:"さくらさん、昼休みは 何時からですか。",romaji:"Sakura-san, hiruyasumi wa nanji kara desu ka.",idText:"Sakura-san, istirahat siang mulai jam berapa ya?"},{id:"d2",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"１２時【じゅうにじ】からですよ。どこで 昼【ひる】ごはんを 食【た】べますか。",furigana:"１２時からですよ。どこで 昼ごはんを 食べますか。",romaji:"Juuniji kara desu yo. Doko de hirugohan o tabemasu ka.",idText:"Mulai jam 12 lho. Di mana kamu mau makan siang?"},{id:"d3",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"食堂【しょくどう】で 食【た】べます。さくらさんも 一緒【いっしょ】に 行【い】きませんか。",furigana:"食堂で 食べます。さくらさんも 一緒に 行きませんか。",romaji:"Shokudou de tabemasu. Sakura-san mo issho ni ikimasen ka.",idText:"Saya makan di kantin. Sakura-san mau pergi bersama?"},{id:"d4",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"いいですね！１２時半【じゅうにじはん】ごろ 行【い】きましょう。",furigana:"いいですね！１２時半ごろ 行きましょう。",romaji:"Ii desu ne! Juunijihan goro ikimashou.",idText:"Bagus tuh! Sekitar jam 12.30 mari kita pergi ya."},{id:"d5",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"午後【ごご】は １時【いちじ】に 会議室【かいぎしつ】で ミーティングが ありますよ。",furigana:"午後は １時に 会議室で ミーティングが ありますよ。",romaji:"Gogo wa ichiji ni kaigishitsu de mi-tingu ga arimasu yo.",idText:"Siang nanti jam 1 ada rapat di ruang pertemuan ya."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】しました。１時【いちじ】前【まえ】に 会議室【かいぎしつ】へ 行【い】きます。",furigana:"承知しました。１時前に 会議室へ 行きます。",romaji:"Shouchi shimashita. Ichiji mae ni kaigishitsu e ikimasu.",idText:"Saya pahami. Sebelum jam 1 saya akan menuju ruang rapat."},{id:"d7",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"時間【じかん】を 守【まも】って 行動【こうどう】してくださいね。",furigana:"時間を 守って 行動してくださいね。",romaji:"Jikan o mamotte koudou shite kudasai ne.",idText:"Bertindaklah dengan mematuhi waktu ya."},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、１０分前【じゅっぷんまえ】に 着席【ちゃくせき】します！",furigana:"はい、１０分前に 着席します！",romaji:"Hai, juppun mae ni chakuseki shimasu!",idText:"Baik, saya akan sudah duduk 10 menit sebelumnya!"}],vocab_breakdown:[{id:"vg-n5-00519",word:"休み",reading:"やすみ",romaji:"yasumi",meaning:"hari libur, istirahat",pos:"noun",nuance:"休み = istirahat/libur/cuti. 夏休み = libur musim panas. お休みなさい = selamat tidur.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"明日は休みですか。",furigana:"明日は休みですか。",romaji:"",idText:"Besok libur?"}},{id:"vg-n5-00520",word:"昼休み",reading:"ひるやすみ",romaji:"hiruyasumi",meaning:"istirahat siang",pos:"noun",nuance:"A midday break typically taken for lunch. In Japanese schools and companies, this is usually a strict, designated time period.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"昼休みに同僚とお弁当を食べました。",furigana:"昼休みに同僚とお弁当を食べました。",romaji:"",idText:"Saat istirahat siang saya makan bento bersama rekan kerja."}},{id:"vg-n5-00524",word:"銀行",reading:"ぎんこう",romaji:"ginkou",meaning:"bank, lembaga keuangan",pos:"noun",nuance:"銀行 = bank (tempat). Berbeda: お金 = uang. 銀行口座 = rekening bank.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"銀行でお金をおろします。",furigana:"銀行でお金をおろします。",romaji:"",idText:"Saya ambil uang di bank."}},{id:"vg-n5-00526",word:"辞書",reading:"じしょ",romaji:"jisho",meaning:"kamus",pos:"noun",nuance:"辞書 = kamus. 辞書を引く = mencari di kamus (ungkapan khas).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"わからない言葉は辞書で調べてください。",furigana:"わからない言葉は辞書で調べてください。",romaji:"",idText:"Kata yang tidak dimengerti, tolong cari di kamus."}},{id:"vg-n5-00527",word:"買いもの",reading:"かいもの",romaji:"kaimono",meaning:"belanja",pos:"noun",nuance:"Refers to the act of buying goods, most commonly daily necessities or groceries rather than large purchases. Often used with the verb する (to do).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"日曜日にスーパーへ買いものに行きます。",furigana:"日曜日にスーパーへ買いものに行きます。",romaji:"",idText:"Pada hari Minggu saya pergi berbelanja ke supermarket."}},{id:"vg-n5-00528",word:"来月",reading:"らいげつ",romaji:"raigetsu",meaning:"bulan depan",pos:"noun",nuance:"A relative time word that doesn't require a particle like に when used as an adverb in a sentence.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"来月、新しいアパートに引っ越します。",furigana:"来月、新しいアパートに引っ越します。",romaji:"",idText:"Bulan depan, saya akan pindah ke apartemen baru."}},{id:"vg-n5-00529",word:"食事",reading:"しょくじ",romaji:"shokuji",meaning:"makan, makan (kegiatan)",pos:"noun",nuance:"スーパー (スーパーマーケット) = supermarket.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"スーパーで野菜を買いました。",furigana:"スーパーで野菜を買いました。",romaji:"",idText:"Saya beli sayuran di supermarket."}},{id:"vg-n5-00530",word:"食堂",reading:"しょくどう",romaji:"shokudou",meaning:"kantin, kafetaria",pos:"noun",nuance:"デパート (デパートメントストア) = department store.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"誕生日プレゼントをデパートで買いました。",furigana:"誕生日プレゼントをデパートで買いました。",romaji:"",idText:"Saya beli hadiah ulang tahun di department store."}},{id:"vg-n5-00531",word:"食料品",reading:"しょくりょうひん",romaji:"shokuryouhin",meaning:"bahan makanan",pos:"noun",nuance:"A slightly formal word for food products sold in supermarkets. Compare with 'tabemono,' which is the general word for things you eat.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"デパートの地下で食料品を買いました。",furigana:"デパートの地下で食料品を買いました。",romaji:"",idText:"Saya membeli bahan makanan di lantai bawah tanah toserba."}},{id:"vg-n5-00532",word:"食べもの",reading:"たべもの",romaji:"tabemono",meaning:"makanan-minuman",pos:"noun",nuance:"A highly versatile, everyday word for anything edible. Literally means 'things to eat.'",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"好きな日本の食べものは寿司です。",furigana:"好きな日本の食べものは寿司です。",romaji:"",idText:"Makanan Jepang favorit saya adalah sushi."}}],explanations:[{id:"exp-1",grammarId:"gn5-00010",title:"Pola: に (waktu)",formula:"N (waktu spesifik) + に",meaning:"partikel waktu spesifik",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"に (waktu)",idText:"partikel waktu spesifik"}],examples:[{jp:"しちじにおきます。",romaji:"",idText:"Bangun jam tujuh."},{jp:"にちようびにえいがをみます。",romaji:"",idText:"Menonton film pada hari Minggu."}]},{id:"exp-2",grammarId:"gn5-00011",title:"Pola: で (lokasi tindakan)",formula:"N (tempat) + で + V (tindakan)",meaning:"partikel lokasi tindakan",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"で (lokasi tindakan)",idText:"partikel lokasi tindakan"}],examples:[{jp:"としょかんでべんきょうします。",romaji:"",idText:"Belajar di perpustakaan."},{jp:"レストランでたべます。",romaji:"",idText:"Makan di restoran."}]},{id:"exp-3",grammarId:"gn5-00087",title:"Pola: いつも / よく / あまり〜ない",formula:"Adverbia + V-ます / V-ません",meaning:"selalu / sering / jarang (adverbia frekuensi)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"いつも / よく / あまり〜ない",idText:"selalu / sering / jarang (adverbia frekuensi)"}],examples:[{jp:"いつもバスで行きます。",romaji:"",idText:"Saya selalu pergi naik bus."},{jp:"よく図書館で勉強します。",romaji:"",idText:"Saya sering belajar di perpustakaan."},{jp:"お肉はあまり食べません。",romaji:"",idText:"Saya jarang makan daging."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah arti yang tepat untuk "食堂 (しょくどう)".',sentencePrompt:'Kata "食堂" dalam konteks fasilitas kerja artinya:',options:["Kantin / Ruang makan","Kamar mandi staf","Gudang barang","Loket tiket"],correctAnswer:"Kantin / Ruang makan",explanation:'"食堂 (しょくどう)" berarti kantin atau ruang makan.',diagnosticFeedback:{"Kamar mandi staf":"Salah: Kamar mandi adalah お手洗い (otearai) atau トイレ.","Gudang barang":"Salah: Gudang adalah 倉庫 (souko).","Loket tiket":"Salah: Loket tiket adalah 切符売り場 (kippu uriba)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Isian Partikel Waktu): Pilihlah partikel penanda waktu jam pasti.",sentencePrompt:"午後【ごご】１時【いちじ】 _____ 会議【かいぎ】が 始【はじ】まります。",options:["に","で","を","と"],correctAnswer:"に",explanation:"Titik waktu jam pasti (1時) wajib ditandai partikel に.",diagnosticFeedback:{で:"Salah: Partikel で menandai tempat berlangsungnya aksi, bukan titik waktu jam.",を:"Salah: Partikel を menandai objek kata kerja transitif.",と:'Salah: Partikel と menandai rekan penyerta atau hubungan "dan".'}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Urutkan frasa tempat dan aksi berikut secara tepat.",sentencePrompt:"Susunan kalimat yang tepat:",options:["食堂【しょくどう】で 昼【ひる】ごはんを 食【た】べます","昼【ひる】ごはんを 食【た】べます 食堂【しょくどう】で","食【た】べます 食堂【しょくどう】で 昼【ひる】ごはんを","食堂【しょくどう】に 昼【ひる】ごはんを 食【た】べます"],correctAnswer:"食堂【しょくどう】で 昼【ひる】ごはんを 食【た】べます",explanation:"Tempat aksi (食堂で) + Objek (昼ごはんを) + Verba (食べます).",diagnosticFeedback:{"昼【ひる】ごはんを 食【た】べます 食堂【しょくどう】で":"Jebakan: Keterangan tempat ditaruh di akhir kalimat.","食【た】べます 食堂【しょくどう】で 昼【ひる】ごはんを":"Jebakan: Predikat kerja di awal kalimat.","食堂【しょくどう】に 昼【ひる】ごはんを 食【た】べます":"Jebakan: Salah memakai partikel に untuk tempat aktivitas aktif."},tokens:["食堂【しょくどう】で","昼【ひる】ごはんを","食【た】べます"],correctOrder:["0","1","2"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Jebakan): Pilihlah kalimat yang bebas dari kesalahan partikel waktu.",sentencePrompt:"Manakah kalimat keterangan waktu yang benar?",options:["明日【あした】８時【はちじ】に 会社【かいしゃ】へ 行【い】きます。","明日【あした】に ８時【はちじ】に 会社【かいしゃ】へ 行【い】きます。","毎日【まいにち】に ８時【はちじ】会社【かいしゃ】へ 行【い】きます。","明日【あした】８時【はちじ】で 会社【かいしゃ】へ 行【い】きます。"],correctAnswer:"明日【あした】８時【はちじ】に 会社【かいしゃ】へ 行【い】きます。",explanation:'"明日" tidak memakai に, sedangkan jam pasti "８時" wajib memakai に.',diagnosticFeedback:{"明日【あした】に ８時【はちじ】に 会社【かいしゃ】へ 行【い】きます。":'Jebakan: Kata relatif "ashita" pantang diberi partikel に.',"毎日【まいにち】に ８時【はちじ】会社【かいしゃ】へ 行【い】きます。":'Jebakan: "mainichi" pantang memakai に.',"明日【あした】８時【はちじ】で 会社【かいしゃ】へ 行【い】きます。":"Jebakan: Waktu jam tidak menggunakan partikel で."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat atasan mengingatkan "午後１時に 会議室で ミーティングがあります", tanggapan paling disiplin adalah:',sentencePrompt:"Pilihlah tanggapan yang mencerminkan etika kerja Jepang:",options:["承知【しょうち】しました。１時【いちじ】前【まえ】に 行【い】きます。","遅【おく】れても いいですか。","はい、さようなら。","会議室【かいぎしつ】は どこですか、知【し】りません。"],correctAnswer:"承知【しょうち】しました。１時【いちじ】前【まえ】に 行【い】きます。",explanation:"Menyatakan pemahaman (Shouchi shimashita) dan komitmen hadir sebelum jam yang ditentukan.",diagnosticFeedback:{"遅【おく】れても いいですか。":"Sangat tidak profesional meminta izin terlambat tanpa alasan darurat.","はい、さようなら。":"Sayounara tidak tepat diucapkan saat menerima instruksi kerja.","会議室【かいぎしつ】は どこですか、知【し】りません。":"Terlalu ketus; jika tidak tahu lokasi, tanyakan dengan sopan."}}],can_do_challenge:{statement:"Bisa membuat janji temu dan melaporkan jadwal kerja harian.",situation:"Mengonfirmasi jam rapat shift kepada atasan.",promptTask:"Laporkan bahwa rapat dimulai jam 1 siang di ruang pertemuan!",modelAnswer:"午後【ごご】１時【いちじ】に 会議室【かいぎしつ】で 会議【かいぎ】が あります。",modelAnswerId:"Pukul 1 siang ada rapat di ruang pertemuan.",culturalEtiquette:"Tiba 10 menit sebelum jam mulai yang disepakati.",skillUnlocked:["Membedakan partikel waktu に dan tempat aksi で","Memahami etika ketepatan waktu kerja Jepang"]},pocket_summary:{keyFormula:"[Jam Pasti] に + [Tempat Aksi] で + [Kata Kerja]",coreWords:["ひるやすみ","しょくどう","かいぎしつ","じかん"],coreWarning:"Jangan pernah beri partikel に pada kata waktu relatif seperti ashita atau kyou.",quickDialogue:"A: 何時に 会いますか。 → B: １時に 会議室で 会いましょう。"}}},t={"les-n5-u05-01":{pedagogical_framework:{what:{summary:"Arah tujuan mobilitas dengan へ (e) / に (ni), titik awal dan akhir から〜まで, serta tujuan aksi [Masu-stem] に行く.",canDo:"Bisa menjelaskan rute berangkat kerja, jam operasional kereta, dan pergi ke suatu tempat untuk tujuan tertentu.",targetPatterns:["[Tempat] へ 行きます / 来ます","[Titik A] から [Titik B] まで","[Verba Stem] に 行きます"],coreVocabSample:["えき","でんしゃ","かいしゃ","りょう","いきます","きます"]},sensei_context:{sceneIntro:"Budi baru pindah ke asrama pekerja di dekat Stasiun Tachikawa. Kenji menjelaskan rute kereta menuju pabrik dan toko kelontong.",dailyMission:"Mampu menyebutkan stasiun asal dan tujuan dengan partikel から dan まで, serta menyatakan tujuan perjalanan dengan 〜に行きます.",whyOrder:"Mobilitas adalah kunci kemandirian hidup di Jepang. Kamu harus paham cara bernavigasi menggunakan kereta dan bus."},cultural_notes:{title:"Etika Penumpang Kereta di Jepang (電車マナー)",etiquette:'Setel ponsel ke "Manner Mode" (senyap) dan jangan menelepon di dalam gerbong kereta.',taboos:'Aksara へ saat berfungsi sebagai partikel arah selalu dilafalkan "e", BUKAN "he".'},pronunciation_tips:{title:"Pelafalan Partikel へ (e)",moraNote:'Partikel へ dilafalkan sama persis dengan vokal "e".',soundTip:'Ucapkan "Tokyo e" seperti "Tokyo-e", jangan berbunyi "Tokyo-he".'},common_pitfalls:[{title:'Melafalkan へ sebagai "He"',caseScenario:"Membaca partikel へ persis tulisan romajinya.",pitfallWarning:'"とうきょう へ (he) いきます。"',rightSolution:'"とうきょう へ (e) いきます。"',explanation:'Sebagai partikel arah, へ wajib dilafalkan "e".'},{title:"Menyusun Tujuan Pergi dengan Verba Utuh",caseScenario:"Menggabungkan bentuk kamus langsung ke に行きます.",pitfallWarning:'"かう に いきます。" (Salah)',rightSolution:'"かい に いきます。" (Benar - Masu-stem)',explanation:"Pola tujuan pergi membutuhkan Masu-stem: 買い(ます) + に 行きます."}],who_and_when:{situational_context:"Membeli tiket di stasiun, bertanya rute bus, atau pamit keluar belanja.",social_relations:"Ragam sopan kepada petugas stasiun atau percakapan ramah dengan rekan asrama.",when_not_to_use:"Jangan memakai kata 行く murni tanpa です/ます kepada atasan."},scenario:{title:"Rute Kereta dari Asrama Menuju Tempat Kerja",setting:"Stasiun Tachikawa, peron jalur Chuo, pukul 07.30",narrative:"Kenji menunjukkan kepada Budi cara naik kereta dari stasiun asrama ke stasiun pabrik."}},dialogue:[{id:"d1",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"ブディ、寮【りょう】から 会社【かいしゃ】まで どうやって 行【い】く？",furigana:"ブディ、寮から 会社まで どうやって 行く？",romaji:"Budi, ryou kara kaisha made dou yatte iku?",idText:"Budi, dari asrama ke kantor/pabrik gimana perginya?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"立川駅【たちかわえき】から 電車【でんしゃ】で 行【い】きます。新宿【しんじゅく】まで ３０分【さんじゅっぷん】です。",furigana:"立川駅から 電車で 行きます。新宿まで ３０分です。",romaji:"Tachikawa-eki kara densha de ikimasu. Shinjuku made sanjuppun desu.",idText:"Dari Stasiun Tachikawa saya pergi naik kereta. Sampai Shinjuku 30 menit."},{id:"d3",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"便利【べんり】だね。今日【きょう】の 仕事【しごと】の あとは どこか 行【い】くの？",furigana:"便利だね。今日の 仕事の あとは どこか 行くの？",romaji:"Benri da ne. Kyou no shigoto no ato wa dokoka iku no?",idText:"Praktis ya. Setelah kerja hari ini mau pergi ke suatu tempat?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、駅前【えきまえ】へ 晩【ばん】ごはんを 食【た】べに 行【い】きます。",furigana:"はい、駅前へ 晩ごはんを 食べに 行きます。",romaji:"Hai, ekimae e bangohan o tabe ni ikimasu.",idText:"Iya, saya mau pergi ke depan stasiun untuk makan malam."},{id:"d5",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"あ、私【わたし】も 駅【えき】の スーパーへ 買【か】い物【もの】に 行【い】きますよ。",furigana:"あ、私も 駅の スーパーへ 買い物に 行きますよ。",romaji:"A, watashi mo eki no su-pa- e kaimono ni ikimasu yo.",idText:"Ah, saya juga mau pergi ke supermarket stasiun untuk belanja lho."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"本当【ほんとう】ですか！じゃあ、一緒【いっしょ】に 駅【えき】へ 行【い】きましょう。",furigana:"本当ですか！じゃあ、一緒に 駅へ 行きましょう。",romaji:"Hontou desu ka! Jaa, issho ni eki e ikimashou.",idText:"Benarkah! Kalau begitu, mari kita pergi ke stasiun bersama-sama."},{id:"d7",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"電車の 時間【じかん】は ８時１５分【はちじじゅうごふん】だよ。急【いそ】ごう！",furigana:"電車の 時間は ８時１５分だよ。急ごう！",romaji:"Densha no jikan wa hachiji juugofun da yo. Isogou!",idText:"Jam keretanya 08.15 lho. Ayo bergegas!"},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！ホームへ 行【い】きましょう！",furigana:"はい！ホームへ 行きましょう！",romaji:"Hai! Ho-mu e ikimashou!",idText:"Baik! Ayo kita ke peron!"}],vocab_breakdown:[{id:"vg-n5-00007",word:"歩く",reading:"あるく",romaji:"aruku",meaning:"berjalan",pos:"verb-u",nuance:"Denotes the physical action of walking on foot. Often contrasted with 走る (はしる, to run).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"駅まで歩いて行きます。",furigana:"駅まで歩いて行きます。",romaji:"",idText:"Saya berjalan ke stasiun."}},{id:"vg-n5-00009",word:"行く",reading:"いく",romaji:"iku",meaning:"pergi",pos:"verb-u",nuance:"Te-form irregular: いって (bukan いいて).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"学校に行きます。",furigana:"学校に行きます。",romaji:"",idText:"Saya pergi ke sekolah."}},{id:"vg-n5-00027",word:"出かける",reading:"でかける",romaji:"dekakeru",meaning:"keluar, pergi keluar",pos:"verb-ru",nuance:"出かける = pergi keluar (dari rumah/kantor). Lebih spesifik dari 行く.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"今から出かけます。",furigana:"今から出かけます。",romaji:"",idText:"Saya akan keluar sekarang."}},{id:"vg-n5-00044",word:"降りる",reading:"おりる",romaji:"oriru",meaning:"turun (dari kendaraan)",pos:"verb-ru",nuance:"Lawan: 乗る (naik). Pakai partikel で atau を.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"次の駅で降ります。",furigana:"次の駅で降ります。",romaji:"",idText:"Saya turun di stasiun berikutnya."}},{id:"vg-n5-00045",word:"乗る",reading:"のる",romaji:"noru",meaning:"naik (kendaraan)",pos:"verb-u",nuance:"Pakai partikel に. 電車に乗る.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"バスに乗って行きます。",furigana:"バスに乗って行きます。",romaji:"",idText:"Saya pergi naik bus."}},{id:"vg-n5-00173",word:"いく",reading:"いく",romaji:"iku",meaning:"pergi",pos:"verb-u",nuance:"Keigo: いらっしゃる (sonkei). Berbeda dari 来る: 行く = menjauh dari pembicara.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"学校に行きます。",furigana:"学校に行きます。",romaji:"",idText:"Saya pergi ke sekolah."}},{id:"vg-n5-00204",word:"とまる",reading:"とまる",romaji:"tomaru",meaning:"berhenti; menginap",pos:"verb-u",nuance:"止まる = berhenti (bus/kereta). 泊まる = menginap. Beda kanji, beda makna.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"次の駅で止まります。",furigana:"次の駅で止まります。",romaji:"",idText:"Berhenti di stasiun berikutnya."}},{id:"vg-n5-00212",word:"のる",reading:"のる",romaji:"noru",meaning:"naik (kendaraan)",pos:"verb-u",nuance:"電車に乗る = naik kereta. Lawan: 降りる (oriru).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"バスに乗って学校に行きます。",furigana:"バスに乗って学校に行きます。",romaji:"",idText:"Saya naik bus pergi ke sekolah."}},{id:"vg-n5-00220",word:"まがる",reading:"まがる",romaji:"magaru",meaning:"berbelok; berbalik",pos:"verb-u",nuance:"Means to turn a corner or for something to bend. Used with を to indicate the corner you are turning (角を曲がる).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"あの角を右に曲がってください。",furigana:"あの角を右に曲がってください。",romaji:"",idText:"Tolong belok kanan di sudut itu."}},{id:"vg-n5-00229",word:"わたる",reading:"わたる",romaji:"wataru",meaning:"menyeberang",pos:"verb-u",nuance:"Means to cross over a physical barrier or space, such as a bridge (橋を渡る) or a street (道を渡る).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"横断歩道を渡ってください。",furigana:"横断歩道を渡ってください。",romaji:"",idText:"Tolong seberang di zebra cross."}}],explanations:[{id:"exp-1",grammarId:"gn5-00008",title:"Pola: に (arah/tujuan)",formula:"N (tempat/orang) + に + V (gerak/memberi)",meaning:"partikel arah atau tujuan",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"に (arah/tujuan)",idText:"partikel arah atau tujuan"}],examples:[{jp:"がっこうにいきます。",romaji:"",idText:"Pergi ke sekolah."},{jp:"ともだちにてがみをかきます。",romaji:"",idText:"Menulis surat kepada teman."}]},{id:"exp-2",grammarId:"gn5-00013",title:"Pola: へ (arah)",formula:"N (tempat) + へ + V (gerak)",meaning:"partikel arah pergerakan",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"へ (arah)",idText:"partikel arah pergerakan"}],examples:[{jp:"にほんへいきたいです。",romaji:"",idText:"Ingin pergi ke Jepang."},{jp:"うちへかえります。",romaji:"",idText:"Pulang ke rumah."}]},{id:"exp-3",grammarId:"gn5-00020",title:"Pola: から / まで",formula:"N (awal) + から + N (akhir) + まで",meaning:"dari ... sampai ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"から / まで",idText:"dari ... sampai ..."}],examples:[{jp:"くじからごご六じまではたらきます。",romaji:"",idText:"Bekerja dari jam 9 sampai jam 6 sore."},{jp:"とうきょうからおおさかまでしんかんせんでいきます。",romaji:"",idText:"Pergi dari Tokyo ke Osaka naik shinkansen."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah arti kata "電車 (でんしゃ)".',sentencePrompt:'Kata "電車" berarti:',options:["Kereta listrik","Sepeda motor","Kapal laut","Pesawat terbang"],correctAnswer:"Kereta listrik",explanation:'"電車 (でんしゃ)" adalah kereta listrik yang menjadi transportasi utama di Jepang.',diagnosticFeedback:{"Sepeda motor":"Salah: Sepeda motor adalah オートバイ atau バイク.","Kapal laut":"Salah: Kapal laut adalah 船 (fune).","Pesawat terbang":"Salah: Pesawat terbang adalah 飛行機 (hikouki)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Isian Partikel Arah): Pilihlah partikel arah tujuan perjalanan.",sentencePrompt:"私【わたし】は 会社【かいしゃ】 _____ 行【い】きます。",options:["へ","で","を","から"],correctAnswer:"へ",explanation:'Partikel へ (dilafalkan "e") menandai arah tujuan perjalanan (pergi ke kantor).',diagnosticFeedback:{で:"Salah: Partikel で menandai alat transportasi, bukan arah tujuan.",を:"Salah: Partikel を menandai objek kata kerja transitif.",から:"Salah: Partikel から menandai titik awal asal keberangkatan."}},{id:"drill-3",type:"reorder",instruction:'Langkah 3 (Susun Kalimat): Urutkan frasa tujuan aksi "pergi untuk makan" berikut.',sentencePrompt:"Susunan kalimat yang tepat:",options:["駅前【えきまえ】へ 昼【ひる】ごはんを 食【た】べに 行【い】きます","昼【ひる】ごはんを 食【た】べに 駅前【えきまえ】へ 行【い】きます","行【い】きます 駅前【えきまえ】へ 食【た】べに 昼【ひる】ごはんを","駅前【えきまえ】へ 食【た】べるに 行【い】きます 昼【ひる】ごはんを"],correctAnswer:"駅前【えきまえ】へ 昼【ひる】ごはんを 食【た】べに 行【い】きます",explanation:"Tempat tujuan (駅前へ) + Objek (昼ごはんを) + Masu-stem + に 行きます (食べに行きます).",diagnosticFeedback:{"昼【ひる】ごはんを 食【た】べに 駅前【えきまえ】へ 行【い】きます":"Kurang lazim: Keterangan arah tempat biasanya mendahului objek.","行【い】きます 駅前【えきまえ】へ 食【た】べに 昼【ひる】ごはんを":"Jebakan: Kata kerja ditaruh di awal kalimat.","駅前【えきまえ】へ 食【た】べるに 行【い】きます 昼【ひる】ごはんを":"Jebakan: Bentuk kamus salah dipakai untuk pola ni ikimasu."},tokens:["駅前【えきまえ】へ","昼【ひる】ごはんを","食【た】べに","行【い】きます"],correctOrder:["0","1","2","3"]},{id:"drill-4",type:"trap_detect",instruction:'Langkah 4 (Deteksi Jebakan): Manakah pasangan partikel "dari ... sampai ..." yang benar?',sentencePrompt:"Pilihlah kalimat rute yang tepat:",options:["寮【りょう】から 会社【かいしゃ】まで 電車【でんしゃ】で 行【い】きます。","寮【りょう】まで 会社【かいしゃ】から 電車【でんしゃ】で 行【い】きます。","寮【りょう】へ 会社【かいしゃ】に 電車【でんしゃ】で 行【い】きます。","寮【りょう】で 会社【かいしゃ】を 電車【でんしゃ】で 行【い】きます。"],correctAnswer:"寮【りょう】から 会社【かいしゃ】まで 電車【でんしゃ】で 行【い】きます。",explanation:"Asal memakai から (dari), dan tujuan akhir memakai まで (sampai).",diagnosticFeedback:{"寮【りょう】まで 会社【かいしゃ】から 電車【でんしゃ】で 行【い】きます。":"Jebakan terbalik: Artinya menjadi dari kantor sampai asrama.","寮【りょう】へ 会社【かいしゃ】に 電車【でんしゃ】で 行【い】きます。":"Jebakan: Menggunakan dua partikel arah tanpa penanda titik asal.","寮【りょう】で 会社【かいしゃ】を 電車【でんしゃ】で 行【い】きます。":"Jebakan: Salah menggunakan partikel tempat dan objek."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat teman mengajak "一緒【いっしょ】に 駅【えき】へ 行【い】きませんか", jawaban setuju yang ramah adalah:',sentencePrompt:"Pilihlah jawaban menyetujui ajakan:",options:["いいですね！一緒【いっしょ】に 行【い】きましょう。","いいえ、行【い】きます。","駅【えき】は ありません。","さようなら、明日【あした】です。"],correctAnswer:"いいですね！一緒【いっしょ】に 行【い】きましょう。",explanation:'"いいですね！〜ましょう" adalah formula standar menyetujui ajakan secara ramah.',diagnosticFeedback:{"いいえ、行【い】きます。":'Kontradiktif: Mengatakan "tidak" tetapi predikatnya "pergi".',"駅【えき】は ありません。":'Tidak masuk akal: "stasiun tidak ada".',"さようなら、明日【あした】です。":"Tidak nyambung dengan respon ajakan saat ini."}}],can_do_challenge:{statement:"Bisa menjelaskan rute berangkat kerja dan sarana transportasi yang dipakai.",situation:"Menjelaskan perjalanan harian dari asrama ke tempat magang.",promptTask:"Katakan bahwa kamu pergi dari asrama sampai kantor naik kereta selama 30 menit!",modelAnswer:"寮【りょう】から 会社【かいしゃ】まで 電車【でんしゃ】で 行【い】きます。３０分【さんじゅっぷん】かかります。",modelAnswerId:"Dari asrama sampai kantor saya pergi naik kereta. Membutuhkan waktu 30 menit.",culturalEtiquette:"Sebutkan titik awal dengan から dan tujuan dengan まで secara runtut.",skillUnlocked:["Menguasai penanda rute から〜まで","Menguasai pola tujuan aksi 〜に行きます"]},pocket_summary:{keyFormula:"[Titik Asal] から [Titik Tujuan] まで [Alat] で 行きます",coreWords:["でんしゃ","えき","いきます","きます"],coreWarning:'Partikel へ dilafalkan "e", bukan "he". Pola tujuan verba harus memakai Masu-stem.',quickDialogue:"A: どこへ 行きますか。 → B: スーパーへ 買い物に 行きます。"}},"les-n5-u05-02":{pedagogical_framework:{what:{summary:"Penyerta teman beraktivitas dengan partikel と (bersama/dengan), sarana transportasi dengan で, dan berjalan kaki 歩いて (aruite - tanpa で).",canDo:"Bisa mengajak rekan bepergian, menyebutkan teman perjalanan, dan memilih sarana mobilitas.",targetPatterns:["[Orang] と (bersama)","[Sarana Transportasi] で","歩いて (aruite - jalan kaki)"],coreVocabSample:["ともだち","じてんしゃ","バス","あるいて","ひとりで","とうきょう"]},sensei_context:{sceneIntro:"Akhir pekan tiba! Budi dan Sakura merencanakan jalan-jalan ke pusat kota Tokyo atau pasar swalayan terdekat.",dailyMission:"Gunakan partikel と saat pergi bersama orang lain, atau kata ひとりで jika pergi sendirian.",whyOrder:"Setelah bisa menentukan rute sendiri, sekarang kita belajar berinteraksi sosial mengajak teman beraktivitas."},cultural_notes:{title:"Aturan Bersepeda di Jepang (自転車ルール)",etiquette:"Di Jepang, sepeda harus didaftarkan anti-maling (Bouhan Touroku). Bersepeda sambil memegang payung atau memakai earphone dilarang keras!",taboos:'Jangan tambahkan partikel で pada kata 歩いて (aruite). "Aruite de ikimasu" adalah kesalahan fatal!'},pronunciation_tips:{title:"Pembeda Bunyi Aruite vs De",moraNote:'Kata "aruite" terdiri dari 4 mora rata (a-ru-i-te).',soundTip:'Katakan "densha de" (pakai de) vs "aruite" (tanpa de).'},common_pitfalls:[{title:"Menambahkan Partikel で pada Jalan Kaki",caseScenario:'Refleks mentransfer "dengan jalan kaki" menjadi aruite de.',pitfallWarning:'"あるいて で いきます。" (Salah Fatal)',rightSolution:'"あるいて いきます。" (Benar)',explanation:"Kata 歩いて (aruite) sudah berkedudukan sebagai adverbia bentuk-te, tidak boleh diberi partikel で."},{title:"Salah Menempatkan Partikel Penyerta と",caseScenario:"Menaruh partikel と di belakang kata kerja seperti bahasa Indonesia.",pitfallWarning:'"いきます ともだち と。" (Salah)',rightSolution:'"ともだち と いきます。" (Benar)',explanation:"Partikel と melekat langsung di belakang orang yang menyertai."}],who_and_when:{situational_context:"Mengobrol rencana liburan akhir pekan di asrama, membeli kebutuhan harian.",social_relations:"Ragam akrab sopan kepada teman magang dan tetangga asrama.",when_not_to_use:'Jangan gunakan ひとりで dengan partikel と ("hitori to" tidak ada dalam bahasa Jepang).'},scenario:{title:"Rencana Jalan-Jalan Akhir Pekan ke Shinjuku",setting:"Dapur bersama asrama pekerja, Sabtu pagi pukul 09.00",narrative:"Budi mengajak Kenji dan Sakura untuk pergi bersama ke toko elektronik di Shinjuku."}},dialogue:[{id:"d1",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ケンジさん、今日【きょう】は どこかへ 出【で】かけますか。",furigana:"ケンジさん、今日は どこかへ 出かけますか。",romaji:"Kenji-san, kyou wa dokoka e dekakemasu ka.",idText:"Kenji-san, hari ini ada rencana pergi keluar ke suatu tempat?"},{id:"d2",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"午後【ごご】から 新宿【しんじゅく】へ 行【い】くよ。ブディは？",furigana:"午後から 新宿へ 行くよ。ブディは？",romaji:"Gogo kara Shinjuku e iku yo. Budi wa?",idText:"Mulai siang mau pergi ke Shinjuku. Kalau Budi?"},{id:"d3",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"私【わたし】も 友達【ともだち】と 新宿【しんじゅく】へ 行【い】きます。何【なん】で 行【い】きますか。",furigana:"私も 友達と 新宿へ 行きます。何で 行きますか。",romaji:"Watashi mo tomodachi to Shinjuku e ikimasu. Nan de ikimasu ka.",idText:"Saya juga mau pergi ke Shinjuku bersama teman. Pergi naik apa?"},{id:"d4",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"天気【てんき】が いいから、駅【えき】まで 自転車【じてんしゃ】で 行【い】くよ。",furigana:"天気が いいから、駅まで 自転車で 行くよ。",romaji:"Tenki ga ii kara, eki made jitensha de iku yo.",idText:"Karena cuacanya bagus, sampai stasiun aku naik sepeda."},{id:"d5",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"私【わたし】は 散歩【さんぽ】が好【す】きだから、駅【えき】まで 歩【ある】いて 行【い】きます。",furigana:"私は 散歩が好きだから、駅まで 歩いて 行きます。",romaji:"Watashi wa sanpo ga suki da kara, eki made aruite ikimasu.",idText:"Karena saya suka jalan-jalan santai, sampai stasiun saya pergi jalan kaki."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"歩【ある】いて 何分【なんぷん】くらいですか。",furigana:"歩いて 何分くらいですか。",romaji:"Aruite nanpun kurai desu ka.",idText:"Jalan kaki kira-kira berapa menit ya?"},{id:"d7",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"１５分【じゅうごふん】くらいですよ。みんなで 一緒【いっしょ】に 行【い】きましょうか。",furigana:"１５分くらいですよ。みんなで 一緒に 行きましょうか。",romaji:"Juugofun kurai desu yo. Minna de issho ni ikimashou ka.",idText:"Kira-kira 15 menit kok. Bagaimana kalau kita semua pergi bareng?"},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！ぜひ 一緒【いっしょ】に 行【い】きましょう！楽【たの】しみです。",furigana:"はい！ぜひ 一緒に 行きましょう！楽しみです。",romaji:"Hai! Zehi issho ni ikimashou! Tanoshimi desu.",idText:"Wah, mau sekali! Ayo kita pergi bersama! Pasti menyenangkan."}],vocab_breakdown:[{id:"vg-n5-00506",word:"南",reading:"みなみ",romaji:"minami",meaning:"selatan",pos:"noun",nuance:"The southern cardinal direction. In Japan, southern-facing rooms (南向き) are highly valued for getting good sunlight.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"南の島へ旅行に行きました。",furigana:"南の島へ旅行に行きました。",romaji:"",idText:"Saya pergi berlibur ke pulau di sebelah selatan."}},{id:"vg-n5-00507",word:"南口",reading:"みなみぐち",romaji:"minamiguchi",meaning:"pintu selatan",pos:"noun",nuance:"The southern exit of a station or building.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"南口のバス乗り場からバスに乗ります。",furigana:"南口のバス乗り場からバスに乗ります。",romaji:"",idText:"Saya naik bus dari halte bus di pintu selatan."}},{id:"vg-n5-00508",word:"北海道",reading:"ほっかいどう",romaji:"hottkaidou",meaning:"Hokkaido (pulau utara Jepang)",pos:"noun",nuance:"The northernmost main island of Japan, famous for snow, dairy, and vast nature. Notice it uses the suffix '-dou' (circuit/region) rather than '-ken' (prefecture).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"冬の北海道は雪がたくさん降って寒いです。",furigana:"冬の北海道は雪がたくさん降って寒いです。",romaji:"",idText:"Di Hokkaido musim dingin salju turun banyak dan dingin."}},{id:"vg-n5-00509",word:"北",reading:"きた",romaji:"kita",meaning:"utara",pos:"noun",nuance:"The northern cardinal direction. Often associated with colder regions.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"この部屋の窓は北を向いています。",furigana:"この部屋の窓は北を向いています。",romaji:"",idText:"Jendela kamar ini menghadap ke arah utara."}},{id:"vg-n5-00510",word:"北口",reading:"きたぐち",romaji:"kitaguchi",meaning:"pintu utara",pos:"noun",nuance:"The northern exit of a train station.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"駅の北口にはタクシーがたくさん待っています。",furigana:"駅の北口にはタクシーがたくさん待っています。",romaji:"",idText:"Di pintu utara stasiun banyak taksi menunggu."}},{id:"vg-n5-00512",word:"上",reading:"うえ",romaji:"ue",meaning:"atas",pos:"noun",nuance:"上 (うえ) = atas/di atas. Juga: 上 (じょう) dalam komposisi: 上手 = pandai.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"机の上に本があります。",furigana:"机の上に本があります。",romaji:"",idText:"Di atas meja ada buku."}},{id:"vg-n5-00513",word:"上着",reading:"うわぎ",romaji:"uwagi",meaning:"jaket, mantel",pos:"noun",nuance:"A general term for outerwear worn over a shirt or blouse. Literally 'upper clothes,' it covers items from suit jackets to winter coats.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"寒いので暖かい上着を着ました。",furigana:"寒いので暖かい上着を着ました。",romaji:"",idText:"Karena dingin, saya memakai jaket hangat."}},{id:"vg-n5-00514",word:"地下鉄",reading:"ちかてつ",romaji:"chikatetsu",meaning:"kereta bawah tanah, MRT",pos:"noun",nuance:"そば/傍 = di samping/dekat. Lebih spesifik dari 近く (chikaku = dekat area).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"銀行のそばにコンビニがあります。",furigana:"銀行のそばにコンビニがあります。",romaji:"",idText:"Di samping bank ada konbini."}},{id:"vg-n5-00515",word:"下",reading:"した",romaji:"shita",meaning:"bawah",pos:"noun",nuance:"下 (した) = bawah/di bawah. Lawan: 上 (うえ). Juga: 下 (か/げ) dalam komposisi.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"いすの下に猫がいます。",furigana:"いすの下に猫がいます。",romaji:"",idText:"Di bawah kursi ada kucing."}},{id:"vg-n5-00517",word:"外",reading:"そと",romaji:"soto",meaning:"luar",pos:"noun",nuance:"Refers to the physical outdoors or external space. Also conceptually used to mean 'outside one's in-group' (soto).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"外は雨が降っていますから、傘を持って行きます。",furigana:"外は雨が降っていますから、傘を持って行きます。",romaji:"",idText:"Di luar sedang hujan, jadi saya membawa payung."}}],explanations:[{id:"exp-1",grammarId:"gn5-00012",title:"Pola: で (cara/alat)",formula:"N (alat/cara) + で + V",meaning:"partikel cara atau alat",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"で (cara/alat)",idText:"partikel cara atau alat"}],examples:[{jp:"はしでたべます。",romaji:"",idText:"Makan dengan sumpit."},{jp:"でんしゃでかいしゃへいきます。",romaji:"",idText:"Pergi ke kantor naik kereta."},{jp:"にほんごではなします。",romaji:"",idText:"Berbicara dalam bahasa Jepang."}]},{id:"exp-2",grammarId:"gn5-00085",title:"Pola: から (asal/arah datang)",formula:"【場所/人】から + V kedatangan (来ます、帰ります、dll.)",meaning:"dari [tempat/orang] — menunjukkan asal atau titik keberangkatan",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"から (asal/arah datang)",idText:"dari [tempat/orang] — menunjukkan asal atau titik keberangkatan"}],examples:[{jp:"ブラジルから来ました。",romaji:"",idText:"Saya berasal dari Brasil."},{jp:"インドネシアから来ました。",romaji:"",idText:"Saya dari Indonesia."},{jp:"大阪から来ました。",romaji:"",idText:"Saya datang dari Osaka."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah arti kata "自転車 (じてんしゃ)".',sentencePrompt:'Kata "自転車" memiliki arti:',options:["Sepeda pancal","Kereta bawah tanah","Mobil sewaan","Taksi bandara"],correctAnswer:"Sepeda pancal",explanation:'"自転車 (じてんしゃ)" adalah sepeda.',diagnosticFeedback:{"Kereta bawah tanah":"Salah: Kereta bawah tanah adalah 地下鉄 (chikatetsu).","Mobil sewaan":"Salah: Mobil sewaan adalah レンタカー.","Taksi bandara":"Salah: Taksi adalah タクシー."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Isian Partikel Penyerta): Pilihlah partikel yang menyatakan "bersama teman".',sentencePrompt:"私【わたし】は 友達【ともだち】 _____ 新宿【しんじゅく】へ 行【い】きます。",options:["と","で","に","を"],correctAnswer:"と",explanation:"Partikel と menandai orang penyerta aksi (bersama teman).",diagnosticFeedback:{で:"Salah: Partikel で menandai alat transportasi, bukan teman orang.",に:"Salah: Partikel に menandai tujuan perjalanan.",を:"Salah: Partikel を menandai objek kata kerja transitif."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Urutkan kalimat yang menyatakan pergi jalan kaki berikut.",sentencePrompt:"Susunan kalimat yang tepat:",options:["駅【えき】まで 歩【ある】いて 行【い】きます","歩【ある】いてで 駅【えき】まで 行【い】きます","行【い】きます 駅【えき】まで 歩【ある】いて","駅【えき】まで 歩【ある】いてに 行【い】きます"],correctAnswer:"駅【えき】まで 歩【ある】いて 行【い】きます",explanation:'"歩いて" tidak boleh diberi partikel で atau に: 駅まで 歩いて 行きます.',diagnosticFeedback:{"歩【ある】いてで 駅【えき】まで 行【い】きます":'Jebakan Fatal: "Aruite" pantang ditambah partikel で!',"行【い】きます 駅【えき】まで 歩【ある】いて":"Jebakan: Predikat kerja ditaruh di depan kalimat.","駅【えき】まで 歩【ある】いてに 行【い】きます":'Jebakan: "Aruite" tidak memerlukan partikel に.'},tokens:["駅【えき】まで","歩【ある】いて","行【い】きます"],correctOrder:["0","1","2"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Jebakan): Pilihlah kalimat yang benar saat pergi seorang diri.",sentencePrompt:'Manakah ungkapan yang benar untuk "pergi sendirian"?',options:["一人【ひとり】で 東京【とうきょう】へ 行【い】きます。","一人【ひとり】と 東京【とうきょう】へ 行【い】きます。","一人【ひとり】に 東京【とうきょう】へ 行【い】きます。","一人【ひとり】を 東京【とうきょう】へ 行【い】きます。"],correctAnswer:"一人【ひとり】で 東京【とうきょう】へ 行【い】きます。",explanation:'Kondisi melakukan sesuatu sendirian dinyatakan dengan "一人で (hitori de)".',diagnosticFeedback:{"一人【ひとり】と 東京【とうきょう】へ 行【い】きます。":'Jebakan: "Hitori to" tidak ada dalam tata bahasa Jepang.',"一人【ひとり】に 東京【とうきょう】へ 行【い】きます。":"Jebakan: Partikel に salah untuk penanda keadaan tunggal.","一人【ひとり】を 東京【とうきょう】へ 行【い】きます。":"Jebakan: Objek を keliru diterapkan."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat ditanya "何【なん】で 駅【えき】まで 行【い】きますか", jawaban yang tepat adalah:',sentencePrompt:"Pilihlah jawaban sarana transportasi:",options:["自転車【じてんしゃ】で 行【い】きます。","友達【ともだち】で 行【い】きます。","はい、行【い】きません。","東京【とうきょう】です。"],correctAnswer:"自転車【じてんしゃ】で 行【い】きます。",explanation:'Pertanyaan "何で (nande)" menanyakan sarana transportasi, dijawab dengan "[Alat] で 行きます".',diagnosticFeedback:{"友達【ともだち】で 行【い】きます。":"Jebakan: Teman orang harus memakai partikel と, bukan で.","はい、行【い】きません。":"Kontradiktif dan tidak menjawab sarana transportasi.","東京【とうきょう】です。":"Hanya menyebutkan kota tujuan, bukan sarananya."}}],can_do_challenge:{statement:"Bisa mengajak rekan bepergian dan menceritakan sarana transportasi bersama teman.",situation:"Merencanakan liburan akhir pekan bersama rekan asrama.",promptTask:"Katakan bahwa kamu pergi ke Tokyo bersama teman naik kereta!",modelAnswer:"私【わたし】は 友達【ともだち】と 電車【でんしゃ】で 東京【とうきょう】へ 行【い】きます。",modelAnswerId:"Saya pergi ke Tokyo naik kereta bersama teman.",culturalEtiquette:"Urutkan teman (と) lalu sarana transportasi (で) sebelum arah tujuan (へ).",skillUnlocked:["Menguasai partikel penyerta と","Membedakan sarana で dan pengecualian 歩いて"]},pocket_summary:{keyFormula:"[Orang] と + [Sarana] で + [Tempat] へ 行きます",coreWords:["ともだち","じてんしゃ","あるいて","ひとりで"],coreWarning:'"歩いて" tidak boleh memakai で. Sendirian diungkapkan dengan "一人で (hitori de)".',quickDialogue:"A: だれと 行きますか。 → B: 友達と 自転車で 行きます。"}}},r={"les-n5-u06-01":{pedagogical_framework:{what:{summary:"Menyebutkan jumlah pesanan dengan kaunter asli Jepang (ひとつ, ふたつ) dan kaunter orang (ひとり, ふたり), ajakan santun 〜ましょう, dan tawaran bantuan 〜ましょうか.",canDo:"Bisa memesan menu makanan di restoran atau kedai Jepang dan mengajak rekan makan bersama.",targetPatterns:["[Kaunter: ひとつ/ふたつ] ください","〜ましょう (ayo)","〜ましょうか (bagaimana kalau / mau kubantu?)"],coreVocabSample:["メニュー","ひとつ","ふたつ","みっつ","ラーメン","たべましょう"]},sensei_context:{sceneIntro:"Jam istirahat siang, Budi dan Tanaka-senpai pergi ke kedai ramen di seberang kantor. Budi memesan makanan sendiri untuk pertama kali.",dailyMission:"Mampu menyebutkan jumlah mangkuk ramen dengan hitungan Jepang dan mengajak rekan dengan 〜ましょう.",whyOrder:"Makan adalah kebutuhan pokok! Menguasai pemesanan makanan membuat hidup di Jepang jauh lebih nikmat dan mandiri."},cultural_notes:{title:"Budaya Memesan & Menghirup Ramen di Jepang",etiquette:"Menghirup mie ramen hingga berbunyi sruput (Zuzutto) adalah tanda menikmati makanan dan tidak dianggap tidak sopan di kedai ramen.",taboos:"Jangan menancapkan sumpit tegak lurus di atas mangkuk nasi (Tsukitate-bashi), karena menyerupai dupa upacara kematian Buddha."},pronunciation_tips:{title:"Irama Hitungan Kaunter Asli Jepang",moraNote:"Hitungan asli Jepang: hitotsu (1), futatsu (2), mittsu (3 - ada konsonan rangkap tt), yottsu (4 - yt).",soundTip:"Beri jeda ketukan pada konsonan rangkap mittsu (mi-t-tsu)."},common_pitfalls:[{title:"Memakai Angka Biasa (Ichi, Ni) untuk Pesanan Makanan",caseScenario:'Mengatakan "ichi kudasai" atau "ni kudasai" saat memesan.',pitfallWarning:'"ラーメン いち ください。" (Salah)',rightSolution:'"ラーメン ひとつ ください。" (Benar)',explanation:"Memesan porsi makanan umum wajib menggunakan kaunter hitotsu, futatsu, mittsu."},{title:"Salah Posisi Peletakan Kaunter Jumlah",caseScenario:'Meletakkan partikel を setelah kata hitotsu: "Ramen hitotsu o kudasai".',pitfallWarning:'"ラーメン ひとつ を ください。"',rightSolution:'"ラーメン を ひとつ ください。" atau "ラーメン ひとつ ください。"',explanation:"Kaunter diletakkan tepat sebelum kata kerja atau tanpa partikel tambahan."}],who_and_when:{situational_context:"Memesan makanan di kedai ramen, restoran keluarga, atau izakaya.",social_relations:"Berbicara sopan kepada pelayan kedai dan akrab dengan rekan makan.",when_not_to_use:'Jangan memakai kata perintah kasual "kure" kepada pelayan restoran.'},scenario:{title:"Makan Siang di Kedai Ramen Ichiban",setting:"Kedai ramen dekat kantor, meja konter, pukul 12.15",narrative:"Tanaka mengajak Budi makan ramen. Pelayan datang mencatat pesanan mereka."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"ブディさん、お腹【なか】が 空【す】きましたね。ラーメンを 食【た】べましょう！",furigana:"ブディさん、お腹が 空きましたね。ラーメンを 食べましょう！",romaji:"Budi-san, onaka ga sukimashita ne. Ra-men o tabemashou!",idText:"Budi-san, perut sudah lapar ya. Ayo kita makan ramen!"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！ぜひ 食【た】べましょう。この 店【みせ】は 初【はじ】めてです。",furigana:"はい！ぜひ 食べましょう。この 店は 初めてです。",romaji:"Hai! Zehi tabemashou. Kono mise wa hajimete desu.",idText:"Wah, ayo! Ini pertama kalinya saya ke kedai ini."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"すみません！注文【ちゅうもん】を お願【ねが】いします。",furigana:"すみません！注文を お願いします。",romaji:"Sumimasen! Chuumon o onegaishimasu.",idText:"Permisi! Mau pesan ya."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"私【わたし】は 醤油【しょうゆ】ラーメンを 一【ひと】つ ください。",furigana:"私は 醤油ラーメンを 一つ ください。",romaji:"Watashi wa shouyu ra-men o hitotsu kudasai.",idText:"Saya tolong shoyu ramen-nya satu mangkuk."},{id:"d5",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"私【わたし】は 味噌【みそ】ラーメンを 一【ひと】つ、ギョーザを 二【ふた】つ ください。",furigana:"私は 味噌ラーメンを 一つ、ギョーザを 二つ ください。",romaji:"Watashi wa miso ra-men o hitotsu, gyo-za o futatsu kudasai.",idText:"Saya tolong miso ramen satu, dan gyoza dua porsi ya."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"田中【たなか】さん、お水【みず】を 持【も】って 来【き】ましょうか。",furigana:"田中さん、お水を 持って 来ましょうか。",romaji:"Tanaka-san, omizu o motte kimashou ka.",idText:"Tanaka-san, bagaimana kalau saya ambilkan air minumnya?"},{id:"d7",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"ありがとう、助【たす】かります。あそこの 給水機【きゅうすいき】に ありますよ。",furigana:"ありがとう、助かります。あそこの 給水機に ありますよ。",romaji:"Arigatou, tasukarimasu. Asoko no kyuusuiki ni arimasu yo.",idText:"Terima kasih, sangat membantu. Ada di mesin dispenser air sebelah sana ya."},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、すぐ 持【も】って 来【き】ます！",furigana:"はい、すぐ 持って 来ます！",romaji:"Hai, sugu motte kimasu!",idText:"Baik, segera saya ambilkan!"}],vocab_breakdown:[{id:"vg-n5-00014",word:"切る",reading:"きる",romaji:"kiru",meaning:"memotong",pos:"verb-u",nuance:"Godan meski berakhiran る.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"野菜を切ります。",furigana:"野菜を切ります。",romaji:"",idText:"Saya memotong sayuran."}},{id:"vg-n5-00023",word:"食べる",reading:"たべる",romaji:"taberu",meaning:"makan",pos:"verb-ru",nuance:"Keigo: 召し上がる (sonkei), いただく (kenjo).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"朝ご飯を食べました。",furigana:"朝ご飯を食べました。",romaji:"",idText:"Saya makan sarapan."}},{id:"vg-n5-00024",word:"飲む",reading:"のむ",romaji:"nomu",meaning:"minum",pos:"verb-u",nuance:"Keigo: 召し上がる (sonkei), いただく (kenjo).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"水を飲んでください。",furigana:"水を飲んでください。",romaji:"",idText:"Tolong minum air."}},{id:"vg-n5-00026",word:"作る",reading:"つくる",romaji:"tsukuru",meaning:"membuat",pos:"verb-u",nuance:"できる = bisa/mampu. 日本語ができる = bisa bahasa Jepang. Juga: selesai dibuat/terjadi.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"ケーキを作りました。",furigana:"ケーキを作りました。",romaji:"",idText:"Saya membuat kue."}},{id:"vg-n5-00037",word:"買う",reading:"かう",romaji:"kau",meaning:"membeli",pos:"verb-u",nuance:"Nai-form: 買わない (う→わ).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"スーパーで野菜を買いました。",furigana:"スーパーで野菜を買いました。",romaji:"",idText:"Saya membeli sayuran di supermarket."}},{id:"vg-n5-00038",word:"売る",reading:"うる",romaji:"uru",meaning:"menjual",pos:"verb-u",nuance:"売る = menjual. Lawan: 買う. 売り場 = counter/bagian di toko.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"この店は本を売っています。",furigana:"この店は本を売っています。",romaji:"",idText:"Toko ini menjual buku."}},{id:"vg-n5-00198",word:"たべる",reading:"たべる",romaji:"taberu",meaning:"makan",pos:"verb-ru",nuance:"Keigo: 召し上がる (sonkei), いただく (kenjo).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"何を食べますか。",furigana:"何を食べますか。",romaji:"",idText:"Mau makan apa?"}},{id:"vg-n5-00211",word:"のむ",reading:"のむ",romaji:"nomu",meaning:"minum",pos:"verb-u",nuance:"Primarily means to drink liquids, but uniquely in Japanese, it is also used for swallowing pills or taking medicine (薬を飲む).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"水をたくさん飲んでください。",furigana:"水をたくさん飲んでください。",romaji:"",idText:"Tolong banyak minum air."}},{id:"vg-n5-00232",word:"あう",reading:"あう",romaji:"au",meaning:"cocok; sesuai",pos:"verb-u",nuance:"合う = cocok/pas (baju, rasa). Berbeda: 会う = bertemu orang.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"この服, サイズが合いますか。",furigana:"この服, サイズが合いますか。",romaji:"",idText:"Apakah ukuran baju ini cocok?"}},{id:"vg-n5-00233",word:"うる",reading:"うる",romaji:"uru",meaning:"menjual",pos:"verb-u",nuance:"Means to sell something, exchanging goods for money. Often used in the continuous form (売っている) to describe what a store carries.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"ここでは新鮮な野菜を売っています。",furigana:"ここでは新鮮な野菜を売っています。",romaji:"",idText:"Di sini menjual sayuran segar."}}],explanations:[{id:"exp-1",grammarId:"gn5-00088",title:"Pola: N、[数]お願いします / ください",formula:"N + jumlah (hitotsu/futatsu/...) + お願いします atau ください",meaning:"tolong [N] sebanyak [jumlah] (memesan atau meminta barang)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"N、[数]お願いします / ください",idText:"tolong [N] sebanyak [jumlah] (memesan atau meminta barang)"}],examples:[{jp:"コーヒー、ひとつお願いします。",romaji:"",idText:"Satu kopi, tolong."},{jp:"生ビール3つと、ウーロン茶1つ、お願いします。",romaji:"",idText:"Tiga bir draft dan satu oolong tea, tolong."},{jp:"これ、ふたつください。",romaji:"",idText:"Ini, dua, tolong."}]},{id:"exp-2",grammarId:"gn5-00073",title:"Pola: 〜でいい",formula:"N / Adj-na + でいい",meaning:"... saja sudah cukup / tidak masalah dengan ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜でいい",idText:"... saja sudah cukup / tidak masalah dengan ..."}],examples:[{jp:"みずでいいです。",romaji:"",idText:"Air saja sudah cukup."},{jp:"これでいいですか？",romaji:"",idText:"Ini sudah cukup ya?"}]},{id:"exp-3",grammarId:"gn5-00086",title:"Pola: N は ちょっと…",formula:"N + は + ちょっと + … (kalimat digantung)",meaning:"[N] agak... (penolakan tidak langsung / ekspresi keengganan)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"N は ちょっと…",idText:"[N] agak... (penolakan tidak langsung / ekspresi keengganan)"}],examples:[{jp:"わさびは、ちょっと…。",romaji:"",idText:"Wasabi... agak susah (tidak suka)."},{jp:"月曜日は、ちょっと…。",romaji:"",idText:"Senin itu... agak susah."},{jp:"それはちょっと…。",romaji:"",idText:"Itu... agak..."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kaunter): Pilihlah kaunter yang menyatakan jumlah "dua buah / porsi".',sentencePrompt:"Kaunter asli Jepang untuk menyebutkan 2 buah adalah:",options:["ふたつ (futatsu)","ひとつ (hitotsu)","みっつ (mittsu)","よっつ (yottsu)"],correctAnswer:"ふたつ (futatsu)",explanation:"ふたつ (futatsu) berarti 2 buah. ひとつ = 1, みっつ = 3, よっつ = 4.",diagnosticFeedback:{"ひとつ (hitotsu)":"Salah: ひとつ adalah 1 buah.","みっつ (mittsu)":"Salah: みっつ adalah 3 buah.","よっつ (yottsu)":"Salah: よっつ adalah 4 buah."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Isian Bentuk Ajakan): Pilihlah akhiran ajakan "ayo makan bersama".',sentencePrompt:"お昼【ひる】ごはんを 一緒【いっしょ】に 食【た】べ _____。",options:["ましょう","ます","ました","ません"],correctAnswer:"ましょう",explanation:"Bentuk 〜ましょう menyatakan ajakan antusias: 食べましょう (ayo makan).",diagnosticFeedback:{ます:"Salah: Bentuk ます hanya menyatakan pernyataan biasa.",ました:"Salah: Bentuk ました menyatakan waktu lampau.",ません:"Salah: Bentuk ません menyatakan sangkalan negatif."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Urutkan kalimat pemesanan ramen berikut secara benar.",sentencePrompt:"Susunan pesanan yang tepat:",options:["ラーメンを 一【ひと】つ ください","一【ひと】つを ラーメン ください","ください ラーメンを 一【ひと】つ","ラーメン 一【ひと】つを ください"],correctAnswer:"ラーメンを 一【ひと】つ ください",explanation:"Menu pesanan (ラーメンを) + Jumlah kaunter (一つ) + ください.",diagnosticFeedback:{"一【ひと】つを ラーメン ください":"Jebakan: Susunan kaunter dan nama barang terbalik.","ください ラーメンを 一【ひと】つ":"Jebakan: Kata kudasai diletakkan di awal kalimat.","ラーメン 一【ひと】つを ください":"Kurang tepat: Partikel を diletakkan setelah nama barang, bukan setelah kaunter."},tokens:["ラーメンを","一【ひと】つ","ください"],correctOrder:["0","1","2"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Jebakan): Manakah tawaran bantuan yang paling santun?",sentencePrompt:"Pilihlah tawaran membawakan air minum:",options:["お水【みず】を 持【も】って 来【き】ましょうか。","お水【みず】を 持【も】って 来【き】ますよ。","お水【みず】を 持【も】って 来【き】てください。","お水【みず】を 持【も】って 来【き】ました。"],correctAnswer:"お水【みず】を 持【も】って 来【き】ましょうか。",explanation:"Menawarkan bantuan kepada orang lain memakai pola 〜ましょうか.",diagnosticFeedback:{"お水【みず】を 持【も】って 来【き】ますよ。":"Jebakan: Terkesan mendikte atau sekadar mengabarkan aksi diri sendiri.","お水【みず】を 持【も】って 来【き】てください。":"Jebakan: Malah menyuruh lawan bicara membawakan air.","お水【みず】を 持【も】って 来【き】ました。":"Jebakan: Menyatakan bentuk lampau yang sudah selesai."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat rekan kerja berkata "ラーメンを食べましょう！", jawaban menyetujui yang paling wajar adalah:',sentencePrompt:"Pilihlah tanggapan yang antusias:",options:["いいですね！ぜひ 食【た】べましょう。","いいえ、食【た】べません。","ラーメンは さようなら。","お腹【なか】が いっぱいです、食【た】べましょう。"],correctAnswer:"いいですね！ぜひ 食【た】べましょう。",explanation:'Menyetujui ajakan dengan "いいですね！ぜひ〜ましょう".',diagnosticFeedback:{"いいえ、食【た】べません。":"Penolakan ketus yang merusak suasana.","ラーメンは さようなら。":"Sayounara tidak nyambung dalam konteks makan.","お腹【なか】が いっぱいです、食【た】べましょう。":"Kontradiktif: Kenyang tetapi mengajak makan."}}],can_do_challenge:{statement:"Bisa memesan menu di restoran Jepang secara mandiri.",situation:"Memesan menu di kedai makan bersama rekan kerja.",promptTask:"Pesanlah 1 mangkuk ramen dan 2 porsi gyoza kepada pelayan!",modelAnswer:"すみません、ラーメンを 一【ひと】つと ギョーザを 二【ふた】つ ください。",modelAnswerId:"Permisi, tolong ramen satu mangkuk dan gyoza dua porsi ya.",culturalEtiquette:'Ucapkan "Sumimasen" dengan tangan sedikit terangkat untuk memanggil pelayan.',skillUnlocked:["Menguasai kaunter asli Jepang hitotsu, futatsu","Menguasai pola ajakan mashou dan tawaran mashou ka"]},pocket_summary:{keyFormula:"[Nama Makanan] を [Kaunter: ひとつ/ふたつ] ください",coreWords:["ひとつ","ふたつ","みっつ","たべましょう"],coreWarning:"Pemesanan makanan memakai kaunter hitotsu/futatsu, bukan angka biasa ichi/ni.",quickDialogue:"A: 何を 食べますか。 → B: ラーメンを ひとつ ください。"}},"les-n5-u06-02":{pedagogical_framework:{what:{summary:"Menanyakan harga dengan いくら, pembatasan dengan だけ (hanya), pilihan alternatif か (atau), dan daftar tak tuntas や〜など (dan lain-lain).",canDo:"Bisa berbelanja di swalayan, menanyakan harga barang, dan membatasi jumlah pembelian.",targetPatterns:["いくら ですか","[Jumlah/Kata Benda] だけ","[Pilihan A] か [Pilihan B]","[A] や [B] など"],coreVocabSample:["いくら","えん","だけ","りんご","みず","おちゃ"]},sensei_context:{sceneIntro:"Di supermarket dekat asrama, Budi berbelanja buah dan minuman bersama Sakura. Budi belajar menanyakan harga dan memilih barang promo.",dailyMission:"Mampu menanyakan total harga belanjaan dan menyebutkan barang belanjaan dengan partikel や dan など.",whyOrder:"Berbelanja kebutuhan hidup menuntut kemampuan berhitung mata uang Yen dan membedakan pilihan alternatif."},cultural_notes:{title:"Mata Uang Yen & Sistem Pajak Konsumsi di Jepang (消費税)",etiquette:"Di kasir Jepang, uang diletakkan di atas baki kecil (Tsuri-sen tore-), jangan diserahkan langsung ke tangan kasir.",taboos:"Harga di label sering ada dua: Zeinuki (belum pajak 10%) dan Zeikomi (sudah termasuk pajak). Selalu lihat harga Zeikomi (税込)!"},pronunciation_tips:{title:"Pelafalan Mata Uang Yen (円)",moraNote:'Mata uang 円 dilafalkan "en" (bukan "yen" keras). 100 yen = hyaku-en, 1000 yen = sen-en.',soundTip:'Katakan "ikura desu ka" dengan intonasi naik di akhir kata ka.'},common_pitfalls:[{title:'Salah Menempatkan Kata "Dake" (Hanya)',caseScenario:'Meletakkan だけ di depan kata benda seperti bahasa Indonesia "hanya satu".',pitfallWarning:'"だけ ひとつ ください。" (Salah)',rightSolution:'"ひとつ だけ ください。" (Benar)',explanation:"Partikel pembatas だけ selalu menempel di BELAKANG kata benda atau angka jumlah."},{title:"Memakai Partikel と untuk Daftar Panjang yang Masih Ada Lainnya",caseScenario:"Menggunakan と padahal barang yang dibeli masih banyak.",pitfallWarning:'"りんご と みかん を かいました。" (Berarti hanya 2 macam itu saja)',rightSolution:'"りんご や みかん など を かいました。" (Apel, jeruk, dan lain-lain)',explanation:"Partikel や〜など digunakan untuk menyebutkan contoh perwakilan (tidak tuntas)."}],who_and_when:{situational_context:"Kasir supermarket, minimarket (Konbini), atau pasar buah.",social_relations:"Sopan standar kepada kasir dan obrolan santai dengan teman belanja.",when_not_to_use:"Jangan mencoba menawar harga di supermarket resmi Jepang; harga di kasir adalah harga pas."},scenario:{title:"Belanja Kebutuhan Mingguan di Supermarket Life",setting:"Lorong buah dan kasir supermarket, pukul 16.00",narrative:"Budi dan Sakura memilih apel dan minuman segar sambil mengecek harga diskon."}},dialogue:[{id:"d1",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"さくらさん、この リンゴは いくらですか。",furigana:"さくらさん、この リンゴは いくらですか。",romaji:"Sakura-san, kono ringo wa ikura desu ka.",idText:"Sakura-san, apel ini harganya berapa ya?"},{id:"d2",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"一【ひと】つ １５０円【ひゃくごじゅうえん】ですよ。安【やす】いですね。",furigana:"一つ １５０円ですよ。安いですね。",romaji:"Hitotsu hyakugojuuen desu yo. Yasui desu ne.",idText:"Satu buah 150 yen lho. Murah ya."},{id:"d3",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"じゃあ、二【ふた】つ だけ 買【か】います。",furigana:"じゃあ、二つ だけ 買います。",romaji:"Jaa, futatsu dake kaimasu.",idText:"Kalau begitu, saya beli dua buah saja."},{id:"d4",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"飲【の】み物【もの】は お茶【ちゃ】か 水【みず】を 買【か】いますか。",furigana:"飲み物は お茶か 水を 買いますか。",romaji:"Nomimono wa ocha ka mizu o kaimasu ka.",idText:"Kalau minuman mau beli teh atau air mineral?"},{id:"d5",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"お茶【ちゃ】を 買【か】います。パンや 卵【たまご】なども 買【か】いたいです。",furigana:"お茶を 買います。パンや 卵なども 買いたいです。",romaji:"Ocha o kaimasu. Pan ya tamago nado mo kaitai desu.",idText:"Saya beli teh. Saya juga ingin beli roti, telur, dan lain-lain."},{id:"d6",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"あちらの コーナーに ありますよ。一緒【いっしょ】に 行【い】きましょう。",furigana:"あちらの コーナーに ありますよ。一緒に 行きましょう。",romaji:"Achira no ko-na- ni arimasu yo. Issho ni ikimashou.",idText:"Ada di lorong sebelah sana lho. Ayo kita ke sana bareng."},{id:"d7",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"全部【ぜんぶ】で いくらくらいに なりますか。",furigana:"全部で いくらくらいに なりますか。",romaji:"Zenbu de ikura kurai ni narimasu ka.",idText:"Kira-kira semuanya jadi berapa ya?"},{id:"d8",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"たぶん １０００円【せんえん】くらいですよ。",furigana:"たぶん １０００円くらいですよ。",romaji:"Tabun sen-en kurai desu yo.",idText:"Mungkin sekitar 1000 yen kok."}],vocab_breakdown:[{id:"vg-n5-00583",word:"六つ",reading:"むっつ",romaji:"mutttsu",meaning:"enam (menghitung)",pos:"counter",nuance:"Applies to counting six general objects without a specific shape or counter. It's part of the traditional Japanese counting system that only goes up to ten.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"お皿の上にトマトが六つあります。",furigana:"お皿の上にトマトが六つあります。",romaji:"",idText:"Ada enam buah tomat di atas piring."}},{id:"vg-n5-00584",word:"七つ",reading:"ななつ",romaji:"nanatsu",meaning:"tujuh (menghitung)",pos:"counter",nuance:"Used to count seven general items. In traditional Japanese folklore, the age of seven is often seen as a significant milestone, famously referenced in songs.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"机の上にコップが七つ並んでいます。",furigana:"机の上にコップが七つ並んでいます。",romaji:"",idText:"Ada tujuh buah gelas berjejer di atas meja."}},{id:"vg-n5-00585",word:"八つ",reading:"やっつ",romaji:"yatttsu",meaning:"delapan (menghitung)",pos:"counter",nuance:"Used for counting eight items. Be careful to pronounce the small 'tsu' clearly to differentiate it from other words.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"お菓子を八つ買いました。",furigana:"お菓子を八つ買いました。",romaji:"",idText:"Saya membeli delapan bungkus makanan ringan."}},{id:"vg-n5-00586",word:"九つ",reading:"ここのつ",romaji:"kokonotsu",meaning:"sembilan (menghitung)",pos:"counter",nuance:"The word for counting nine general objects. It is one of the few numbers in this native counting system with four syllables.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"みかんが全部で九つあります。",furigana:"みかんが全部で九つあります。",romaji:"",idText:"Ada sembilan buah jeruk secara keseluruhan."}},{id:"vg-n5-00665",word:"みかん",reading:"みかん",romaji:"mikan",meaning:"jeruk keprok",pos:"noun",nuance:"Refers specifically to the Japanese mandarin orange, a staple winter fruit often eaten while sitting under a kotatsu.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"冬にこたつでみかんを食べるのが好きです。",furigana:"冬にこたつでみかんを食べるのが好きです。",romaji:"",idText:"Saya suka makan jeruk keprok di kotatsu saat musim dingin."}},{id:"vg-n5-00666",word:"いちご",reading:"いちご",romaji:"ichigo",meaning:"stroberi",pos:"noun",nuance:"A popular fruit in Japan, especially associated with Christmas cakes. The word can be written in kanji (苺) but is usually written in hiragana.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"甘くておいしいいちごを食べました。",furigana:"甘くておいしいいちごを食べました。",romaji:"",idText:"Saya makan stroberi yang manis dan enak."}},{id:"vg-n5-00667",word:"ぶどう",reading:"ぶどう",romaji:"budou",meaning:"anggur",pos:"noun",nuance:"Refers to grapes. Japanese grapes are often eaten peeled, unlike in many Western countries.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"スーパーで紫色のぶどうを一房買いました。",furigana:"スーパーで紫色のぶどうを一房買いました。",romaji:"",idText:"Saya membeli satu tangkai anggur ungu di supermarket."}},{id:"vg-n5-00668",word:"のりもの",reading:"のりもの",romaji:"norimono",meaning:"kendaraan",pos:"noun",nuance:"Literally 'thing to ride'. It encompasses cars, trains, buses, airplanes, and even amusement park rides.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"電車やバスなど、色々なのりものがあります。",furigana:"電車やバスなど、色々なのりものがあります。",romaji:"",idText:"Ada berbagai macam kendaraan seperti kereta dan bus."}},{id:"vg-n5-00669",word:"オートバイ",reading:"オートバイ",romaji:"o-tobai",meaning:"motor",pos:"noun",nuance:"A Japanese portmanteau of 'auto' and 'bicycle' (bike). The shorter term 'baiku' is also very commonly used for motorcycles.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"兄はオートバイに乗って会社へ行きます。",furigana:"兄はオートバイに乗って会社へ行きます。",romaji:"",idText:"Kakak laki-laki saya naik motor pergi ke kantor."}},{id:"vg-n5-00670",word:"ふね",reading:"ふね",romaji:"fune",meaning:"kapal",pos:"noun",nuance:"手紙 = surat (fisik). Berbeda: メール = email. 手紙を書く = menulis surat.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"友だちに手紙を書きました。",furigana:"友だちに手紙を書きました。",romaji:"",idText:"Saya menulis surat untuk teman."}}],explanations:[{id:"exp-1",grammarId:"gn5-00022",title:"Pola: だけ (hanya)",formula:"N / Vる / Vた + だけ",meaning:"hanya / saja",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"だけ (hanya)",idText:"hanya / saja"}],examples:[{jp:"みずだけのみます。",romaji:"",idText:"Minum air saja."},{jp:"ひとつだけください。",romaji:"",idText:"Tolong satu saja."}]},{id:"exp-2",grammarId:"gn5-00023",title:"Pola: しか〜ない",formula:"N + しか + Vない",meaning:"hanya (dengan negatif)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"しか〜ない",idText:"hanya (dengan negatif)"}],examples:[{jp:"お金が100円しかありません。",romaji:"",idText:"Uangnya cuma ada 100 yen."},{jp:"かれしかしらない。",romaji:"",idText:"Hanya dia yang tahu."}]},{id:"exp-3",grammarId:"gn5-00074",title:"Pola: 〜か〜か",formula:"A + か + B + か",meaning:"apakah ... atau ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜か〜か",idText:"apakah ... atau ..."}],examples:[{jp:"いくかいかないかまだわかりません。",romaji:"",idText:"Belum tahu apakah pergi atau tidak."},{jp:"コーヒーかこうちゃか、どちらがいいですか。",romaji:"",idText:"Kopi atau teh, yang mana lebih baik?"}]},{id:"exp-4",grammarId:"gn5-00075",title:"Pola: 〜も〜も",formula:"N1 + も + N2 + も (afirmatif/negatif)",meaning:"baik ... maupun ... / ... juga ... juga ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜も〜も",idText:"baik ... maupun ... / ... juga ... juga ..."}],examples:[{jp:"すしもてんぷらもすきです。",romaji:"",idText:"Suka sushi maupun tempura."},{jp:"えいごもフランスごもはなせます。",romaji:"",idText:"Bisa berbicara bahasa Inggris maupun Prancis."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah kata tanya harga yang tepat.",sentencePrompt:"Kata tanya untuk menanyakan harga barang adalah:",options:["いくら (ikura)","いくつ (ikutsu)","いつ (itsu)","どこ (doko)"],correctAnswer:"いくら (ikura)",explanation:'"いくら (ikura)" berarti berapa harganya. いくつ = berapa banyak, いつ = kapan, どこ = di mana.',diagnosticFeedback:{"いくつ (ikutsu)":"Salah: いくつ menanyakan jumlah buah benda, bukan harga.","いつ (itsu)":"Salah: いつ menanyakan waktu/kapan.","どこ (doko)":"Salah: どこ menanyakan tempat/lokasi."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Isian Partikel Pembatas): Pilihlah partikel yang bermakna "hanya".',sentencePrompt:"リンゴを 二【ふた】つ _____ 買【か】いました。",options:["だけ","と","や","か"],correctAnswer:"だけ",explanation:'Partikel だけ berarti "hanya / cuma" dan diletakkan setelah jumlah: 二つだけ (hanya dua buah).',diagnosticFeedback:{と:'Salah: Partikel と berarti "dan" tuntas.',や:"Salah: Partikel や digunakan untuk contoh daftar tidak tuntas.",か:'Salah: Partikel か berarti "atau" pilihan alternatif.'}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Urutkan kalimat yang menyebutkan beberapa barang dengan や〜など berikut.",sentencePrompt:"Susunan kalimat yang tepat:",options:["パンや 卵【たまご】などを 買【か】います","などを パンや 卵【たまご】 買【か】います","買【か】います パンや 卵【たまご】などを","パンと 卵【たまご】などを 買【か】います"],correctAnswer:"パンや 卵【たまご】などを 買【か】います",explanation:"Pola daftar perwakilan: [A] や [B] など + を 買います.",diagnosticFeedback:{"などを パンや 卵【たまご】 買【か】います":"Jebakan: Kata nado diletakkan terbalik di awal.","買【か】います パンや 卵【たまご】などを":"Jebakan: Kata kerja di awal kalimat.","パンと 卵【たまご】などを 買【か】います":"Jebakan: Partikel と tidak dipasangkan dengan など."},tokens:["パンや","卵【たまご】などを","買【か】います"],correctOrder:["0","1","2"]},{id:"drill-4",type:"trap_detect",instruction:'Langkah 4 (Deteksi Jebakan): Pilihlah kalimat pilihan "A atau B" yang benar.',sentencePrompt:"Manakah kalimat penawaran pilihan alternatif yang tepat?",options:["お茶【ちゃ】か 水【みず】を 飲【の】みますか。","お茶【ちゃ】と 水【みず】を 飲【の】みますか。","お茶【ちゃ】や 水【みず】を 飲【の】みますか。","お茶【ちゃ】で 水【みず】を 飲【の】みますか。"],correctAnswer:"お茶【ちゃ】か 水【みず】を 飲【の】みますか。",explanation:'Pilihan alternatif "atau" dinyatakan dengan partikel か di antara dua nomina.',diagnosticFeedback:{"お茶【ちゃ】と 水【みず】を 飲【の】みますか。":"Jebakan: と berarti minum keduanya (teh DAN air).","お茶【ちゃ】や 水【みず】を 飲【の】みますか。":"Jebakan: や berarti menyebutkan contoh perwakilan.","お茶【ちゃ】で 水【みず】を 飲【の】みますか。":"Jebakan: Partikel で salah konteks."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat kasir menyebutkan "全部で １０００円です", respon dan tindakan yang tepat adalah:',sentencePrompt:"Pilihlah ungkapan saat membayar di kasir:",options:["はい、１０００円【せんえん】です。お願【ねが】いします。","高【たか】いから 買【か】いません。","さようなら、ありがとう。","いくらですか、教【おし】えてください。"],correctAnswer:"はい、１０００円【せんえん】です。お願【ねが】いします。",explanation:'Menyerahkan uang pas ke baki dengan ucapan "Hai, sen-en desu. Onegai shimasu".',diagnosticFeedback:{"高【たか】いから 買【か】いません。":"Sangat kasar membatalkan transaksi tiba-tiba di depan kasir.","さようなら、ありがとう。":"Belum membayar sudah pamit keluar.","いくらですか、教【おし】えてください。":"Kasir sudah menyebutkan nominalnya."}}],can_do_challenge:{statement:"Bisa menanyakan harga belanja dan membatasi jumlah pembelian.",situation:"Membeli buah di supermarket Jepang.",promptTask:"Tanyakan berapa harga buah apel, lalu katakan kamu hanya beli satu buah!",modelAnswer:"この リンゴは いくらですか。じゃあ、一【ひと】つ だけ ください。",modelAnswerId:"Apel ini harganya berapa? Kalau begitu, tolong satu buah saja.",culturalEtiquette:"Tanyakan harga dengan nada sopan dan letakkan だけ di belakang jumlah.",skillUnlocked:["Menguasai pertanyaan harga ikura","Menguasai pembatasan dake dan pilihan alternatif ka"]},pocket_summary:{keyFormula:"[Benda] は いくらですか / [Jumlah] だけ ください",coreWords:["いくら","えん","だけ","りんご"],coreWarning:'"だけ" diletakkan setelah jumlah. "や" untuk contoh barang tidak tuntas.',quickDialogue:"A: これは いくらですか。 → B: 100円です。ひとつ だけ 買います。"}}},k={"les-n5-u07-01":{pedagogical_framework:{what:{summary:"Pola penanda waktu spesifik dengan partikel に, lokasi aktivitas aksi dengan partikel で, dan rentang durasi waktu/tempat (から〜まで).",canDo:"Bisa menceritakan jadwal jam bangun tidur, jam kerja/belajar, tempat melakukan aktivitas (belajar di perpustakaan, makan di kantin), dan rentang waktu dari jam berapa sampai jam berapa.",targetPatterns:["[Jam/Hari] に [Verba]ます","[Tempat] で [Aksi]を します","[Waktu A] から [Waktu B] まで","なんじに 起きますか"],coreVocabSample:["おきる","ねる","べんきょうする","はたらく","やすむ","いま","なんじ","まいあさ","まいばん","としょかん","しょくどう"]},sensei_context:{sceneIntro:"Sakura-san membantu Budi mencocokkan jadwal shift kerja dan jam belajar mandiri di perpustakaan komunitas.",dailyMission:'Mampu membedakan dengan sempurna kapan partikel "ni" digunakan untuk waktu spesifik (ada angka jam/tanggal) vs kata waktu relatif (kyou, ashita tanpa ni), serta partikel "de" untuk lokasi aktivitas aksi.',whyOrder:'Ini adalah titik krusial pembeda tingkat lanjut di N5: Pembelajar sering bingung membedakan "ni" lokasi keberadaan (Unit 3: heya ni arimasu) vs "de" lokasi aksi (Unit 4: heya de tabemasu). Menguasai trik ini akan menjamin kamu tidak pernah keliru lagi!'},cultural_notes:{title:"Manajemen Waktu 5 Menit Lebih Awal (5-Fun Mae Koudou)",etiquette:'Di dunia profesional Jepang berlaku aturan tidak tertulis "5-fun mae koudou" (５分前行動): selalu tiba di lokasi pertemuan atau mulai bekerja minimal 5 menit sebelum jam yang ditentukan.',taboos:"Jangan terlambat tanpa pemberitahuan sebelumnya (renraku). Jika kereta mengalami keterlambatan (chien), mintalah surat bukti keterlambatan (chien-shoumeisho) di loket stasiun untuk diserahkan ke kantor."},pronunciation_tips:{title:"Penyebutan Angka Jam Khusus: 4-ji, 7-ji, 9-ji",moraNote:"Hati-hati dengan jam 4 (yo-ji, BUKAN yon-ji), jam 7 (shichi-ji, BUKAN nana-ji), dan jam 9 (ku-ji, BUKAN kyuu-ji).",soundTip:"Menit kelipatan sepuluh diucapkan dengan sokuon kecil: 10 menit = juppun / jippun, 20 menit = nijuppun, 30 menit = han / sanjuppun."},common_pitfalls:[{title:'Memasang Partikel "ni" pada Kata Waktu Relatif (Kyou, Ashita)',caseScenario:'Refleks menambahkan partikel "ni" pada semua kata waktu.',pitfallWarning:'"きょうに べんきょうします。" (Kyou ni benkyou shimasu)',rightSolution:'"きょう べんきょうします。" (Kyou benkyou shimasu - tanpa に)',explanation:'Partikel "ni" HANYA dipasang pada waktu yang memiliki angka spesifik (jam 7, tanggal 15, bulan Mei, hari Senin). Kata waktu relatif (kyou, ashita, kinou, maiasa, konshu) TIDAK BOLEH memakai "ni".'},{title:'Jebakan "ni" vs "de": Lokasi Aksi Ditulis dengan Partikel ni',caseScenario:'Ingin bilang "belajar di perpustakaan" tapi memakai partikel "ni" karena terjemahan bahasa Indonesia sama-sama "di".',pitfallWarning:'"としょかんに べんきょうします。" (Toshokan ni benkyou shimasu)',rightSolution:'"としょかんで べんきょうします。" (Toshokan de benkyou shimasu)',explanation:'Jika di tempat itu terjadi aktivitas dinamis (belajar, makan, bekerja, membeli), partikelnya WAJIB "de" (で). Partikel "ni" di tempat hanya untuk keberadaan pasif (arimasu/imasu) atau titik kedatangan.'}],who_and_when:{situational_context:"Mengisi jadwal piket, menyepakati jam shift kerja paruh waktu (arubaito), mengatur rencana belajar di perpustakaan bersama teman.",social_relations:"Bahasa sopan standar formal (~masu / ~masen) yang digunakan kepada pengawas kerja, instruktur, maupun rekan pembelajar.",when_not_to_use:"Jangan gunakan kara~made jika hanya menyebutkan jam mulai saja tanpa batas akhir (cukup sebut ~kara)."},scenario:{title:"Menyusun Rencana Jadwal Shift dan Belajar di Perpustakaan",setting:"Ruang Belajar Bersama Asrama Malam Hari Pukul 20.00",narrative:"Budi membuka buku agenda saku. Sakura melihat jadwal shift kerja Budi dan menanyakan kapan ia biasa belajar bahasa Jepang."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Senior Jepang",avatar:"👩‍💼",jp:"ブディさん、毎朝【まいあさ】 何時【なんじ】に 起【お】きますか。",furigana:"ブディさん、毎朝 何時に 起きますか。",romaji:"Budi-san, maiasa nanji ni okimasu ka.",idText:"Budi-san, setiap pagi jam berapa kamu bangun?",note:"Sakura melihat agenda Budi"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"６時【ろくじ】に 起【お】きます。それから、食堂【しょくどう】で 朝【あさ】ごはんを 食【た】べます。",furigana:"６時に 起きます。それから、食堂で 朝ごはんを 食べます。",romaji:"Rokuji ni okimasu. Sorekara, shokudou de asagohan o tabemasu.",idText:"Saya bangun jam 6. Setelah itu, makan sarapan di kantin."},{id:"d3",speaker:"Sakura",speakerRole:"Senior Jepang",avatar:"👩‍💼",jp:"早【はや】いですね！仕事【しごと】は 何時【なんじ】から 何時【なんじ】までですか。",furigana:"早いですね！仕事は 何時から 何時までですか。",romaji:"Hayai desu ne! Shigoto wa nanji kara nanji made desu ka.",idText:"Pagi sekali ya! Kerjamu dari jam berapa sampai jam berapa?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"９時【くじ】から ５時【ごじ】まで 働【はたら】きます。昼休【ひるやす】みは １２時【じゅうにじ】からです。",furigana:"９時から ５時まで 働きます。昼休みは １２時からです。",romaji:"Kuji kara goji made hatarakimasu. Hiruyasumi wa juuniji kara desu.",idText:"Saya bekerja dari jam 9 sampai jam 5. Istirahat siang mulai jam 12."},{id:"d5",speaker:"Sakura",speakerRole:"Senior Jepang",avatar:"👩‍💼",jp:"日本語【にほんご】の 勉強【べんきょう】は どこで しますか。",furigana:"日本語の 勉強は どこで しますか。",romaji:"Nihongo no benkyou wa doko de shimasu ka.",idText:"Kamu belajar bahasa Jepang di mana?"},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"夜【よる】 図書館【としょかん】で 勉強【べんきょう】します。８時【はちじ】から １０時【じゅうじ】までです。",furigana:"夜 図書館で 勉強します。８時から １０時までです。",romaji:"Yoru toshokan de benkyou shimasu. Hachiji kara juuji made desu.",idText:"Malam hari saya belajar di perpustakaan. Dari jam 8 sampai jam 10."}],vocab_breakdown:[{id:"v1",word:"おきる",reading:"おきる",romaji:"okiru",meaning:"bangun tidur (bentuk masu: おきます)",nuance:"Verba golongan 2 (Ichidan). Pasangan waktu spesifiknya memakai partikel に.",exampleSentence:{jp:"まいあさ ろくじに おきます。",furigana:"毎朝 ６時に 起きます。",romaji:"Maiasa rokuji ni okimasu.",idText:"Setiap pagi saya bangun jam 6."}},{id:"v2",word:"ねる",reading:"ねる",romaji:"neru",meaning:"tidur, berbaring (bentuk masu: ねます)",nuance:"Verba golongan 2 (Ichidan). Lawan kata dari おきる.",exampleSentence:{jp:"じゅういちじに ねます。",furigana:"１１時に 寝ます。",romaji:"Juuichiji ni nemasu.",idText:"Saya tidur jam 11."}},{id:"v3",word:"はたらく",reading:"はたらく",romaji:"hataraku",meaning:"bekerja (bentuk masu: はたらきます)",nuance:"Verba golongan 1 (Godan). Tempat bekerja ditandai partikel で (misal: koujou de hatarakimasu).",exampleSentence:{jp:"かいしゃで はたらきます。",furigana:"会社で 働きます。",romaji:"Kaisha de hatarakimasu.",idText:"Saya bekerja di kantor."}},{id:"v4",word:"べんきょうする",reading:"べんきょうする",romaji:"benkyou suru",meaning:"belajar (bentuk masu: べんきょうします)",nuance:"Verba golongan 3 (gabungan kata benda benkyou + verba suru).",exampleSentence:{jp:"へやで にほんごを べんきょうします。",furigana:"部屋で 日本語を 勉強します。",romaji:"Heya de nihongo o benkyou shimasu.",idText:"Saya belajar bahasa Jepang di kamar."}},{id:"v5",word:"としょかん",reading:"としょかん",romaji:"toshokan",meaning:"perpustakaan",nuance:"Tempat publik yang tenang untuk meminjam buku dan belajar mandiri.",exampleSentence:{jp:"としょかんで ほんを よみます。",furigana:"図書館で 本を 読みます。",romaji:"Toshokan de hon o yomimasu.",idText:"Saya membaca buku di perpustakaan."}}],explanations:[{id:"e1",title:"1. Partikel に (ni) untuk Waktu Spesifik Bertitik Angka",formula:"[Waktu dengan Angka / Hari] + に + [Verba]ます",meaning:"Menyatakan titik waktu dilakukannya suatu aktivitas (pada jam X, pada hari Senin).",nuanceNotes:"Gunakan に jika kata waktu memuat angka jam (6-ji ni), menit (han ni), tanggal, atau nama hari (Getsuyoubi ni). DILARANG memakai に untuk kata waktu relatif seperti kyou (hari ini), ashita (besok), kinou (kemarin), maiasa (setiap pagi), ima (sekarang).",examples:[{jp:"ろくじはんに おきます。",furigana:"６時半に 起きます。",romaji:"Rokuji-han ni okimasu.",idText:"Saya bangun jam setengah 7."},{jp:"あした べんきょうします。",furigana:"明日 勉強します。",romaji:"Ashita benkyou shimasu.",idText:"Besok saya belajar (tanpa に)."}]},{id:"e2",title:"2. Partikel で (de) untuk Lokasi Aktivitas Aksi",formula:"[Tempat Aksi] + で + [Objek] を [Verba]ます",meaning:"Melakukan kegiatan aksi di suatu tempat (makan di kantin, belajar di kamar).",nuanceNotes:"Bedakan tegas dengan partikel に pada Unit 3: Partikel に untuk keberadaan diam (Heya ni terebi ga arimasu), sedangkan partikel で untuk aksi dinamis (Heya de terebi o mimasu).",examples:[{jp:"しょくどうで ひるごはんを たべます。",furigana:"食堂で 昼ごはんを 食べます。",romaji:"Shokudou de hirugohan o tabemasu.",idText:"Saya makan siang di kantin."}]},{id:"e3",title:"3. Rentang Waktu dan Tempat: 〜から 〜まで (kara ~ made)",formula:"[Titik Awal] から + [Titik Akhir] まで",meaning:"Dari [titik awal] sampai [titik akhir]. Bisa untuk jam, hari, maupun lokasi rute.",nuanceNotes:"Dapat dipakai bersamaan (~kara ~made hatarakimasu) atau berdiri sendiri salah satunya (~kara desu).",examples:[{jp:"くじから ごじまで はたらきます。",furigana:"９時から ５時まで 働きます。",romaji:"Kuji kara goji made hatarakimasu.",idText:"Saya bekerja dari jam 9 sampai jam 5."},{jp:"とうきょうから おおさかまで でんしゃで いきます。",furigana:"東京から 大阪まで 電車で 行きます。",romaji:"Toukyou kara Oosaka made densha de ikimasu.",idText:"Dari Tokyo sampai Osaka saya pergi naik kereta."}]}],drills:[{id:"drill-u04-03-1",type:"vocab_context",instruction:"Pilihlah makna bahasa Indonesia yang tepat untuk: 「くじから ごじまで はたらきます。」",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["Bekerja dari jam 9 sampai jam 5.","Mulai tidur jam 9 sampai jam 5 pagi.","Belajar di perpustakaan jam 9 pagi.","Pergi ke kantor jam 5 sore."],correctAnswer:"Bekerja dari jam 9 sampai jam 5.",explanation:"くじから (dari jam 9) ごじまで (sampai jam 5) はたらきます (bekerja).",diagnosticFeedback:{"Mulai tidur jam 9 sampai jam 5 pagi.":"Salah verba: hatarakimasu adalah bekerja, bukan tidur (nemasu).","Belajar di perpustakaan jam 9 pagi.":"Salah verba: bukan belajar (benkyou shimasu).","Pergi ke kantor jam 5 sore.":"Salah arti rentang waktu."}},{id:"drill-u04-03-2",type:"cloze",instruction:"Manakah partikel yang tepat untuk melengkapi kalimat: 「としょかん（　）ほんを よみます。」",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["で","に","へ","を"],correctAnswer:"で",explanation:"Perpustakaan (toshokan) adalah tempat berlangsungnya tindakan membaca buku, sehingga wajib menggunakan partikel で.",diagnosticFeedback:{に:"Partikel に di lokasi hanya untuk keberadaan pasif (ada barang/orang) atau tujuan tiba, bukan aktivitas membaca.",へ:"Partikel へ digunakan untuk arah perjalanan pergi/pulang, bukan tempat membaca buku.",を:"Partikel を menandai objek buku (hon o), bukan tempat gedungnya."}},{id:"drill-u04-03-3",type:"reorder",instruction:"Susunlah kata-kata berikut menjadi kalimat yang benar: [おきます] [まいあさ] [に] [ろくじ]",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["まいあさ ろくじに おきます。","ろくじに まいあさ おきます。","まいあさ に ろくじ おきます。","おきます まいあさ ろくじに。"],correctAnswer:"まいあさ ろくじに おきます。",explanation:"Urutan alami bahasa Jepang: Waktu umum (maiasa) -> Waktu spesifik + に (rokuji ni) -> Verba predikat (okimasu).",diagnosticFeedback:{"ろくじに まいあさ おきます。":"Meskipun dipahami, meletakkan waktu umum (maiasa) di paling depan jauh lebih alami.","まいあさ に ろくじ おきます。":"Salah letak partikel に: Partikel に harus menempel di belakang angka jam ろくじ, bukan di belakang maiasa.","おきます まいあさ ろくじに。":"Predikat verba tidak boleh di awal kalimat."},tokens:["まいあさ","ろくじに","おきます。"],correctOrder:["0","1","2"]},{id:"drill-u04-03-4",type:"trap_detect",instruction:"Manakah di antara kalimat berikut yang MENGANDUNG KESALAHAN tata bahasa partikel waktu?",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["あしたに ともだちと あいます。","あした ともだちと あいます。","しちじに おきます。","げつようびに テストが あります。"],correctAnswer:"あしたに ともだちと あいます。",explanation:'Kata waktu relatif "ashita" (besok) TIDAK BOLEH dipasangi partikel に ("ashita ni" adalah kesalahan fatal).',diagnosticFeedback:{"あした ともだちと あいます。":"Kalimat ini benar (tanpa partikel に).","しちじに おきます。":"Kalimat ini benar (angka jam wajib memakai に).","げつようびに テストが あります。":"Kalimat ini benar (nama hari boleh memakai に)."}},{id:"drill-u04-03-5",type:"response",instruction:"Sakura bertanya: 「ブディさん、まいばん なんじから なんじまで べんきょうしますか。」 Jika kamu belajar dari jam 8 sampai jam 10 di kamar, bagaimana menjawabnya?",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["へやで はちじから じゅうじまで べんきょうします。","へやに はちじから じゅうじまで べんきょうします。","はちじに じゅうじまで へやを べんきょうします。","としょかんで はちじに ねます。"],correctAnswer:"へやで はちじから じゅうじまで べんきょうします。",explanation:"Lokasi aktivitas: heya de, rentang waktu: hachiji kara juuji made, predikat: benkyou shimasu.",diagnosticFeedback:{"へやに はちじから じゅうじまで べんきょうします。":"Salah partikel: Lokasi aktivitas belajar wajib menggunakan で, bukan に.","はちじに じゅうじまで へやを べんきょうします。":"Salah partikel: Pasangan rentang waktu adalah kara~made, bukan ni~made.","としょかんで はちじに ねます。":"Salah konteks: Malah menjawab tidur jam 8 di perpustakaan."}}],can_do_challenge:{statement:"Bisa menjelaskan jadwal harian, jam aktivitas, dan tempat melakukan kegiatan secara presisi.",situation:"Sedang wawancara kerja paruh waktu atau menjelaskan jadwal mingguan kepada atasan asrama.",promptTask:"Katakan bahwa kamu setiap hari bekerja dari jam 9 sampai jam 5, dan belajar bahasa Jepang di kamar pada malam hari!",modelAnswer:"まいにち くじから ごじまで はたらきます。よる へやで にほんごを べんきょうします。",modelAnswerId:"Setiap hari saya bekerja dari jam 9 sampai jam 5. Malam hari saya belajar bahasa Jepang di kamar.",culturalEtiquette:"Ucapkan jam kerja dan rentang waktu dengan runtut dan percaya diri.",skillUnlocked:["Menguasai pembedaan fundamental partikel waktu spesifik に vs kata waktu relatif","Menguasai pembedaan partikel lokasi aksi で vs lokasi keberadaan statis に","Mampu menyatakan rentang waktu dan tempat から〜まで secara alami"],pocketSummary:{keyFormula:"[Jam] に + [Tempat Aksi] で + [Waktu A] から [Waktu B] まで [Verba]ます",coreWords:["おきる (bangun)","ねる (tidur)","はたらく (bekerja)","べんきょうする (belajar)","から〜まで (dari~sampai)"],coreWarning:"Angka jam = pakai に! Waktu relatif (kyou/ashita/maiasa) = JANGAN pakai に! Lokasi aksi = selalu pakai で!",quickDialogue:"A: 何時に どこで べんきょうしますか？ → B: はちじに へやで べんきょうします。"}},pocket_summary:{keyFormula:"[Jam] に + [Tempat] で + [Verba]ます / [Waktu] から [Waktu] まで",coreWords:["おきる (bangun)","ねる (tidur)","はたらく (bekerja)","としょかん (perpustakaan)"],coreWarning:"Jangan beri に pada kyou/ashita! Lokasi aktivitas memakai で (bukan に).",quickDialogue:"A: なんじからですか？ → B: くじから ごじまでです。"}},"les-n5-u07-02":{pedagogical_framework:{what:{summary:"Pola pemesanan makanan/barang menggunakan kata bantu bilangan asli Jepang (ひとつ, ふたつ, みっつ) dan permohonan sopan (〜を ください / お願いします).",canDo:"Bisa memesan makanan di konbini, restoran cepat saji, atau kedai makan dengan menyebutkan jumlah porsi/item secara tepat dan santun.",targetPatterns:["[Benda] を [Jumlah] ください","[Benda] を [Jumlah] おねがいします","ひとつ, ふたつ, みっつ (bilangan asli Jepang)"],coreVocabSample:["ひとつ","ふたつ","みっつ","よっつ","いつつ","ください","おねがいします","おにぎり","べんとう","おちゃ","みず"]},sensei_context:{sceneIntro:"Budi dan Sakura sedang singgah di sebuah konbini (convenience store) di Tokyo saat jam istirahat siang. Budi ingin membeli onigiri dan memesan ayam goreng (karaage) di etalase kasir.",dailyMission:"Mampu memesan makanan dan minuman dengan menyebutkan jumlah porsi secara tepat menggunakan bilangan asli Jepang (hitotsu, futatsu, mittsu) tanpa tertukar dengan angka kardinal (ichi, ni, san).",whyOrder:'Di Unit 4 kita belajar kata kerja aktivitas (makan, minum). Namun saat berada di kasir atau restoran Jepang, kamu tidak bisa sekadar bilang "onigiri tabemasu". Kamu harus memesan dengan formula baku pemesanan: [Benda] + を + [Jumlah] + ください!'},cultural_notes:{title:"Budaya Konbini dan Pelayanan Kasir di Jepang",etiquette:'Saat kasir menyerahkan bento atau onigiri, kasir biasanya bertanya: "Atatamemasu ka?" (Apakah ingin dihangatkan di microwave?). Cukup jawab: "Hai, onegaishimasu" (Ya, tolong dihangatkan) atau "Daijoubu desu" (Tidak usah, terima kasih).',taboos:"Jangan meletakkan uang lembaran atau koin langsung ke tangan kasir. Selalu taruh uang di atas nampan kecil koin (tsuri-tore / カリートレイ) yang disediakan di meja kasir."},pronunciation_tips:{title:"Irama Hitungan Asli Jepang (Hitotsu, Futatsu, Mittsu)",moraNote:"Perhatikan konsonan ganda sokuon (tsu kecil) pada mittsu (みっつ) dan yottsu (よっつ). Beri jeda 1 ketukan napas tertahan di tenggorokan sebelum melafalkan -tsu.",soundTip:'Frasa "Kudasai" diucapkan datar dan lembut, bukan membentak laksana instruksi militer. "Onegaishimasu" terdengar lebih elegan dan santun bila memesan jasa/layanan.'},common_pitfalls:[{title:"Memakai Angka Biasa (Ichi, Ni) Alih-alih Kata Bantu Bilangan (Hitotsu, Futatsu)",caseScenario:'Di kasir memesan onigiri dengan mengatakan "Onigiri o ichi kudasai".',pitfallWarning:'"おにぎりを いち ください。" (Ichi kudasai - tidak alami)',rightSolution:'"おにぎりを ひとつ ください。" (Hitotsu kudasai - benar & alami)',explanation:"Angka biasa (ichi, ni, san) hanya digunakan untuk nomor telepon, jam, atau berhitung matematis. Untuk memesan satuan barang umum, WAJIB menggunakan bilangan asli berakhiran -tsu (hitotsu, futatsu, dst.)."},{title:"Salah Peletakan Partikel: Menyelipkan Partikel を Setelah Jumlah",caseScenario:'Menyusun kalimat: "Onigiri hitotsu o kudasai".',pitfallWarning:'"おにぎり ひとつを ください。" (Salah letak partikel)',rightSolution:'"おにぎりを ひとつ ください。" (Benar: Benda + を + Jumlah + ください)',explanation:"Dalam susunan tata bahasa standar bahasa Jepang, kata bantu bilangan diletakkan langsung sebelum verba kudasai/onegaishimasu TANPA partikel penengah."},{title:"Tertukar Jumlah Tiga (Mittsu) dan Enam (Muttsu)",caseScenario:"Berniat memesan 3 potong ayam goreng tapi salah ucap menjadi muttsu (6 potong).",pitfallWarning:'"からあげを むっつ ください。" (Muttsu = 6)',rightSolution:'"からあげを みっつ ください。" (Mittsu = 3)',explanation:'Bunyi vokal "i" pada mittsu (みっつ = 3) dan "u" pada muttsu (むっつ = 6) sangat mirip bagi telinga orang Indonesia. Ingat jembatan keledai: M-I-ttsu = T-I-ga.'}],who_and_when:{situational_context:"Memesan makanan di konbini, restoran Teishoku, kafe, atau membeli tiket di loket fisik.",social_relations:"Ragam sopan universal (Teineigo) yang wajib dikuasai untuk transaksi belanja sehari-hari di seluruh pelosok Jepang.",when_not_to_use:"Bilangan berakhiran -tsu hanya berlaku dari hitungan 1 sampai 10 (tou). Di atas 10, kembali menggunakan angka biasa diikuti kata bantu satuan khusus."},scenario:{title:"Membeli Makan Siang di Konbini Dekat Kantor",setting:"Kasir Konbini Tokyo Pukul 12.10 Siang",narrative:"Budi dan Sakura antre di kasir konbini membawa keranjang belanjaan. Sakura mengajari Budi cara memesan ayam goreng hangat di etalase kasir."}},dialogue:[{id:"d1",speaker:"Kasir",speakerRole:"Staf Toko",avatar:"🏪",jp:"いらっしゃいませ！",furigana:"いらっしゃいませ！",romaji:"Irasshaimase!",idText:"Selamat datang!",note:"Kasir membungkuk memberi salam"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"すみません、鮭【しゃけ】の おにぎりを 二【ふた】つ ください。",furigana:"すみません、鮭の おにぎりを 二つ ください。",romaji:"Sumimasen, shake no onigiri o futatsu kudasai.",idText:"Permisi, tolong berikan dua onigiri salmon."},{id:"d3",speaker:"Kasir",speakerRole:"Staf Toko",avatar:"🏪",jp:"はい、鮭【しゃけ】 おにぎり 二つですね。他【ほか】には いかがですか。",furigana:"はい、鮭 おにぎり 二つですね。他には いかがですか。",romaji:"Hai, shake onigiri futatsu desu ne. Hoka ni wa ikaga desu ka.",idText:"Baik, onigiri salmon dua ya. Apakah ada pesanan lainnya?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"それから、唐揚【からあ】げを 一【ひと】つ お願【ねが】いします。",furigana:"それから、唐揚げを 一つ お願いします。",romaji:"Sorekara, karaage o hitotsu onegaishimasu.",idText:"Kemudian, tolong satu ayam goreng tepungnya."},{id:"d5",speaker:"Sakura",speakerRole:"Senior Jepang",avatar:"👩‍💼",jp:"ブディさん、お茶【ちゃ】は 要【い】りませんか。",furigana:"ブディさん、お茶は 要りませんか。",romaji:"Budi-san, ocha wa irimasen ka.",idText:"Budi-san, apakah tidak butuh teh hijau?"},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"あ、そうですね！温【あたた】かい お茶【ちゃ】を 一本【いっぽん】 ください。",furigana:"あ、そうですね！温かい お茶を 一本 ください。",romaji:"A, sou desu ne! Atatakai ocha o ippon kudasai.",idText:"Ah, betul juga ya! Tolong satu botol teh hangat."}],vocab_breakdown:[{id:"v1",word:"ひとつ",reading:"ひとつ",romaji:"hitotsu",meaning:"satu buah (satuan umum barang)",nuance:"Bilangan asli Jepang. Ditulis dengan kanji 一つ.",exampleSentence:{jp:"りんごを ひとつ ください。",furigana:"りんごを 一つ ください。",romaji:"Ringo o hitotsu kudasai.",idText:"Tolong berikan satu buah apel."}},{id:"v2",word:"ふたつ",reading:"ふたつ",romaji:"futatsu",meaning:"dua buah",nuance:"Bilangan asli Jepang. Ditulis dengan kanji 二つ.",exampleSentence:{jp:"パンを ふたつ かいました。",furigana:"パンを 二つ 買いました。",romaji:"Pan o futatsu kaimashita.",idText:"Saya membeli dua buah roti."}},{id:"v3",word:"みっつ",reading:"みっつ",romaji:"mittsu",meaning:"tiga buah",nuance:"Bilangan asli Jepang. Ada sokuon (konsonan ganda t). Ditulis 三つ.",exampleSentence:{jp:"たまごを みっつ ください。",furigana:"卵を 三つ ください。",romaji:"Tamago o mittsu kudasai.",idText:"Tolong beri saya tiga butir telur."}},{id:"v4",word:"ください",reading:"ください",romaji:"kudasai",meaning:"tolong berikan (minta barang konkret)",nuance:"Bentuk sopan dari kureru. Dipakai saat meminta barang fisik dari penjual.",exampleSentence:{jp:"みずを ください。",furigana:"水を ください。",romaji:"Mizu o kudasai.",idText:"Tolong beri saya air putih."}},{id:"v5",word:"おねがいします",reading:"おねがいします",romaji:"onegaishimasu",meaning:"tolong ya / mohon bantuannya",nuance:"Lebih santun dan formal daripada kudasai. Cocok untuk memesan makanan di restoran atau meminta jasa.",exampleSentence:{jp:"これ、おねがいします。",furigana:"これ、お願いします。",romaji:"Kore, onegaishimasu.",idText:"Yang ini ya tolong."}}],explanations:[{id:"e1",title:"1. Pola Memesan Barang: [Benda] を [Jumlah] ください",formula:"[Kata Benda] + を + [Kata Bantu Bilangan] + ください / お願いします",meaning:"Tolong berikan saya [benda] sebanyak [jumlah].",nuanceNotes:'Perhatikan urutan gramatikalnya: Partikel を diletakkan tepat setelah kata benda barangnya, BUKAN setelah angka jumlahnya. Contoh: "Kohi o hitotsu kudasai" (Benar), bukan "Kohi hitotsu o kudasai".',examples:[{jp:"おにぎりを ふたつ ください。",furigana:"おにぎりを 二つ ください。",romaji:"Onigiri o futatsu kudasai.",idText:"Tolong beri saya dua onigiri."},{jp:"みずを いっぱいき おねがいします。",furigana:"水を 一杯 お願いします。",romaji:"Mizu o ippai onegaishimasu.",idText:"Tolong satu gelas air putih."}]},{id:"e2",title:"2. Tangga Bilangan Asli Jepang 1 sampai 10 (〜つ)",formula:"ひとつ(1), ふたつ(2), みっつ(3), よっつ(4), いつつ(5), むっつ(6), ななつ(7), やっつ(8), ここのつ(9), とお(10)",meaning:"Menghitung satuan barang umum (buah, roti, piring, tas, kursi, pesanan makanan).",nuanceNotes:"Semua berakhiran -tsu kecuali nomor 10 yang berbunyi とお (tou - panjang). Ingat ada bunyi kembar sokuon pada angka 3 (mittsu), 4 (yottsu), 6 (muttsu), dan 8 (yattsu).",examples:[{jp:"りんごを よっつ かいました。",furigana:"りんごを 四つ 買いました。",romaji:"Ringo o yottsu kaimashita.",idText:"Saya membeli empat buah apel."}]},{id:"e3",title:"3. Perbedaan Nuansa: ください (Kudasai) vs お願いします (Onegaishimasu)",formula:"[Benda] を ください vs [Benda / Menu] を お願いします",meaning:"Kudasai = minta diserahkan barang fisik. Onegaishimasu = mohon tolong diproses/dilayani.",nuanceNotes:"Di restoran atau konbini saat meminta pelayan memanaskan bento atau mencatatkan pesanan menu, frasa お願いします (onegaishimasu) terdengar jauh lebih sopan dan alami bagi pelanggan.",examples:[{jp:"これ、あたためを おねがいします。",furigana:"これ、温めを お願いします。",romaji:"Kore, atatame o onegaishimasu.",idText:"Yang ini tolong dihangatkan ya."}]}],drills:[{id:"drill-u05-01-1",type:"vocab_context",instruction:"Pilihlah jumlah barang yang tepat untuk kata: 「みっつ (mittsu)」",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["3 buah","2 buah","6 buah","8 buah"],correctAnswer:"3 buah",explanation:"ひとつ (1), ふたつ (2), みっつ (3). Mittsu artinya 3 buah.",diagnosticFeedback:{"2 buah":"2 buah adalah ふたつ (futatsu).","6 buah":"6 buah adalah むっつ (muttsu) - waspadai beda vokal i dan u!","8 buah":"8 buah adalah やっつ (yattsu)."}},{id:"drill-u05-01-2",type:"cloze",instruction:"Lengkapilah urutan pemesanan di kasir: 「パン（　）ふたつ ください。」",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["を","が","に","で"],correctAnswer:"を",explanation:"Roti (pan) adalah objek yang dipesan, partikel yang menghubungkan benda dengan verba kudasai adalah を.",diagnosticFeedback:{が:"Partikel が digunakan untuk subjek atau pola arimasu/imasu, bukan memesan barang dengan kudasai.",に:"Partikel に menandai tujuan atau waktu, tidak dipakai di antara benda pesanan dan jumlah.",で:"Partikel で menandai sarana alat atau tempat aktivitas."}},{id:"drill-u05-01-3",type:"reorder",instruction:"Susunlah kata-kata acak berikut menjadi pesanan konbini yang benar: [ください] [おにぎりを] [ひとつ]",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["おにぎりを ひとつ ください。","ひとつ おにぎりを ください。","ください おにぎりを ひとつ。","おにぎり ひとつを ください。"],correctAnswer:"おにぎりを ひとつ ください。",explanation:"Urutan baku: [Nama Benda] + を + [Jumlah] + ください.",diagnosticFeedback:{"ひとつ おにぎりを ください。":"Meskipun dipahami, menaruh jumlah di depan benda kurang alami dalam percakapan kasir resmi.","ください おにぎりを ひとつ。":"Verba kudasai tidak boleh diletakkan di awal kalimat.","おにぎり ひとつを ください。":"Jebakan susunan: Partikel を ditaruh setelah benda, bukan setelah jumlah."},tokens:["おにぎりを","ひとつ","ください。"],correctOrder:["0","1","2"]},{id:"drill-u05-01-4",type:"trap_detect",instruction:"Manakah cara memesan di restoran yang SALAH atau TIDAK ALAMI bagi orang Jepang?",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["ラーメンを いち ください。","ラーメンを ひとつ ください。","ラーメンを ひとつ おねがいします。","おみずを ふたつ ください。"],correctAnswer:"ラーメンを いち ください。",explanation:"Menyebut jumlah pesanan satuan memakai angka kardinal biasa (ichi) adalah kesalahan umum. Harus memakai bilangan asli ひとつ (hitotsu).",diagnosticFeedback:{"ラーメンを ひとつ ください。":"Pemesanan ini 100% tepat dan alami.","ラーメンを ひとつ おねがいします。":"Pemesanan ini sangat santun dan alami.","おみずを ふたつ ください。":"Pemesanan ini tepat (meminta dua gelas air)."}},{id:"drill-u05-01-5",type:"response",instruction:"Pelayan restoran bertanya: 「ごちゅうもんは？」 (Mau pesan apa?). Jika kamu ingin memesan 2 mangkuk ramen dan 1 teh hijau, bagaimana mengatakannya?",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["ラーメンを ふたつと、おちゃを ひとつ おねがいします。","ラーメンを にと、おちゃを いち ください。","ラーメンが ふたつ あります。","おちゃを たべます。"],correctAnswer:"ラーメンを ふたつと、おちゃを ひとつ おねがいします。",explanation:"Dua ramen: ramen o futatsu to, satu teh: ocha o hitotsu, diakhiri sopan: onegaishimasu.",diagnosticFeedback:{"ラーメンを にと、おちゃを いち ください。":'Fatal: Memakai angka kardinal "ni" dan "ichi" untuk memesan porsi makanan.',"ラーメンが ふたつ あります。":'Salah pola: Malah menyatakan keberadaan "ada dua ramen", bukan memesan.',"おちゃを たべます。":"Salah verba: Teh diminum (nomimasu), bukan dimakan (tabemasu)."}}],can_do_challenge:{statement:"Bisa memesan aneka menu makanan dan minuman secara mandiri di restoran atau konbini Jepang.",situation:"Sedang memesan makan siang di kasir kedai makanan cepat saji atau konbini.",promptTask:"Pesanlah 1 bento dan 2 botol teh hijau dengan sopan menggunakan pola onegaishimasu!",modelAnswer:"べんとうを ひとつと、おちゃを にほん おねがいします。",modelAnswerId:"Tolong satu bento dan dua botol teh hijau ya.",culturalEtiquette:"Ucapkan dengan kontak mata sopan kepada kasir dan letakkan uang di nampan kasir.",skillUnlocked:["Menguasai tangga hitungan asli Jepang (hitotsu hingga tou)","Mampu menyusun kalimat pemesanan benda yang tepat dengan partikel を","Menguasai pemakaian kudasai dan onegaishimasu secara percaya diri"],pocketSummary:{keyFormula:"[Benda] を [Jumlah] ください / おねがいします",coreWords:["ひとつ (1 buah)","ふたつ (2 buah)","みっつ (3 buah)","ください (tolong beri)","おねがいします (tolong/mohon)"],coreWarning:"JANGAN pakai ichi/ni untuk pesan makanan! Gunakan hitotsu/futatsu. Partikel を letaknya setelah nama benda!",quickDialogue:"A: なにを かいますか？ → B: おにぎりを ふたつ ください。"}},pocket_summary:{keyFormula:"[Benda] を [Hitotsu/Futatsu] ください",coreWords:["ひとつ (1)","ふたつ (2)","みっつ (3)","ください (tolong)","おねがいします (mohon)"],coreWarning:"Gunakan hitotsu/futatsu (bukan ichi/ni) saat memesan makanan di kasir!",quickDialogue:"A: ごちゅうもんは？ → B: これを ひとつ おねがいします。"}}},u={"les-n5-u08-01":{pedagogical_framework:{what:{summary:"Kata sifat-na (形容動詞), partikel penghubung な sebelum kata benda, dan bentuk sangkalan 〜ではありません / 〜じゃありません.",canDo:"Bisa mendeskripsikan kota, asrama, atau ruangan yang tenang, bersih, dan praktis.",targetPatterns:["[Na-Adj] な [Kata Benda]","[Na-Adj] です","[Na-Adj] ではありません / じゃありません"],coreVocabSample:["しずか","きれい","べんり","へや","まち","ゆうめい"]},sensei_context:{sceneIntro:"Budi menceritakan kesan tinggal di kamar asrama barunya kepada Sakura. Kamarnya bersih dan lingkungannya tenang.",dailyMission:"Gunakan kata sifat-na dengan partikel な saat memodifikasi kata benda, dan sangkal dengan ではありません.",whyOrder:"Setelah menguasai kata sifat-i (Unit 7), sekarang kita kuasai pasangan kembarannya: kata sifat-na!"},cultural_notes:{title:"Konsep Kebersihan & Ketenangan (Kirei & Shizuka) di Hunian Jepang",etiquette:"Di asrama atau apartemen Jepang, jam malam (Mansion Manners) menuntut keheningan setelah pukul 21.00 demi kenyamanan tetangga.",taboos:'Hati-hati dengan kata "きれい (kirei)"! Walau berakhiran -i, Kirei adalah KATA SIFAT-NA murni! Bentuk modifikasinya adalah "kirei na", bukan "kirei heya"!'},pronunciation_tips:{title:"Jebakan Kata Sifat Kirei (きれい)",moraNote:'Kata きれい (ki-re-i) memiliki 3 mora. Sangkalannya adalah "kirei dewa arimasen", BUKAN "kirekunai"!',soundTip:'Katakan "kirei na heya" dengan partikel na terdengar jelas.'},common_pitfalls:[{title:"Menganggap きれい (Kirei) sebagai Kata Sifat-i",caseScenario:"Mengubah bentuk kirei menjadi kirekunai atau kirei heya.",pitfallWarning:'"きれいくない です。" / "きれい へや" (Salah Besar)',rightSolution:'"きれい ではありません。" / "きれい な へや" (Benar)',explanation:"Kirei adalah kata sifat-na semu (berakhiran i). Wajib diperlakukan sebagai na-adj!"},{title:"Lupa Menyisipkan な Sebelum Kata Benda",caseScenario:'Menempelkan shizuka langsung ke heya: "shizuka heya".',pitfallWarning:'"しずか へや です。" (Salah)',rightSolution:'"しずか な へや です。" (Benar)',explanation:'Kata sifat-na WAJIB memakai jembatan "な" sebelum menempel ke kata benda.'}],who_and_when:{situational_context:"Menceritakan fasilitas asrama, lingkungan tempat tinggal, atau tempat wisata.",social_relations:"Ragam sopan standar (Teineigo) yang sangat elegan dipakai kepada siapa pun.",when_not_to_use:'Jangan memakai ragam kasual "da / janai" kepada atasan atau orang baru.'},scenario:{title:"Mendiskusikan Kamar Asrama Baru",setting:"Ruang istirahat kantor, pukul 13.00",narrative:"Sakura menanyakan apakah kamar asrama Budi nyaman dan bagaimana lingkungan di sekitarnya."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"ブディさん、新【あたら】しい 寮【りょう】の 部屋【へや】はどうですか。",furigana:"ブディさん、新しい 寮の 部屋はどうですか。",romaji:"Budi-san, atarashii ryou no heya wa dou desu ka.",idText:"Budi-san, bagaimana kamar asrama barumu?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"とても 静【しず】か な 部屋【へや】です。そして、きれいです。",furigana:"とても 静か な 部屋です。そして、きれいです。",romaji:"Totemo shizuka na heya desu. Soshite, kirei desu.",idText:"Kamarnya sangat tenang. Dan juga bersih."},{id:"d3",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"駅【えき】の 近【ちか】くですか。便利【べんり】ですか。",furigana:"駅の 近くですか。便利ですか。",romaji:"Eki no chikaku desu ka. Benri desu ka.",idText:"Dekat stasiunkah? Praktis tidak?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、駅【えき】から 近【ちか】いですから、とても 便利【べんり】です。",furigana:"はい、駅から 近いですから、とても 便利です。",romaji:"Hai, eki kara chikai desu kara, totemo benri desu.",idText:"Iya, karena dekat dari stasiun, sangat praktis."},{id:"d5",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"町【まち】は にぎやかですか。",furigana:"町は にぎやかですか。",romaji:"Machi wa nigiyaka desu ka.",idText:"Apakah kotanya ramai?"},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"いいえ、あまり にぎやか ではありません。夜【よる】は 静【しず】かです。",furigana:"いいえ、あまり にぎやか ではありません。夜は 静かです。",romaji:"Iie, amari nigiyaka dewa arimasen. Yoru wa shizuka desu.",idText:"Tidak, tidak begitu ramai. Kalau malam sangat tenang."},{id:"d7",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"それは よかったですね。よく 休【やす】めますね。",furigana:"それは よかったですね。よく 休めますね。",romaji:"Sore wa yokatta desu ne. Yoku yasumemasu ne.",idText:"Syukurlah kalau begitu. Bisa istirahat dengan nyenyak ya."},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、毎日【まいにち】快適【かいてき】に 過【す】ごしています！",furigana:"はい、毎日快適に 過ごしています！",romaji:"Hai, mainichi kaiteki ni sugoshite imasu!",idText:"Iya, setiap hari saya lewati dengan nyaman!"}],vocab_breakdown:[{id:"vg-n5-00076",word:"好き",reading:"すき",romaji:"suki",meaning:"suka",pos:"na-adj",nuance:"Secara gramatikal adalah な形容詞. 〜が好き (bukan 〜を).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"音楽が好きです。",furigana:"音楽が好きです。",romaji:"",idText:"Saya suka musik."}},{id:"vg-n5-00077",word:"嫌い",reading:"きらい",romaji:"kirai",meaning:"tidak suka",pos:"na-adj",nuance:"Bisa kasar jika dipakai langsung ke orang. 〜が嫌い.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"虫が嫌いです。",furigana:"虫が嫌いです。",romaji:"",idText:"Saya tidak suka serangga."}},{id:"vg-n5-00078",word:"上手",reading:"じょうず",romaji:"jouzu",meaning:"pandai, mahir",pos:"na-adj",nuance:"Jangan pakai untuk diri sendiri — terkesan sombong. Gunakan 得意 untuk diri sendiri.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"田中さんは料理が上手ですね。",furigana:"田中さんは料理が上手ですね。",romaji:"",idText:"Tanaka-san pandai masak ya."}},{id:"vg-n5-00079",word:"下手",reading:"へた",romaji:"heta",meaning:"tidak pandai, kurang mahir",pos:"na-adj",nuance:"Bisa kasar kalau dipakai ke orang lain tanpa konteks yang tepat.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"歌が下手です。",furigana:"歌が下手です。",romaji:"",idText:"Saya tidak pandai bernyanyi."}},{id:"vg-n5-00080",word:"きれい",reading:"きれい",romaji:"kirei",meaning:"cantik; bersih",pos:"na-adj",nuance:"Dua arti: cantik/indah dan bersih. Perhatikan konteks.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"この花はきれいですね。",furigana:"この花はきれいですね。",romaji:"",idText:"Bunga ini cantik ya."}},{id:"vg-n5-00081",word:"静か",reading:"しずか",romaji:"shizuka",meaning:"tenang, hening",pos:"na-adj",nuance:"Describes peaceful environments, silence, or a calm personality. It's a na-adjective, meaning you must append 'na' when directly modifying a noun.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"この図書館は静かです。",furigana:"この図書館は静かです。",romaji:"",idText:"Perpustakaan ini tenang."}},{id:"vg-n5-00082",word:"賑やか",reading:"にぎやか",romaji:"nigiyaka",meaning:"ramai, meriah",pos:"na-adj",nuance:"Na-adjective meaning 'lively' or 'bustling.' Describes places full of energy: 賑やかな街 (a lively town). Positive connotation, unlike うるさい (noisy).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"渋谷はにぎやかです。",furigana:"渋谷はにぎやかです。",romaji:"",idText:"Shibuya itu ramai."}},{id:"vg-n5-00083",word:"大切",reading:"たいせつ",romaji:"taisetsu",meaning:"penting, berharga",pos:"na-adj",nuance:"Refers to something highly valued or carefully treated, often with an emotional attachment. It's a na-adjective and commonly used when telling someone to take care.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"健康が大切です。",furigana:"健康が大切です。",romaji:"",idText:"Kesehatan itu penting."}},{id:"vg-n5-00167",word:"同じ",reading:"おなじ",romaji:"onaji",meaning:"sama, serupa",pos:"na-adj",nuance:"Unik: adj-na tapi tidak pakai な saat atributif (同じ学校, bukan 同じな学校).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"私たちは同じ学校に通っています。",furigana:"私たちは同じ学校に通っています。",romaji:"",idText:"Kami bersekolah di sekolah yang sama."}},{id:"vg-n5-00259",word:"ひま",reading:"ひま",romaji:"hima",meaning:"santai; tidak sibuk; punya waktu luang",pos:"na-adj",nuance:"A na-adjective or noun describing a state of having nothing to do or being unoccupied. It contrasts with being busy and can sometimes imply boredom.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"今週末はひまですか。",furigana:"今週末はひまですか。",romaji:"",idText:"Apakah akhir pekan ini kamu bebas?"}}],explanations:[{id:"exp-1",grammarId:"gn5-00026",title:"Pola: な-adj + です / な-adj + な + N",formula:"Adj-な + です (predikat) / Adj-な + な + N (modifikasi)",meaning:"adjektif-na (predikat & modifier)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"な-adj + です / な-adj + な + N",idText:"adjektif-na (predikat & modifier)"}],examples:[{jp:"ここはとてもしずかです。",romaji:"",idText:"Di sini sangat tenang."},{jp:"きれいなはなですね。",romaji:"",idText:"Bunga yang cantik, ya."}]},{id:"exp-2",grammarId:"gn5-00092",title:"Pola: な-adj / N + で (bentuk て)",formula:"な-adj (stem) + で / N + で",meaning:"bentuk て dari kata benda dan な-adjektif — digunakan sebagai penghubung kalimat",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"な-adj / N + で (bentuk て)",idText:"bentuk て dari kata benda dan な-adjektif — digunakan sebagai penghubung kalimat"}],examples:[{jp:"ここは静かで、きれいです。",romaji:"",idText:"Di sini tenang dan bersih."},{jp:"学生で、アルバイトもしています。",romaji:"",idText:"Saya mahasiswa dan juga kerja paruh waktu."},{jp:"便利で、安いです。",romaji:"",idText:"Nyaman dan murah."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah arti kata "静か (しずか)".',sentencePrompt:'Kata sifat "静か" berarti:',options:["Tenang / Sunyi","Ramai / Meriah","Sempit / Sesak","Kotor / Kumuh"],correctAnswer:"Tenang / Sunyi",explanation:'"静か (しずか)" berarti tenang atau hening. Lawan katanya adalah にぎやか (ramai).',diagnosticFeedback:{"Ramai / Meriah":"Salah: Ramai adalah にぎやか (nigiyaka).","Sempit / Sesak":"Salah: Sempit adalah 狭い (semai).","Kotor / Kumuh":"Salah: Kotor adalah 汚い (kitanai)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Isian Jembatan Na): Pilihlah partikel penyambung kata sifat-na ke nomina.",sentencePrompt:"ここは とても きれい _____ 部屋【へや】ですね。",options:["な","い","の","に"],correctAnswer:"な",explanation:'Kata sifat-na (きれい) membutuhkan jembatan "な" sebelum menerangkan kata benda: きれい な 部屋.',diagnosticFeedback:{い:"Salah Fatal: きれい bukan kata sifat-i!",の:"Salah: Partikel の menghubungkan kata benda dengan kata benda, bukan na-adj.",に:"Salah: Partikel に mengubahnya menjadi adverbia (secara bersih), bukan menyifati benda."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Urutkan kalimat yang mendeskripsikan kota yang praktis berikut.",sentencePrompt:"Susunan kalimat yang tepat:",options:["ここは とても 便利【べんり】な 町【まち】です","町【まち】です ここは 便利【べんり】な とても","とても 便利【べんり】です ここは な町【なまち】","ここは 便利【べんり】町【まち】です とても"],correctAnswer:"ここは とても 便利【べんり】な 町【まち】です",explanation:"Subjek (ここは) + Adverbia (とても) + Kata Sifat-na Modifikasi (便利な 町です).",diagnosticFeedback:{"町【まち】です ここは 便利【べんり】な とても":"Jebakan: Susunan kata acak terbalik.","とても 便利【べんり】です ここは な町【なまち】":"Jebakan: Partikel な dipisah sembarangan.","ここは 便利【べんり】町【まち】です とても":"Jebakan: Lupa menyisipkan partikel な."},tokens:["ここは","とても","便利【べんり】な","町【まち】です"],correctOrder:["0","1","2","3"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Jebakan): Pilihlah bentuk sangkalan kata sifat-na yang benar.",sentencePrompt:'Manakah bentuk sangkalan untuk kata "きれい" yang benar?',options:["この 部屋【へや】は きれい ではありません。","この 部屋【へや】は きれいくない です。","この 部屋【へや】は きれい ない です。","この 部屋【へや】は きれい じゃなかった です。"],correctAnswer:"この 部屋【へや】は きれい ではありません。",explanation:"Sangkalan sopan kata sifat-na adalah [Na-adj] + ではありません / じゃありません.",diagnosticFeedback:{"この 部屋【へや】は きれいくない です。":'Jebakan Fatal: "Kirekunai" adalah kesalahan fatal karena kirei bukan kata sifat-i!',"この 部屋【へや】は きれい ない です。":"Jebakan: Pola gramatikal salah.","この 部屋【へや】は きれい じゃなかった です。":"Jebakan: Janakatta adalah bentuk lampau kasual."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat supervisor bertanya "町【まち】は にぎやかですか", jawaban sangkalan sopan yang tepat adalah:',sentencePrompt:"Pilihlah jawaban menyangkal secara halus:",options:["いいえ、あまり にぎやか ではありません。","はい、にぎやか ではありません。","町【まち】は だめです。","いいえ、にぎやか です。"],correctAnswer:"いいえ、あまり にぎやか ではありません。",explanation:'Kombinasi "いいえ、あまり ... ではありません" menyatakan sangkalan halus "tidak begitu ramai".',diagnosticFeedback:{"はい、にぎやか ではありません。":'Kontradiktif: Menjawab "ya" tetapi predikatnya menyangkal.',"町【まち】は だめです。":"Terlalu kasar dan tidak menjawab pertanyaan karakteristik.","いいえ、にぎやか です。":'Kontradiktif: Menjawab "tidak" tetapi predikatnya positif.'}}],can_do_challenge:{statement:"Bisa mendeskripsikan kondisi tempat tinggal dan kamar asrama secara jelas.",situation:"Menceritakan fasilitas asrama kepada senior kerja.",promptTask:"Katakan bahwa kamarmu bersih dan tenang, serta kotanya sangat praktis!",modelAnswer:"私【わたし】の 部屋【へや】は きれいで 静【しず】かです。そして、とても 便利【べんり】な 町【まち】です。",modelAnswerId:"Kamar saya bersih dan tenang. Dan juga, kotanya sangat praktis.",culturalEtiquette:"Gunakan jembatan な sebelum kata benda dan akhiran です yang sopan.",skillUnlocked:["Menguasai konjugasi kata sifat-na","Menghindari jebakan semu kata kirei"]},pocket_summary:{keyFormula:"[Na-Adj] な [Kata Benda] / [Na-Adj] ではありません",coreWords:["しずか","きれい","べんり","にぎやか"],coreWarning:'"きれい" adalah kata sifat-na! Sangkalannya "きれいではありません", bukan "きれいくない".',quickDialogue:"A: 部屋は どうですか。 → B: 静かで きれいな 部屋です。"}},"les-n5-u08-02":{pedagogical_framework:{what:{summary:"Menyatakan kemahiran dan ketidakterampilan dengan 上手 (jouzu) / 下手 (heta), partikel objek penanda sifat が, serta derajat adverbia とても (sangat) dan あまり (tidak begitu - diikuti bentuk negatif).",canDo:"Bisa mengutarakan kemahiran bahasa Jepang, hobi olahraga/memasak, dan merendah secara sopan.",targetPatterns:["[Keterampilan] が 上手 / 下手 です","あまり [Bentuk Negatif]","とても [Bentuk Positif]"],coreVocabSample:["じょうず","へた","りょうり","にほんご","とても","あまり"]},sensei_context:{sceneIntro:'Saat jam istirahat atau makan bersama, rekan Jepang memuji "Nihongo ga jouzu desu ne!". Budi belajar merespons pujian dengan etika merendah.',dailyMission:'Gunakan partikel が untuk menandai subjek kemahiran (Jouzu/Heta), dan gunakan "amari ... masen" untuk merendah secara wajar.',whyOrder:"Memuji orang lain dan merespons pujian adalah etika sosial paling krusial dalam interaksi interpersonal di Jepang."},cultural_notes:{title:"Etika Merespons Pujian di Jepang (謙譲 - Kenjou)",etiquette:'Saat dipuji "Nihongo ga jouzu desu ne", orang Jepang tidak langsung bilang "Arigatou". Respons paling alami adalah merendah dengan lambaian tangan kecil: "Iie, mada mada desu" (Belum apa-apa kok).',taboos:'Jangan pernah memuji diri sendiri dengan kata 上手 (jouzu)! Mengatakan "Watashi wa nihongo ga jouzu desu" terdengar sangat sombong.'},pronunciation_tips:{title:"Pelafalan Pasangan Jouzu dan Heta",moraNote:"Jouzu memiliki vokal panjang ou (jo-u-zu, 3 mora). Heta dilafalkan pendek rata (he-ta, 2 mora).",soundTip:'Katakan "amari wakarimasen" dengan nada menurun lembut.'},common_pitfalls:[{title:"Memuji Diri Sendiri Menggunakan Kata 上手 (Jouzu)",caseScenario:"Mengatakan bahwa diri sendiri pandai.",pitfallWarning:'"わたし は にほんご が じょうず です。" (Sombong)',rightSolution:'"まだまだ です。" atau "すこし はなせます。"',explanation:"Kata 上手 (jouzu) secara etika sosial hanya dipakai untuk memuji orang lain."},{title:'Memasangkan "あまり (Amari)" dengan Bentuk Positif',caseScenario:"Menggunakan amari dengan kalimat afirmatif.",pitfallWarning:'"あまり わかります。" (Salah)',rightSolution:'"あまり わかりません。" (Benar - Wajib Negatif)',explanation:"Kata keterangan あまり (amari) WAJIB selalu diikuti predikat sangkalan/negatif."}],who_and_when:{situational_context:"Mengobrol tentang hobi, merespons pujian bahasa Jepang, atau memesan makanan di pesta kantor.",social_relations:"Sangat wajar dipakai dalam percakapan santai maupun semiformal di tempat kerja.",when_not_to_use:'Jangan katakan heta kepada atasan ("Tanaka-san wa heta desu" sangat menghina).'},scenario:{title:"Pujian Kemampuan Bahasa Jepang di Kafetaria",setting:"Meja makan kafetaria siang hari, pukul 12.30",narrative:"Sakura memuji pelafalan bahasa Jepang Budi yang terdengar semakin fasih dan lancar."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"ブディさん、日本語【にほんご】の 発音【はつおん】が とても 上手【じょうず】ですね！",furigana:"ブディさん、日本語の 発音が とても 上手ですね！",romaji:"Budi-san, nihongo no hatsuon ga totemo jouzu desu ne!",idText:"Budi-san, pelafalan bahasa Jepangmu sangat pandai ya!"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"いいえ、まだまだです。漢字【かんじ】は あまり 分【わ】かりません。",furigana:"いいえ、まだまだです。漢字は あまり 分かりません。",romaji:"Iie, mada mada desu. Kanji wa amari wakarimasen.",idText:"Wah belum apa-apa kok. Kalau huruf kanji saya belum begitu paham."},{id:"d3",speaker:"Sakura",speakerRole:"Rekan Kerja",avatar:"👩‍💼",jp:"でも、会話【かいわ】は とても 上手【じょうず】ですよ。料理【りょうり】も 好【す】きですか。",furigana:"でも、会話は とても 上手ですよ。料理も 好きですか。",romaji:"Demo, kaiwa wa totemo jouzu desu yo. Ryouri mo suki desu ka.",idText:"Tapi percakapanmu sangat bagus lho. Apakah kamu suka memasak juga?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、料理【りょうり】が 大好【だいす】きです。インドネシア料理【りょうり】を よく 作【つく】ります。",furigana:"はい、料理が 大好きです。インドネシア料理を よく 作ります。",romaji:"Hai, ryouri ga daisuki desu. Indonesia ryouri o yoku tsukurimasu.",idText:"Iya, saya suka sekali memasak. Saya sering membuat masakan Indonesia."},{id:"d5",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"いいなあ！ナシゴレンとか？俺【おれ】は 料理【りょうり】が 下手【へた】なんだ。",furigana:"いいなあ！ナシゴレンとか？俺は 料理が 下手なんだ。",romaji:"Ii naa! Nashigoren toka? Ore wa ryouri ga heta nan da.",idText:"Wah asyik banget! Nasi goreng misalnya? Kalau aku payah banget masak."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"今度【こんど】 寮【りょう】で 一緒【いっしょ】に 食【た】べましょう！作【つく】りますよ。",furigana:"今度 寮で 一緒に 食べましょう！作りますよ。",romaji:"Kondo ryou de issho ni tabemashou! Tsukurimasu yo.",idText:"Lain kali mari kita makan bareng di asrama! Saya buatkan ya."},{id:"d7",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"やった！楽【たの】しみに しているよ。",furigana:"やった！楽しみに しているよ。",romaji:"Yatta! Tanoshimi ni shite iru yo.",idText:"Asyik! Aku tunggu-tunggu ya."},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、ぜひ 食【た】べてみてください！",furigana:"はい、ぜひ 食べてみてください！",romaji:"Hai, zehi tabete mite kudasai!",idText:"Baik, silakan nanti dicoba ya!"}],vocab_breakdown:[{id:"vg-n5-00516",word:"下手な",reading:"へたな",romaji:"hetana",meaning:"tidak pandai",pos:"na-adj",nuance:"Lawan kata: 上手な skillful",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"私は歌が下手ですから、歌いません。",furigana:"私は歌が下手ですから、歌いません。",romaji:"",idText:"Karena saya tidak pandai bernyanyi, saya tidak bernyanyi."}},{id:"vg-n5-00606",word:"ひまな",reading:"ひまな",romaji:"himana",meaning:"santai, tidak sibuk",pos:"na-adj",nuance:"ひまな (暇な) = tidak sibuk/punya waktu luang. 暇つぶし = mengisi waktu luang.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"今週末はひまです。いっしょにどうですか。",furigana:"今週末はひまです。いっしょにどうですか。",romaji:"",idText:"Akhir pekan ini saya bebas. Bagaimana kalau bersama?"}},{id:"vg-n5-00607",word:"きらいな",reading:"きらいな",romaji:"kiraina",meaning:"tidak suka, benci",pos:"na-adj",nuance:"Lawan kata: すきな (favorite/like)",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"野菜がきらいですから、食べません。",furigana:"野菜がきらいですから、食べません。",romaji:"",idText:"Karena saya tidak suka sayur, saya tidak memakannya."}},{id:"vg-n5-00608",word:"すきな",reading:"すきな",romaji:"sukina",meaning:"suka, favorit",pos:"na-adj",nuance:"すきな (好きな) = suka. Derajat: 大好き > 好き > まあまあ好き. Lawan: 嫌い.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"日本語が好きです。",furigana:"日本語が好きです。",romaji:"",idText:"Saya suka bahasa Jepang."}},{id:"vg-n5-00720",word:"暇",reading:"ひま",romaji:"hima",meaning:"waktu luang; tidak sibuk",pos:"na-adj",nuance:"Bisa berarti punya waktu luang (positif) atau tidak ada kegiatan (bisa negatif tergantung konteks).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"暇なとき, 何をしますか。",furigana:"暇なとき, 何をしますか。",romaji:"",idText:"Kalau punya waktu luang, kamu ngapain?"}},{id:"vg-n5-00723",word:"大変",reading:"たいへん",romaji:"taihen",meaning:"sangat; parah; berat",pos:"na-adj",nuance:"Sebagai kata sifat: situasi yang berat/susah. Sebagai adverb: sangat/amat.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"大変でしたね。",furigana:"大変でしたね。",romaji:"",idText:"Berat ya keadaannya."}},{id:"vg-n5-00724",word:"有名",reading:"ゆうめい",romaji:"yuumei",meaning:"terkenal; termasyhur",pos:"na-adj",nuance:"A na-adjective for something widely recognized. As the base form, it requires 'na' when modifying nouns and conjugates like a noun at the end of a sentence.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"あの歌手はとても有名です。",furigana:"あの歌手はとても有名です。",romaji:"",idText:"Penyanyi itu sangat terkenal."}},{id:"vg-n5-00745",word:"嫌",reading:"いや",romaji:"iya",meaning:"tidak suka, enggan, benci, tidak menyenangkan",pos:"na-adj",nuance:"Menyatakan keengganan kuat atau rasa tidak suka secara emosional dan spontan (contoh: 嫌だ！ / Tidak mau!). Bersifat lebih personal dan subyektif daripada 嫌い (kirai - kata sifat menyatakan preferensi tidak suka secara umum).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"雨の日に出かけるのは嫌です。",furigana:"雨の日に出かけるのは嫌です。",romaji:"",idText:"Saya tidak suka (enggan) bepergian pada hari hujan."}},{id:"vg-n5-00788",word:"結構",reading:"けっこう",romaji:"kekkou",meaning:"cukup, lumayan; sudah cukup (menolak dengan halus)",pos:"na-adj",nuance:"Memiliki dua pemakaian utama: (1) sebagai cara sopan untuk menolak tawaran tambahan yang berarti 'sudah cukup / tidak perlu lagi' (結構です), dan (2) sebagai kata keterangan yang berarti 'lumayan / cukup' di luar dugaan pembicara.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"お茶のおかわりはいかがですか。いいえ、もう結構です。",furigana:"お茶のおかわりはいかがですか。いいえ、もう結構です。",romaji:"",idText:"Mau tambah teh lagi? Tidak, terima kasih, sudah cukup."}},{id:"vg-n5-00805",word:"こんな",reading:"こんな",romaji:"konna",meaning:"seperti ini, yang semacam ini",pos:"na-adj",nuance:"Menerangkan kata benda berikutnya untuk menunjukkan sifat, rupa, atau kondisi yang mirip dengan contoh di dekat pembicara. Berpasangan dengan そんな (seperti itu) dan あんな (seperti itu di sana).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"こんな美味しい料理は初めて食べました。",furigana:"こんな美味しい料理は初めて食べました。",romaji:"",idText:"Ini pertama kalinya saya menyantap masakan seenak ini."}}],explanations:[{id:"exp-1",grammarId:"gn5-00091",title:"Pola: N が わかります / できます",formula:"N + が + わかります atau できます",meaning:"mengerti N / bisa melakukan N",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"N が わかります / できます",idText:"mengerti N / bisa melakukan N"}],examples:[{jp:"日本語が少しわかります。",romaji:"",idText:"Saya sedikit mengerti bahasa Jepang."},{jp:"料理ができます。",romaji:"",idText:"Saya bisa memasak."},{jp:"漢字があまりわかりません。",romaji:"",idText:"Saya kurang paham kanji."}]},{id:"exp-2",grammarId:"gn5-00084",title:"Pola: な A- に",formula:"な-adjective (stem) + に",meaning:"dengan cara yang [na-adj] — bentuk adverbia",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"な A- に",idText:"dengan cara yang [na-adj] — bentuk adverbia"}],examples:[{jp:"丁寧に書いてください。",romaji:"",idText:"Tolong tulis dengan rapi."},{jp:"静かにしてください。",romaji:"",idText:"Tolong tenang."},{jp:"親切に教えてくれました。",romaji:"",idText:"Beliau mengajar dengan baik hati."}]},{id:"exp-3",grammarId:"gn5-00041",title:"Pola: 〜たがる",formula:"V-ます語幹 + たがる",meaning:"sepertinya ingin melakukan ... (orang ketiga)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜たがる",idText:"sepertinya ingin melakukan ... (orang ketiga)"}],examples:[{jp:"こどもはおかしをたべたがっています。",romaji:"",idText:"Anak itu sepertinya ingin makan kue."},{jp:"かれはもっとねむりたがっている。",romaji:"",idText:"Sepertinya dia ingin tidur lebih lama."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah arti kata "下手 (へた)".',sentencePrompt:'Kata "下手" dalam konteks keterampilan bermakna:',options:["Kurang pandai / Tidak mahir","Sangat ahli","Suka sekali","Cepat bosan"],correctAnswer:"Kurang pandai / Tidak mahir",explanation:'"下手 (へた)" berarti tidak mahir atau kurang terampil.',diagnosticFeedback:{"Sangat ahli":"Salah: Sangat ahli adalah 得意 (tokui) atau 上手.","Suka sekali":"Salah: Suka sekali adalah 大好き (daisuki).","Cepat bosan":"Salah: Cepat bosan adalah 飽きっぽい (akippoi)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Isian Partikel Kemahiran): Pilihlah partikel penanda bidang kemahiran.",sentencePrompt:"ケンジさんは 料理【りょうり】 _____ 下手【へた】です。",options:["が","を","に","で"],correctAnswer:"が",explanation:"Objek bidang kemahiran/ketidakterampilan (上手 / 下手) selalu ditandai partikel が.",diagnosticFeedback:{を:"Salah: Partikel を menandai objek kata kerja transitif, bukan kata sifat kemahiran.",に:"Salah: Partikel に menandai tujuan atau titik waktu.",で:"Salah: Partikel で menandai tempat berlangsungnya aksi."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Urutkan ungkapan kerendahan hati berikut.",sentencePrompt:"Susunan kalimat yang tepat:",options:["漢字【かんじ】は あまり 分【わ】かりません","あまり 漢字【かんじ】は 分【わ】かりません","分【わ】かりません 漢字【かんじ】は あまり","漢字【かんじ】は 分【わ】かります あまり"],correctAnswer:"漢字【かんじ】は あまり 分【わ】かりません",explanation:"Topik (漢字は) + Adverbia (あまり) + Predikat Negatif (分かりません).",diagnosticFeedback:{"あまり 漢字【かんじ】は 分【わ】かりません":"Kurang lazim: Topik kalimat sebaiknya ditaruh paling depan.","分【わ】かりません 漢字【かんじ】は あまり":"Jebakan: Kata kerja ditaruh di awal kalimat.","漢字【かんじ】は 分【わ】かります あまり":'Jebakan Fatal: "Amari" wajib berpasangan dengan bentuk negatif!'},tokens:["漢字【かんじ】は","あまり","分【わ】かりません"],correctOrder:["0","1","2"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Jebakan): Manakah respons merespons pujian bahasa Jepang yang paling alami dan santun?",sentencePrompt:'Saat dipuji "日本語が上手ですね", respon terbaik adalah:',options:["いいえ、まだまだです。","はい、とても 上手【じょうず】です。","私【わたし】は 天才【てんさい】です。","どういたしまして、知【し】っています。"],correctAnswer:"いいえ、まだまだです。",explanation:'"いいえ、まだまだです" (Belum kok, masih belum apa-apa) adalah respons kerendahan hati standar Jepang.',diagnosticFeedback:{"はい、とても 上手【じょうず】です。":"Jebakan Fatal: Sangat sombong dan memuji diri sendiri.","私【わたし】は 天才【てんさい】です。":"Sangat tidak sopan dan arogan.","どういたしまして、知【し】っています。":"Kasar dan tidak sesuai etika kesantunan Jepang."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Saat teman berkata "料理が下手なんだ", tanggapan ramah yang tepat adalah:',sentencePrompt:"Pilihlah respon mengajak makan bersama:",options:["今度【こんど】 私【わたし】が 作【つく】りますよ。一緒【いっしょ】に 食【た】べましょう！","そうですか、だめですね。","下手【へた】ですね、さようなら。","料理【りょうり】は 食【た】べません。"],correctAnswer:"今度【こんど】 私【わたし】が 作【つく】りますよ。一緒【いっしょ】に 食【た】べましょう！",explanation:"Menawarkan untuk memasakkan dan mengajak makan bersama adalah respons pertemanan yang hangat.",diagnosticFeedback:{"そうですか、だめですね。":"Terlalu dingin dan mengejek kekurangan teman.","下手【へた】ですね、さようなら。":"Sangat kasar dan tidak sopan.","料理【りょうり】は 食【た】べません。":"Tidak nyambung dengan topik pembicaraan."}}],can_do_challenge:{statement:"Bisa mengutarakan kemahiran hobi dan merendah secara sopan saat menerima pujian.",situation:"Mengobrol santai seputar kemahiran bahasa dan memasak.",promptTask:"Merespons pujian teman dengan sopan, lalu katakan kamu suka memasak!",modelAnswer:"いいえ、まだまだです。でも、料理【りょうり】を 作【つく】るのが 好【す】きです。",modelAnswerId:"Belum kok, masih belum apa-apa. Tapi saya suka memasak makanan.",culturalEtiquette:'Ucapkan "Iie, mada mada desu" sambil tersenyum dan menggelengkan kepala ringan.',skillUnlocked:["Menguasai etika kenjou saat dipuji","Menggunakan partikel が untuk penanda bidang sifat"]},pocket_summary:{keyFormula:"[Bidang] が 上手 / 下手 です / あまり [Negatif]",coreWords:["じょうず","へた","りょうり","あまり"],coreWarning:'Jangan pernah sebut diri sendiri "jouzu". "あまり" wajib diikuti predikat negatif.',quickDialogue:"A: 日本語が上手ですね。 → B: いいえ、まだまだです。"}}};export{k as a,r as b,t as c,i as d,e,n as f,a as g,u};
